INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89273, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大人说一个人的样子很有吸引力。", "primary_collocate": null, "pronunciation": "xìng gǎn", "ipa": "ɕiŋ˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家都说这位女歌手的声音很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说那位演员的样子很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说这条红裙子穿在她身上很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑起来的样子，朋友们都说很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老师说话的声音低低的，很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐们说他留着短胡子，看上去很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跳舞的样子又自信又性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服一点也不性感，但是很舒服。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿姨们都觉得那位男演员很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他戴着眼镜的样子很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性感明星", "label": "复合"}, {"form": "性感美女", "label": "复合"}], "register": "口语", "sense_fingerprint": "成年人评价某人样子、声音很有魅力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人的身材矮，不能用来形容声音。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”可以形容声音的吸引力，符合句意。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”指东西又重又不灵活，不能形容声音。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容山坡等地形，不能形容声音。"}], "explanations": {"矮小": "体貌：“矮小”形容人的身材矮，不能用来形容声音。", "性感": "正确：“性感”可以形容声音的吸引力，符合句意。", "笨重": "语义：“笨重”指东西又重又不灵活，不能形容声音。", "陡峭": "语义：“陡峭”形容山坡等地形，不能形容声音。"}, "sentence_index": 0, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小宝宝笑起来很性感。", "explanation": "这里应该用〈可爱〉。性感指成年人对异性的吸引力，不用来形容婴儿，婴儿的样子要说可爱。"}, {"text": "这位老教授讲课很性感。", "explanation": "这里应该用〈严肃〉。性感说的是外貌或举止的吸引力，不用来形容讲课时的态度。"}, {"text": "这只小鸟的羽毛很性感。", "explanation": "这里应该用〈漂亮〉。性感指人对异性的吸引力，不用来形容动物的羽毛，羽毛好看要说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿", "is_correct": false, "explanation": "语义：“湿”指物体含水，不能形容人的样子。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，不能形容跳舞的样子。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”形容跳舞时的样子有吸引力，符合句意。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多用于声音或环境，不能用来形容舞蹈的样子。"}], "explanations": {"湿": "语义：“湿”指物体含水，不能形容人的样子。", "酸": "语义：“酸”指味道，不能形容跳舞的样子。", "性感": "正确：“性感”形容跳舞时的样子有吸引力，符合句意。", "嘈杂": "搭配：“嘈杂”多用于声音或环境，不能用来形容舞蹈的样子。"}, "sentence_index": 6, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的心很性感，大家都喜欢和她做朋友。", "explanation": "这里应该用〈善良〉。性感形容外貌或举止，不用来形容内心的品质，心地好要说善良。"}, {"text": "经理做事很性感，大家都很佩服他。", "explanation": "这里应该用〈稳重〉。性感不用来形容做事的态度，做事沉着可靠要说稳重。"}, {"text": "听到这个消息，她很性感。", "explanation": "这里应该用〈高兴〉。性感描述的是吸引力，不用来表示心情，心情愉快要说高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她那条裙子一点也性感。", "corrected_sentence": "她那条裙子一点也不性感。", "error_description": "错误：“一点也性感”。正确：“一点也不性感”。“一点也”后面表示否定时要加“不”，不能只说“一点也”加形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他穿这件外套性感。", "corrected_sentence": "他穿这件外套很性感。", "error_description": "错误：“性感”前面缺少程度副词。正确：“很性感”。形容词作谓语前一般要加“很”等程度词，只说“外套性感”像句子没说完。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
