INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人的外貌或举止对异性有吸引力。", "primary_collocate": null, "pronunciation": "xìng gǎn", "ipa": "ɕiŋ˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个模特儿穿着黑色长裙，看起来很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走路的姿势又慢又美，特别性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志选他为最性感的男明星。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女明星穿得很性感，很多男人看着她。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神很性感，让人忍不住看她。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的睡衣不贴身，一点也不性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音很低，女孩子都觉得性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，会笑的人比好看的人更性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发放下来，样子一下子变得很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个舞蹈动作很性感，让男孩子红了脸。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性感明星", "label": "复合"}, {"form": "性感美女", "label": "复合"}], "register": "中性", "sense_fingerprint": "外貌或举止对异性有吸引力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多用于声音或环境，不能用来形容人看起来的样子。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”形容模特儿的外貌有吸引力，符合句意。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，不能形容外表。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容身材结实，与穿着长裙的模特儿形象不相符。"}], "explanations": {"嘈杂": "搭配：“嘈杂”多用于声音或环境，不能用来形容人看起来的样子。", "性感": "正确：“性感”形容模特儿的外貌有吸引力，符合句意。", "酸": "语义：“酸”指味道，不能形容外表。", "粗壮": "体貌：“粗壮”形容身材结实，与穿着长裙的模特儿形象不相符。"}, "sentence_index": 0, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很性感，吃完大家都很满意。", "explanation": "这里应该用〈好吃〉。性感形容人的外貌或举止，不用来形容菜的味道，菜味道好要说好吃。"}, {"text": "这个小朋友玩得很性感，跑来跑去。", "explanation": "这里应该用〈活泼〉。性感不用来形容孩子玩耍的样子，孩子爱动、有朝气要说活泼。"}, {"text": "这些书摆得很性感，整整齐齐放在书架上。", "explanation": "这里应该用〈整洁〉。性感不用来形容书的摆放，东西摆得干净利落要说整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方", "is_correct": false, "explanation": "语义：“方”形容形状，不能用来形容人的感觉。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多用于天气或物体，不能用来形容声音带给人的感觉。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”形容声音带来的吸引力，符合句意。"}, {"text": "弯", "is_correct": false, "explanation": "语义：“弯”形容形状，不能用来形容声音。"}], "explanations": {"方": "语义：“方”形容形状，不能用来形容人的感觉。", "潮湿": "搭配：“潮湿”多用于天气或物体，不能用来形容声音带给人的感觉。", "性感": "正确：“性感”形容声音带来的吸引力，符合句意。", "弯": "语义：“弯”形容形状，不能用来形容声音。"}, "sentence_index": 6, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的价格很性感，大家都愿意来买东西。", "explanation": "这里应该用〈便宜〉。性感不用来形容价格，价格低要说便宜。"}, {"text": "这段话解释得很性感，大家都听懂了。", "explanation": "这里应该用〈清楚〉。性感不用来形容讲解的内容，说明得明白要说清楚。"}, {"text": "图书馆里很性感，大家都在学习。", "explanation": "这里应该用〈安静〉。性感不用来形容图书馆的环境，环境不吵要说安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她性感的走过舞台。", "corrected_sentence": "她性感地走过舞台。", "error_description": "错误：“性感的走”。正确：“性感地走”。“性感”修饰动词时要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的笑容性感。", "corrected_sentence": "他的笑容很性感。", "error_description": "错误：“他的笑容性感”。正确：“他的笑容很性感”。形容词作谓语前面要加“很”等程度词，只说形容词像句子没说完。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力去得到，「放弃」是不再努力去得到，二者意思相反。"}, {"text": "休息", "is_correct": false, "explanation": "不是反义词：「休息」指停下来不做事，与「争取」没有对立关系。"}, {"text": "忘记", "is_correct": false, "explanation": "不是反义词：「忘记」指不再记得，与「争取」的意思不构成对立。"}, {"text": "认识", "is_correct": false, "explanation": "不是反义词：「认识」指知道某人或某事，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力去得到，「放弃」是不再努力去得到，二者意思相反。", "休息": "不是反义词：「休息」指停下来不做事，与「争取」没有对立关系。", "忘记": "不是反义词：「忘记」指不再记得，与「争取」的意思不构成对立。", "认识": "不是反义词：「认识」指知道某人或某事，与「争取」不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
