INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争取是努力去得到想要的东西。", "primary_collocate": null, "pronunciation": "zhēng qǔ", "ipa": "ʈʂɤŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想争取一次去北京工作的机会。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要争取拿到这个奖学金。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了争取好成绩，她每天学到很晚。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李努力争取老师的同意。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在比赛中一直争取第一名。", "target_word": "争取", "complexity_tier": "T3", "furigana": "tā men zài bǐ sài zhōng yì zhí zhēng qǔ dì yī míng", "sentence_source": "generated"}, {"text": "我想争取一个星期的假期。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队正在争取进入决赛的资格。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在争取这份工作。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈同意了，因为我争取了很久。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们争取到了免费参观的机会。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争取了", "label": "完成体"}, {"form": "争取过", "label": "经历体"}, {"form": "争取到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "争取：努力去得到想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争取", "is_correct": true, "explanation": "争取 zhēng qǔ：正确答案，指努力去得到想要的东西。"}, {"text": "蒸煮", "is_correct": false, "explanation": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。"}, {"text": "蒸汽", "is_correct": false, "explanation": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。"}, {"text": "征求", "is_correct": false, "explanation": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。"}, {"text": "称取", "is_correct": false, "explanation": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}], "explanations": {"争取": "争取 zhēng qǔ：正确答案，指努力去得到想要的东西。", "蒸煮": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。", "蒸汽": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。", "征求": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。", "称取": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}, "sentence_index": null, "correct_answer": "争取"}, "level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示努力获得，与「想」和「一次机会」搭配，句意通顺。"}, {"text": "错过", "is_correct": false, "explanation": "语义：「错过」是没有赶上，与「想」的意愿相反，不说「想错过机会」。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的宾语是地点或展览，不能说「参观机会」。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的宾语是饮料，不能与「机会」搭配。"}], "explanations": {"争取": "这里的「争取」表示努力获得，与「想」和「一次机会」搭配，句意通顺。", "错过": "语义：「错过」是没有赶上，与「想」的意愿相反，不说「想错过机会」。", "参观": "搭配：「参观」的宾语是地点或展览，不能说「参观机会」。", "喝": "搭配：「喝」的宾语是饮料，不能与「机会」搭配。"}, "sentence_index": 0, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个人为这件事争取了半天，谁也不肯让步。", "explanation": "「争论」的意思：这里说的是争辩、辩论，「争取」没有这个意思，不能用于争论。"}, {"text": "他不小心争取到了一身感冒。", "explanation": "这里应该用〈染上〉。「争取」表示有意努力得到想要的东西，与「不小心」矛盾，无意间染上疾病要用「染上」。"}, {"text": "他默默争取了一场意外的车祸。", "explanation": "这里应该用〈遭遇〉。「争取」表示有意努力得到想要的东西，车祸这类不希望发生的意外不能被争取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "「争取」表示努力得到，与「正在」和「进入决赛的资格」搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语是食物，不能说「吃资格」。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的宾语是器物，不能说「修理资格」。"}, {"text": "送给", "is_correct": false, "explanation": "配价：「送给」需要接受者和被送的东西，句中缺少接受者，句子不成立。"}], "explanations": {"争取": "「争取」表示努力得到，与「正在」和「进入决赛的资格」搭配。", "吃": "搭配：「吃」的宾语是食物，不能说「吃资格」。", "修理": "搭配：「修理」的宾语是器物，不能说「修理资格」。", "送给": "配价：「送给」需要接受者和被送的东西，句中缺少接受者，句子不成立。"}, "sentence_index": 6, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在争取一个大错误。", "explanation": "这里应该用〈犯〉。「争取」的宾语应是人想要得到的好东西，「错误」不能被争取，应说「犯错误」。"}, {"text": "这块石头争取到了免费参观的机会。", "explanation": "这里应该用〈获得〉。「争取」的主语须是能主动努力的人或团体，石头不能主动争取，只能说「获得」这种被动得到的意思。"}, {"text": "他们争取了一场很大的暴雨。", "explanation": "这里应该用〈遭遇〉。「争取」指有意努力得到想要的东西，暴雨这类自然现象不由人争取，只能说「遭遇」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了争取了这个职位，她准备了很久。", "corrected_sentence": "为了争取这个职位，她准备了很久。", "error_description": "错误：「为了」引导的目的分句中，「争取」后不能加「了」。正确说法是「为了争取这个职位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直在努力争取了这份工作。", "corrected_sentence": "他一直在努力争取这份工作。", "error_description": "错误：「在……」表示正在进行，不能与完成体「了」同用，应去掉「争取」后的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。"}, {"text": "等待", "is_correct": false, "explanation": "不是反义词：「等待」指耐心地等，与「争取」没有对立关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "不是反义词：「吃饭」指进食，与「争取」不构成对立。"}, {"text": "旅行", "is_correct": false, "explanation": "不是反义词：「旅行」指外出游览，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。", "等待": "不是反义词：「等待」指耐心地等，与「争取」没有对立关系。", "吃饭": "不是反义词：「吃饭」指进食，与「争取」不构成对立。", "旅行": "不是反义词：「旅行」指外出游览，与「争取」不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
