INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "努力设法做到或得到想要的结果。", "primary_collocate": null, "pronunciation": "zhēng qǔ", "ipa": "ʈʂɤŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要争取早点儿把工作做完。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你争取明天下午到。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在争取新的客户。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想争取更多的练习时间。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家争取今年买下房子。", "target_word": "争取", "complexity_tier": "T3", "furigana": "dà jiā zhēng qǔ jīn nián mǎi xià fáng zi", "sentence_source": "generated"}, {"text": "经理争取到了一个很好的合同。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她争取每天都能睡八个小时。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们争取在天黑以前回到家。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励大家争取更好的成绩。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想争取妈妈的支持。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争取了", "label": "完成体"}, {"form": "争取过", "label": "经历体"}, {"form": "争取到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "争取：设法做到某事，或努力得到想要的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争取", "is_correct": true, "explanation": "争取 zhēng qǔ：正确答案，指设法得到。"}, {"text": "蒸煮", "is_correct": false, "explanation": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。"}, {"text": "蒸汽", "is_correct": false, "explanation": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。"}, {"text": "征求", "is_correct": false, "explanation": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。"}, {"text": "称取", "is_correct": false, "explanation": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}], "explanations": {"争取": "争取 zhēng qǔ：正确答案，指设法得到。", "蒸煮": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。", "蒸汽": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。", "征求": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。", "称取": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}, "sentence_index": null, "correct_answer": "争取"}, "level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示设法做到，与「要」和「早点儿把工作做完」搭配，句意通顺。"}, {"text": "错过", "is_correct": false, "explanation": "语义：「错过」是没有赶上，与「要」的意愿相反，不说「要错过早点儿把工作做完」。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是地点或展览，不能带「把工作做完」这样的动作结构。"}, {"text": "送给", "is_correct": false, "explanation": "配价：「送给」需要接受者，句中缺少接受者，句子不成立。"}], "explanations": {"争取": "这里的「争取」表示设法做到，与「要」和「早点儿把工作做完」搭配，句意通顺。", "错过": "语义：「错过」是没有赶上，与「要」的意愿相反，不说「要错过早点儿把工作做完」。", "参观": "搭配：「参观」的对象是地点或展览，不能带「把工作做完」这样的动作结构。", "送给": "配价：「送给」需要接受者，句中缺少接受者，句子不成立。"}, "sentence_index": 0, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位老师为教学方法争取了一下午。", "explanation": "「争论」的意思：这里说的是争辩、辩论，「争取」没有这个意思，不能用于争论。"}, {"text": "他不知不觉争取了一身病。", "explanation": "这里应该用〈得〉。「争取」表示有意努力得到，与「不知不觉」矛盾，无意间得病要用「得」。"}, {"text": "他想争取很多作业。", "explanation": "「争取」的宾语应是想要得到的好东西，「作业」不属于这一类，这里说的是「做作业」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示设法做到，与「她」和「每天都能睡八个小时」搭配，句意通顺。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：「制造」的宾语是事物，不能说「制造每天都能睡八个小时」。"}, {"text": "思考", "is_correct": false, "explanation": "搭配：「思考」的宾语是问题或想法，不能接一个状态。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：「叹息」是不及物动词，不能带「每天都能睡八个小时」这样的宾语。"}], "explanations": {"争取": "这里的「争取」表示设法做到，与「她」和「每天都能睡八个小时」搭配，句意通顺。", "制造": "搭配：「制造」的宾语是事物，不能说「制造每天都能睡八个小时」。", "思考": "搭配：「思考」的宾语是问题或想法，不能接一个状态。", "叹息": "配价：「叹息」是不及物动词，不能带「每天都能睡八个小时」这样的宾语。"}, "sentence_index": 6, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子争取到了妈妈的支持。", "explanation": "这里应该用〈获得〉。「争取」的主语须是能主动努力的人或团体，椅子不能主动争取，只能说「获得」。"}, {"text": "他一直在争取一场大雨。", "explanation": "这里应该用〈盼望〉。「争取」指努力去得到，大雨不是人能努力争取的东西，表示希望下雨应说「盼望」。"}, {"text": "他一直想争取妈妈的生气。", "explanation": "这里应该用〈惹〉。「争取」指努力得到好的、想要的东西，「生气」不能被争取，应说「惹妈妈生气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该争取了更多的时间完成任务。", "corrected_sentence": "我们应该争取更多的时间完成任务。", "error_description": "错误：「应该」表示应当，动作还未发生，「争取」后不能加「了」，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在努力争取了一个学习的机会。", "corrected_sentence": "她正在努力争取一个学习的机会。", "error_description": "错误：「正在」表示动作进行中，不能与完成体「了」同用，应去掉「争取」后的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
