INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "概括文章、新闻或作品内容的题目。", "primary_collocate": null, "pronunciation": "biāo tí", "ipa": "piɑʊ̯˥ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这篇新闻的标题很短，但很清楚。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的标题能说出文章的主要内容。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻标题让很多人点开了它。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了标题，我就知道这本书写什么。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的标题和故事内容不一样。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的标题常常只有几个字。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品标题很长，不容易记住。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，标题要能概括全文。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标题太夸张，内容却很普通。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先读标题，再决定看不看新闻。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "副标题", "label": "复合"}, {"form": "大标题", "label": "复合"}, {"form": "標題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "概括新闻、文章或作品内容的题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”指概括新闻内容的题目，这里说它“很短”“很清楚”，最合适。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是文章的题目，“这篇新闻的天气很短”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”可说深浅，不说长短，“颜色很短”不成立。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“字体”说字形、粗细，不说长短，“字体很短”不成立。"}], "explanations": {"标题": "“标题”指概括新闻内容的题目，这里说它“很短”“很清楚”，最合适。", "天气": "语义：“天气”不是文章的题目，“这篇新闻的天气很短”不通。", "颜色": "搭配：“颜色”可说深浅，不说长短，“颜色很短”不成立。", "字体": "搭配：“字体”说字形、粗细，不说长短，“字体很短”不成立。"}, "sentence_index": 0, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给这只小狗起了一个很可爱的标题。", "explanation": "这里应该用〈名字〉。“标题”指文章或新闻的题目，给小狗起名要用“名字”。"}, {"text": "这把标题写得很大，大家都能看见。", "explanation": "这里应该用〈个〉。“把”用于有柄、能拿起的东西，“标题”是文字，量词要用“个”。"}, {"text": "他给这家新开的饭馆起了一个很好听的标题。", "explanation": "这里应该用〈店名〉。“标题”是文章、新闻或作品的题目，不能用来给饭馆起名，给店起名要用“店名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”指作品的题目，这里说它“很长”“不容易记住”，合适。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不说长短，“作品价格很长”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，不属于作品，“作品脾气很长”不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或动物的高矮，作品没有身高，“作品身高很长”不通。"}], "explanations": {"标题": "“标题”指作品的题目，这里说它“很长”“不容易记住”，合适。", "价格": "搭配：“价格”说高低，不说长短，“作品价格很长”不成立。", "脾气": "语义：“脾气”是人的性情，不属于作品，“作品脾气很长”不通。", "身高": "体貌：“身高”指人或动物的高矮，作品没有身高，“作品身高很长”不通。"}, "sentence_index": 6, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个牌子的标题很有名，大家都知道。", "explanation": "这里应该用〈商标〉。“商标”是产品上的标记，“标题”是文章或作品的题目，不能用来指牌子。"}, {"text": "这首标题很好听，我每天都唱。", "explanation": "这里应该用〈个〉。量词“首”用于歌曲、诗词，“标题”是题目，不能用“首”来数。"}, {"text": "这瓶酒的标题很漂亮。", "explanation": "这里应该用〈标签〉。“标签”贴在瓶子上、写着产品信息，“标题”是文章的题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本标题很有意思。", "corrected_sentence": "这个标题很有意思。", "error_description": "“标题”的量词应该用“个”，不能用“本”（“本”用于书籍、册子）。这里说的是标题，不是书，所以“这本标题”不对，应说“这个标题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我标题改了三次。", "corrected_sentence": "我把标题改了三次。", "error_description": "错误：“标题”作“改”的受事，漏掉了“把”。正确：应说“我把标题改了三次”，用“把”把“标题”提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "移民是搬到别的国家去长久住。", "primary_collocate": null, "pronunciation": "yí mín", "ipa": "i˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "我姐姐去年移民到了美国,不打算回来了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想带着家人移民到新西兰。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后选择移民到澳大利亚。", "target_word": "移民", "complexity_tier": "T3", "furigana": "hěn duō niánqīng rén bìyè hòu xuǎnzé yí mín dào Àodàlìyà.", "sentence_source": "generated"}, {"text": "我们邻居三年前就移民德国了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是有机会,你愿意移民到别的国家吗?", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的叔叔移民法国以后,开了一家中餐馆。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小在日本长大,后来跟着父母移民到了中国。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都劝他不要移民,可是他已经决定了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办好手续以后,他们就可以移民了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学的全家都移民去了加拿大。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移民了", "label": "体标"}, {"form": "移民过", "label": "体标"}, {"form": "移民局", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词:搬到别的国家长久居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指长期迁居到另一个国家，与“不打算回来了”的语境相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指短期游玩，与“不打算回来了”所表达的长期留居相矛盾。"}, {"text": "回国", "is_correct": false, "explanation": "搭配：“回国”指返回本国，与“到了美国”的去向及“不打算回来了”相矛盾。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”指短暂拜访，与长期不回来的语境不符。"}], "explanations": {"移民": "移民指长期迁居到另一个国家，与“不打算回来了”的语境相符。", "旅游": "语义：“旅游”指短期游玩，与“不打算回来了”所表达的长期留居相矛盾。", "回国": "搭配：“回国”指返回本国，与“到了美国”的去向及“不打算回来了”相矛盾。", "访问": "语义：“访问”指短暂拜访，与长期不回来的语境不符。"}, "sentence_index": 0, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去年移民，只在德国待了两个星期。", "explanation": "这里应该用〈出国〉。移民指长期定居，只待两个星期的短期出国不能用“移民”。"}, {"text": "她每天都移民，所以很累。", "explanation": "移民是一次性的长期迁居，不能每天重复发生。"}, {"text": "他把书架移民到了客厅。", "explanation": "这里应该用〈搬〉。移民只用于人迁居到另一地长久居住，书架不能移民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到另一个国家长期居住，与“从小在日本长大，后来跟着父母到了中国”的语境相符。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指短期观光，与从小长大后长期定居的情形不符。"}, {"text": "乘车", "is_correct": false, "explanation": "语义：“乘车”只表示搭乘交通工具的一段行程，不表示长期迁居，与“后来”所指的定居语境不符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公短期外出，与“从小在日本长大”后长期定居的语境矛盾。"}], "explanations": {"移民": "移民指迁居到另一个国家长期居住，与“从小在日本长大，后来跟着父母到了中国”的语境相符。", "游览": "语义：“游览”指短期观光，与从小长大后长期定居的情形不符。", "乘车": "语义：“乘车”只表示搭乘交通工具的一段行程，不表示长期迁居，与“后来”所指的定居语境不符。", "出差": "语义：“出差”指因公短期外出，与“从小在日本长大”后长期定居的语境矛盾。"}, "sentence_index": 6, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去博物馆移民。", "explanation": "这里应该用〈参观〉。移民指搬到别的国家长久居住，去博物馆看展览不能用“移民”。"}, {"text": "他把工作移民到了别的公司。", "explanation": "移民只用于人搬到另一个国家长久居住，工作这类事物不能移民。"}, {"text": "这群候鸟每年都移民到南方。", "explanation": "这里应该用〈迁徙〉。移民只用于人，候鸟群体的迁移应当用〈迁徙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的老师去年移民局到了荷兰。", "corrected_sentence": "我的老师去年移民到了荷兰。", "error_description": "“移民局”是名词（政府机构），不能充当谓语；应为动词“移民”，即“我的老师去年移民到了荷兰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我侄子两年前移民过到了法国。", "corrected_sentence": "我侄子两年前移民到了法国。", "error_description": "“移民”后面加“过”表示曾经发生，与“到了法国”表示已完成的迁居相矛盾。正确说法是“我侄子两年前移民到了法国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迁居到外国或外地长期居住。", "primary_collocate": null, "pronunciation": "yí mín", "ipa": "i˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "他们一家十年前移民到了加拿大。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表哥打算明年移民澳大利亚。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子的教育,他们决定移民。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经移民国外很多年了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了建水库,村里的人全都移民到了外省。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外住了很久,后来决定移民,不回来了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友移民到英国以后,很少回国。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说去年有很多人移民去了新加坡。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时从北方移民到了南方。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想移民,所以正在学习英语。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移民了", "label": "体标"}, {"form": "移民过", "label": "体标"}, {"form": "移民潮", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词:迁居到外国或外地并长期居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到外国或外地长期居住，与“一家十年前到了加拿大”的语境相符。"}, {"text": "回国", "is_correct": false, "explanation": "搭配：“回国”指返回自己的国家，不能与“到了加拿大”这种去往他国的去向搭配。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”指短暂拜访，不能表示一家人长期定居在某地。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公短期外出，与“一家十年前”的长期定居不符。"}], "explanations": {"移民": "移民指迁居到外国或外地长期居住，与“一家十年前到了加拿大”的语境相符。", "回国": "搭配：“回国”指返回自己的国家，不能与“到了加拿大”这种去往他国的去向搭配。", "访问": "语义：“访问”指短暂拜访，不能表示一家人长期定居在某地。", "出差": "语义：“出差”指因公短期外出，与“一家十年前”的长期定居不符。"}, "sentence_index": 0, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次移民，只是去参加一个会议。", "explanation": "这里应该用〈出国〉。移民指长期定居，只为参加会议的短期外出不能用“移民”。"}, {"text": "他们把家具移民到了卧室。", "explanation": "移民只用于人迁居到国外或外地，家具不能移民。"}, {"text": "他上个月移民到了新小区。", "explanation": "这里应该用〈搬〉。移民指迁居到国外或外地长期居住，同一座城市里换小区不能说移民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到外国长期居住，与“朋友移民到英国以后很少回国”的语境相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指短期游览，与“很少回国”所说的长期定居不相符。"}, {"text": "派遣", "is_correct": false, "explanation": "搭配：“派遣”需要有派遣的一方，朋友不能自己派遣自己到英国。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指短时间的步行，不能用来指迁居到另一个国家。"}], "explanations": {"移民": "移民指迁居到外国长期居住，与“朋友移民到英国以后很少回国”的语境相符。", "旅游": "语义：“旅游”指短期游览，与“很少回国”所说的长期定居不相符。", "派遣": "搭配：“派遣”需要有派遣的一方，朋友不能自己派遣自己到英国。", "散步": "语义：“散步”指短时间的步行，不能用来指迁居到另一个国家。"}, "sentence_index": 6, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他暑假回老家移民。", "explanation": "这里应该用〈探亲〉。移民指长期迁居，回老家看望亲人不能用“移民”。"}, {"text": "学校把我们班的同学都移民到了别的教室。", "explanation": "移民指迁居到国外或外地长期居住，班级之间的调动不能用“移民”。"}, {"text": "这群候鸟每年都移民到南方过冬。", "explanation": "这里应该用〈迁徙〉。移民只用于人，候鸟群体的迁移应当用〈迁徙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔去年很移民到了德国。", "corrected_sentence": "我叔叔去年移民到了德国。", "error_description": "“很”是程度副词，一般修饰形容词，不能直接修饰动词“移民”。正确说法是“我叔叔去年移民到了德国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹两年前把移民到了美国。", "corrected_sentence": "我妹妹两年前移民到了美国。", "error_description": "“把”字句需要一个被处置的宾语，这里“移民”后没有宾语，结构不成立。正确说法是“我妹妹两年前移民到了美国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
