INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们现在生活的这个时代。", "primary_collocate": null, "pronunciation": "dāng dài", "ipa": "taŋ˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们生活在当代，用手机很方便。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，很多人都有手机。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的人骑马，当代的人坐飞机。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代的孩子比以前的孩子知道得多。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活在当代的我们，应该好好儿学习。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些问题，当代的我们都要面对。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，坐飞机去外国已经不难了。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道古代和当代有什么不同。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代的生活比过去好多了。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，人们每天都用网络聊天。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "当代人", "label": "复合"}, {"form": "当代史", "label": "复合"}, {"form": "當代", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当代：我们现在生活的时代，常与古代、过去相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e97b369-c5b3-4f14-9e9f-6e44fef3be27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：我们现在生活的时代，与“用手机很方便”的语境相合。"}, {"text": "石器时代", "is_correct": false, "explanation": "语义：石器时代没有手机，与“用手机很方便”直接矛盾。"}, {"text": "清朝", "is_correct": false, "explanation": "语义：清朝没有手机，与“用手机很方便”的语境矛盾。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“生活在”后接时代或地点，不能接“星期”。"}], "explanations": {"当代": "当代：我们现在生活的时代，与“用手机很方便”的语境相合。", "石器时代": "语义：石器时代没有手机，与“用手机很方便”直接矛盾。", "清朝": "语义：清朝没有手机，与“用手机很方便”的语境矛盾。", "星期": "搭配：“生活在”后接时代或地点，不能接“星期”。"}, "sentence_index": 0, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的祖先在当代就发明了造纸术。", "explanation": "这里应该用〈古代〉。祖先生活在过去，“当代”指现在，不能说祖先在当代发明了造纸术。"}, {"text": "我小时候，当代的孩子还没有电脑。", "explanation": "这里应该用〈当时〉。当代指现在这个时代，不能指我小时候的那段时间。"}, {"text": "这件文物是当代的，已经有三千年历史了。", "explanation": "这里应该用〈古代〉。“当代”指现在，不能用来指已有三千年历史的文物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：我们现在生活的时代，作状语，与“坐飞机去外国已经不难了”相合。"}, {"text": "春秋", "is_correct": false, "explanation": "语义：春秋时期还没有飞机，与“坐飞机去外国已经不难了”矛盾。"}, {"text": "西周", "is_correct": false, "explanation": "语义：西周没有飞机，与“坐飞机去外国”的情景矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "搭配：“已经”表示已经实现，不与将来的“明天”搭配。"}], "explanations": {"当代": "当代：我们现在生活的时代，作状语，与“坐飞机去外国已经不难了”相合。", "春秋": "语义：春秋时期还没有飞机，与“坐飞机去外国已经不难了”矛盾。", "西周": "语义：西周没有飞机，与“坐飞机去外国”的情景矛盾。", "明天": "搭配：“已经”表示已经实现，不与将来的“明天”搭配。"}, "sentence_index": 6, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些石头已经存在几百万年了，是当代形成的。", "explanation": "这里应该用〈远古〉。当代指现在，几百万年的石头不能说是当代形成的。"}, {"text": "他在班里当代了三年班长。", "explanation": "这里应该用〈担任〉。当代是名词，不能作动词；表示担任职务要说“担任”。"}, {"text": "我们的城市有三个当代。", "explanation": "这里应该用〈时代〉。当代只指现在这一个时代，不能数成“三个当代”；说多个时期要用“时代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们生活当代，很少有人不用手机。", "corrected_sentence": "我们生活在当代，很少有人不用手机。", "error_description": "“生活”后接时代，要加介词“在”，应说“生活在当代”，不说“生活当代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当代地年轻人很重视健康。", "corrected_sentence": "当代的年轻人很重视健康。", "error_description": "“当代”作定语，后面应用“的”，不用“地”；“地”用于修饰动词、形容词。应说“当代的年轻人”，不说“当代地年轻人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
