INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当前这个时代；现今。", "primary_collocate": null, "pronunciation": "dāng dài", "ipa": "taŋ˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他喜欢读当代文学作品。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位画家是当代最有名的画家。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个博物馆里有很多当代艺术品。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代年轻人很喜欢在网上买东西。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代社会发展得非常快。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是一位很有名的当代作家。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲的是当代中国人的生活。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去看一场当代音乐会。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代科学家正在研究怎么保护地球。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画是当代画家画的，不是前人留下的作品。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "当代人", "label": "复合"}, {"form": "当代文学", "label": "复合"}, {"form": "當代", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当代：当前这个时代，多修饰文学、艺术等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e97b369-c5b3-4f14-9e9f-6e44fef3be27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDE