INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：当前这个时代，作定语修饰“文学作品”，与句意相合。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“拖鞋”不能修饰文学作品，“拖鞋文学作品”不成搭配。"}, {"text": "蜡烛", "is_correct": false, "explanation": "搭配：“蜡烛”不能修饰文学作品，“蜡烛文学作品”不成搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，与“喜欢读……文学作品”的阅读对象不相容。"}], "explanations": {"当代": "当代：当前这个时代，作定语修饰“文学作品”，与句意相合。", "拖鞋": "搭配：“拖鞋”不能修饰文学作品，“拖鞋文学作品”不成搭配。", "蜡烛": "搭配：“蜡烛”不能修饰文学作品，“蜡烛文学作品”不成搭配。", "厨房": "语义：厨房是场所，与“喜欢读……文学作品”的阅读对象不相容。"}, "sentence_index": 0, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候，当代的生活还很简单。", "explanation": "这里应该用〈当时〉。当代指现在这个时代，不能指过去的某段时间。"}, {"text": "这本小说写的是古代的当代故事。", "explanation": "这里应该用〈现在〉。当代指现今，不能与“古代”并用来修饰同一个故事，两者时间矛盾。"}, {"text": "这间屋子已经有一百年的历史了，是当代的。", "explanation": "这里应该用〈古老〉。当代指现在，不能用来形容已有一百年历史的老屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：当前这个时代，作定语修饰“中国人的生活”，与句意相合。"}, {"text": "植物", "is_correct": false, "explanation": "语义：“植物中国人”指不了人的生活，与“讲的是……中国人的生活”不相容。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“中国人”前只能用时代、地区类修饰语，不能用“汽车”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命之物，与“中国人的生活”的主体不符。"}], "explanations": {"当代": "当代：当前这个时代，作定语修饰“中国人的生活”，与句意相合。", "植物": "语义：“植物中国人”指不了人的生活，与“讲的是……中国人的生活”不相容。", "汽车": "搭配：“中国人”前只能用时代、地区类修饰语，不能用“汽车”。", "石头": "语义：石头是无生命之物，与“中国人的生活”的主体不符。"}, "sentence_index": 6, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们住在当代，离学校很近。", "explanation": "这里应该用〈地方〉。当代是时间名词，指现在这个时代，不是地点；说住的地方要用“地方”。"}, {"text": "他在学校当代了三年班长。", "explanation": "这里应该用〈担任〉。当代是名词，不能作动词；表示担任职务要说“担任”。"}, {"text": "我的书架上有三个当代，都很有名。", "explanation": "这里应该用〈作品〉。当代是抽象的时代名词，不能直接计数；数作品要说“三部作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐很喜欢当代地小说。", "corrected_sentence": "我姐姐很喜欢当代小说。", "error_description": "“当代”修饰名词时直接接名词，中间不加“地”。“地”用于修饰动词或形容词，此处应说“当代小说”，不说“当代地小说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们过着当代地生活，很多事都很方便。", "corrected_sentence": "我们过着当代的生活，很多事都很方便。", "error_description": "“当代”修饰名词“生活”时要用“的”，不用“地”；“地”用于修饰动词或形容词。应说“当代的生活”，不说“当代地生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
