INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "疗法是帮人治病的办法。", "primary_collocate": null, "pronunciation": "liáo fǎ", "ipa": "liɑʊ̯˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个疗法治病很快。", "target_word": "疗法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种疗法不用药，靠运动治病。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给他换了一种新疗法。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病用中医疗法好得很快。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个疗法需要每天做一次。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理疗法可以帮人放松心情。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这个疗法对老人也有用。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试过很多疗法，但病还没好。", "target_word": "疗法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疗法已经有一百多年的历史了。", "target_word": "疗法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生把两种疗法的好处都讲给他听。", "target_word": "疗法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种疗法", "label": "量词"}, {"form": "心理疗法", "label": "复合"}, {"form": "物理疗法", "label": "复合"}], "register": "中性", "sense_fingerprint": "疗法：治疗疾病的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89311, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疗法", "is_correct": true, "explanation": "正确：“疗法”是治病的方法，可作主语，与“治病很快”相符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是接受治疗的人，本身不能治病。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不作治病手段，“治病”不搭配“手机”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不能治病，与“治病很快”不符。"}], "explanations": {"疗法": "正确：“疗法”是治病的方法，可作主语，与“治病很快”相符。", "病人": "语义：病人是接受治疗的人，本身不能治病。", "手机": "搭配：“手机”不作治病手段，“治病”不搭配“手机”。", "空调": "语义：空调不能治病，与“治病很快”不符。"}, "sentence_index": 0, "correct_answer": "疗法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饭后喝疗法。", "explanation": "这里应该用〈药水〉。喝的是液体，疗法是治疗的办法，不能用“喝”来带它。"}, {"text": "他住进了那个疗法。", "explanation": "这里应该用〈医院〉。住进要带地点，疗法是治疗的办法，不是可以住进的地方。"}, {"text": "他每天滴疗法。", "explanation": "这里应该用〈眼药〉。滴的是液体药物，疗法是治疗的办法，不能用“滴”来带它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疗法", "is_correct": true, "explanation": "正确：“疗法”是治病的方法，与“这个……对老人也有用”相符。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”是疾病本身，不是可以对老人有用的治疗手段。"}, {"text": "毒药", "is_correct": false, "explanation": "语义：毒药有害，与“对老人也有用”矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾没有用处，与“对老人也有用”矛盾。"}], "explanations": {"疗法": "正确：“疗法”是治病的方法，与“这个……对老人也有用”相符。", "病": "语义：“病”是疾病本身，不是可以对老人有用的治疗手段。", "毒药": "语义：毒药有害，与“对老人也有用”矛盾。", "垃圾": "语义：垃圾没有用处，与“对老人也有用”矛盾。"}, "sentence_index": 6, "correct_answer": "疗法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他开了一台疗法。", "explanation": "这里应该用量词〈种〉。〈台〉用于机器，不能用于疗法。"}, {"text": "医生把两块疗法的好处都讲给他听。", "explanation": "这里应该用量词〈种〉。〈块〉用于块状的东西，不能用于疗法。"}, {"text": "他买了两座疗法。", "explanation": "这里应该用量词〈种〉。〈座〉用于大型固定的东西，不能用于疗法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个疗法治地很快。", "corrected_sentence": "这个疗法治得很快。", "error_description": "结构助词错误：“治”后的程度补语要用“得”，不能用“地”。“地”标示状语，“治地很快”不成立，应说“治得很快”。错误在“地”，正确形式为“治得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生给老人选了适合他疗法。", "corrected_sentence": "医生给老人选了适合他的疗法。", "error_description": "结构助词错误：“适合他”修饰“疗法”时要加“的”，应说“适合他的疗法”，不能省略“的”。错误在缺少“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
