INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面以上的空间。", "primary_collocate": null, "pronunciation": "kōng zhōng", "ipa": "kʰʊŋ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他把球扔到了空中。", "target_word": "空中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球停在空中，一动也不动。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跳起来，在空中转了一圈。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员跳到空中，做了一个漂亮的动作。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向空中挥手，像在跟谁说再见。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她松开手，花瓣在空中慢慢落下来。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个气球飘在空中，越飘越高。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手指在空中画了一个圆。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球飞到空中，大家都抬头看。", "target_word": "空中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机在空中飞行了两个小时。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "空中小姐", "label": "复合"}, {"form": "空中花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "空中：离开地面的空间，物体抛起、跳起、悬停的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e97b369-c5b3-4f14-9e9f-6e44fef3be27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“扔到了”要求一个落点处所，“昨天”是时间，球不能扔到时间里。"}, {"text": "空中", "is_correct": true, "explanation": "空中指离开地面的空间，球被扔到的正是这个位置。"}, {"text": "希望", "is_correct": false, "explanation": "搭配：“扔到了”后面要接具体的处所，“希望”是抽象名词，不能这样搭配。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是时间，球不能扔到春天里。"}], "explanations": {"昨天": "语义：“扔到了”要求一个落点处所，“昨天”是时间，球不能扔到时间里。", "空中": "空中指离开地面的空间，球被扔到的正是这个位置。", "希望": "搭配：“扔到了”后面要接具体的处所，“希望”是抽象名词，不能这样搭配。", "春天": "语义：“春天”是时间，球不能扔到春天里。"}, "sentence_index": 0, "correct_answer": "空中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山上的空中很清新，适合深呼吸。", "explanation": "这里应该用〈空气〉。“空中”指地面以上的空间，是处所，不能用来说空气清新，应说空气。"}, {"text": "这个保温瓶的空中很大，能装下一升水。", "explanation": "这里应该用〈中空〉。“空中”指地面以上的空间，瓶子内部是空的，应说中空。"}, {"text": "操场旁边有一大块空中，学生们可以踢球。", "explanation": "这里应该用〈空地〉。“空中”指地面以上的空间，地面上没被占用的地方应说空地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "搭配：“飘在”后面要接处所，“昨天”是时间，气球不能飘在时间里。"}, {"text": "空中", "is_correct": true, "explanation": "空中指地面以上的空间，气球飘在那里，才能越飘越高。"}, {"text": "星期一", "is_correct": false, "explanation": "搭配：“飘在”后面要接处所，“星期一”是时间，不能这样搭配。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“飘在”后面要接处所，“晚饭”不是处所，不能这样搭配。"}], "explanations": {"昨天": "搭配：“飘在”后面要接处所，“昨天”是时间，气球不能飘在时间里。", "空中": "空中指地面以上的空间，气球飘在那里，才能越飘越高。", "星期一": "搭配：“飘在”后面要接处所，“星期一”是时间，不能这样搭配。", "晚饭": "搭配：“飘在”后面要接处所，“晚饭”不是处所，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "空中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木板上有一个空中，小虫子从那里爬了出来。", "explanation": "这里应该用〈空隙〉。“空中”指地面以上的空间，木板上的缝隙要说空隙，不能说木板上有空中。"}, {"text": "这道题的空中要用笔填上答案。", "explanation": "这里应该用〈空白〉。“空中”指地面以上的空间，题目里留出来要填写的地方应说空白，不能说空中。"}, {"text": "这辆公交车的空中很多，你可以找座位坐。", "explanation": "这里应该用〈空位〉。“空中”指地面以上的空间，车上没人坐的座位要说空位，不能用空中来说座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在空中的转了一圈，裙子飘了起来。", "corrected_sentence": "她在空中转了一圈，裙子飘了起来。", "error_description": "多出了“的”。“在空中”是状语，后面直接接动词，不能加“的”，应说“在空中转了一圈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气球飘了到空中。", "corrected_sentence": "气球飘到了空中。", "error_description": "“了”位置错误。“飘到”是动补结构，“了”应放在补语“到”之后，应说“飘到了空中”，不能说“飘了到空中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "杂", "is_correct": true, "explanation": "反义：“杂”指混入别的东西，与“纯”意思相反。"}, {"text": "厚", "is_correct": false, "explanation": "与“纯”无反义关系：“厚”说的是厚度。"}, {"text": "深", "is_correct": false, "explanation": "与“纯”无反义关系：“深”说的是深浅。"}, {"text": "快", "is_correct": false, "explanation": "与“纯”无反义关系：“快”说的是速度。"}], "correct_answer": "杂", "explanations": {"杂": "反义：“杂”指混入别的东西，与“纯”意思相反。", "厚": "与“纯”无反义关系：“厚”说的是厚度。", "深": "与“纯”无反义关系：“深”说的是深浅。", "快": "与“纯”无反义关系：“快”说的是速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
