INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "里面只有这一样，没有别的东西混进去。", "primary_collocate": null, "pronunciation": "chún", "ipa": "ʈʂʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这种蜂蜜很纯，没有加糖。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯果汁是纯的，没加水。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块金子不够纯，里面有别的金属。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶橄榄油很纯，没有掺别的油。", "target_word": "纯", "complexity_tier": "T3", "furigana": "zhè píng gǎnlǎnyóu hěn chún, méiyǒu chān bié de yóu.", "sentence_source": "generated"}, {"text": "这碗水很纯，没有一点脏东西。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶酒很纯，一点水也没掺。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服是纯羊毛的，很暖和。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子里的盐很纯，没有沙子。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玉很纯，没有别的颜色。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的泉水很纯，我们喝了不少。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "纯净", "label": "复合"}, {"form": "纯正", "label": "复合"}, {"form": "純", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物质成分单一，没有掺进别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），里面只有这一样，没有别的东西混进去。"}, {"text": "春", "is_correct": false, "explanation": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。"}, {"text": "存", "is_correct": false, "explanation": "cún 与 chún 声母不同（c 与 ch），意思是保存。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}], "explanations": {"纯": "正确：纯（chún），里面只有这一样，没有别的东西混进去。", "春": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。", "蠢": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。", "存": "cún 与 chún 声母不同（c 与 ch），意思是保存。", "船": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，“很纯”说蜂蜜里没有掺杂，与后句“没有加糖”一致。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说的是形状，不能用来形容蜂蜜。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”不用来形容蜂蜜的状态。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”说的是长短，不能用来形容蜂蜜。"}], "explanations": {"纯": "正确：纯，“很纯”说蜂蜜里没有掺杂，与后句“没有加糖”一致。", "圆": "语义：“圆”说的是形状，不能用来形容蜂蜜。", "快": "搭配：“快”不用来形容蜂蜜的状态。", "长": "语义：“长”说的是长短，不能用来形容蜂蜜。"}, "sentence_index": 0, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱很纯，夏天也不太费电。", "explanation": "这里应该用〈节能〉。纯说的是成分单一、不掺杂，形容省电要用节能。"}, {"text": "这间厨房的台面很纯，每天都擦得亮亮的。", "explanation": "这里应该用〈洁净〉。纯说的是不掺杂质，形容台面干净要用洁净。"}, {"text": "他骑自行车骑得很纯，一点也不费力。", "explanation": "这里应该用〈纯熟〉。纯熟指技艺熟练，形容骑车的熟练程度要用纯熟，“很纯”没有这种用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），里面只有这一样，没有别的东西混进去。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。"}, {"text": "沉", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}], "explanations": {"纯": "正确：纯（chún），里面只有这一样，没有别的东西混进去。", "蝉": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。", "陈": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。", "沉": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，修饰“羊毛”，表示羊毛里不掺别的纤维。"}, {"text": "尖", "is_correct": false, "explanation": "语义：“尖”说的是尖端，不能修饰羊毛的成分。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”不用来修饰羊毛。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味道，不能修饰羊毛。"}], "explanations": {"纯": "正确：纯，修饰“羊毛”，表示羊毛里不掺别的纤维。", "尖": "语义：“尖”说的是尖端，不能修饰羊毛的成分。", "瘦": "搭配：“瘦”不用来修饰羊毛。", "甜": "语义：“甜”是味道，不能修饰羊毛。"}, "sentence_index": 6, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把扇子的做工很纯，纹路也很细。", "explanation": "这里应该用〈精致〉。纯说的是不掺杂质，形容做工的精巧要用精致。"}, {"text": "这张照片很纯，连远处的树都看得见。", "explanation": "这里应该用〈清晰〉。纯说的是不掺杂质，形容照片的清楚程度要用清晰。"}, {"text": "这台仪器的测量很纯，误差很小。", "explanation": "这里应该用〈精准〉。纯说的是不掺杂质，形容测量的准确程度要用精准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶蜂蜜没纯，没有掺别的东西。", "corrected_sentence": "这瓶蜂蜜很纯，没有掺别的东西。", "error_description": "错误：形容词“纯”作谓语时，前面应用程度副词“很”，不能用“没”。“没纯”不成立，正确说法是“很纯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玉石的成分纯很。", "corrected_sentence": "这种玉石的成分很纯。", "error_description": "错误：“很”放在了“纯”的后面，语序错误。正确说法是“很纯”，“很”要放在形容词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
