INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。"}, {"text": "慢", "is_correct": false, "explanation": "与“纯”无反义关系：“慢”说的是速度。"}, {"text": "硬", "is_correct": false, "explanation": "与“纯”无反义关系：“硬”说的是硬度。"}, {"text": "宽", "is_correct": false, "explanation": "与“纯”无反义关系：“宽”说的是宽窄。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。", "慢": "与“纯”无反义关系：“慢”说的是速度。", "硬": "与“纯”无反义关系：“硬”说的是硬度。", "宽": "与“纯”无反义关系：“宽”说的是宽窄。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "单纯；不含杂质的。", "primary_collocate": null, "pronunciation": "chún", "ipa": "ʈʂʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这个孩子的心很纯。", "target_word": "纯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她年纪不大，人很纯。", "target_word": "纯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们俩的友情很纯，没有别的想法。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还很纯，别人说什么他都信。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶的空气很纯，我们深深地吸了一口。", "target_word": "纯", "complexity_tier": "T3", "furigana": "shān dǐng de kōngqì hěn chún, wǒmen shēnshēn de xī le yì kǒu.", "sentence_source": "generated"}, {"text": "这个戒指的银很纯，不含杂质。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌的声音很纯，听着很舒服。", "target_word": "纯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的动机不纯，只想要我们的钱。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶水很纯，不含任何杂质。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从来没骗过人，心思特别纯。", "target_word": "纯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纯真", "label": "复合"}, {"form": "纯粹", "label": "复合"}, {"form": "純", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单纯、不含杂质，也指人心思简单不复杂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），形容心思单纯、不复杂。"}, {"text": "春", "is_correct": false, "explanation": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。"}, {"text": "存", "is_correct": false, "explanation": "cún 与 chún 声母不同（c 与 ch），意思是保存。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}], "explanations": {"纯": "正确：纯（chún），形容心思单纯、不复杂。", "春": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。", "蠢": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。", "存": "cún 与 chún 声母不同（c 与 ch），意思是保存。", "船": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，形容孩子心地单纯，与“很纯”搭配。"}, {"text": "扁", "is_correct": false, "explanation": "语义：“扁”说的是形状，不能用来形容心。"}, {"text": "陡", "is_correct": false, "explanation": "搭配：“陡”用于坡、路等，不能用来形容心。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”说的是形状，不能用来形容心。"}], "explanations": {"纯": "正确：纯，形容孩子心地单纯，与“很纯”搭配。", "扁": "语义：“扁”说的是形状，不能用来形容心。", "陡": "搭配：“陡”用于坡、路等，不能用来形容心。", "方": "语义：“方”说的是形状，不能用来形容心。"}, "sentence_index": 0, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很纯，每门课都是满分。", "explanation": "这里应该用〈优秀〉。纯说的是单纯或不掺杂，形容成绩好要用优秀。"}, {"text": "他做事很纯，从不拖拉。", "explanation": "这里应该用〈利落〉。纯说的是单纯或不掺杂，形容做事干脆利索要用利落。"}, {"text": "这次旅行很纯，大家都很开心。", "explanation": "这里应该用〈轻松〉。纯说的是单纯或不掺杂，形容旅行的愉快、轻松要用轻松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），形容心思单纯、不复杂。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。"}, {"text": "沉", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}], "explanations": {"纯": "正确：纯（chún），形容心思单纯、不复杂。", "蝉": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。", "陈": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。", "沉": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，形容声音清亮，与“听着很舒服”一致。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味道，不能用来形容声音。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说的是高度，不能用来形容声音。"}, {"text": "枯", "is_correct": false, "explanation": "语义：“枯”说的是干涸、没有生气，与声音不搭。"}], "explanations": {"纯": "正确：纯，形容声音清亮，与“听着很舒服”一致。", "咸": "语义：“咸”是味道，不能用来形容声音。", "矮": "搭配：“矮”说的是高度，不能用来形容声音。", "枯": "语义：“枯”说的是干涸、没有生气，与声音不搭。"}, "sentence_index": 6, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的服务很纯，客人都很满意。", "explanation": "这里应该用〈周到〉。纯说的是单纯或不掺杂，形容服务细致要用周到。"}, {"text": "这场比赛很纯，观众一直在欢呼。", "explanation": "这里应该用〈精彩〉。纯说的是单纯或不掺杂，形容比赛的精彩程度要用精彩。"}, {"text": "这排书摆得很纯，一本也不乱。", "explanation": "这里应该用〈整齐〉。纯说的是单纯或不掺杂，形容摆放得有条理要用整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小男孩的心纯很，从不撒谎。", "corrected_sentence": "这个小男孩的心很纯，从不撒谎。", "error_description": "错误：程度副词“很”应放在形容词前。应说“心很纯”，不能说“心纯很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人的动机很没纯，只想骗我们。", "corrected_sentence": "这个人的动机很不纯，只想骗我们。", "error_description": "错误：形容词的否定要用“不”，不能用“没”。“没纯”不成立，正确说法是“很不纯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
