INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "相看是互相看一看，或者仔细看一看。", "primary_collocate": null, "pronunciation": "xiāng kàn", "ipa": "ɕiaŋ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他们在雨中相看，谁也没有先开口。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在门口相看了一下，一起走进了教室。", "target_word": "相看", "complexity_tier": "T3", "furigana": "xiāng kàn", "sentence_source": "generated"}, {"text": "老人和孙子相看着，都很高兴。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位老师相看着，点了点头。", "target_word": "相看", "complexity_tier": "T3", "furigana": "xiāng kàn", "sentence_source": "generated"}, {"text": "离别那天，我们相看了很久。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲和女儿相看无语，眼里都有泪。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们隔着桌子相看，不知道说什么。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩多年没见，一见面就相看着大笑起来。", "target_word": "相看", "complexity_tier": "T3", "furigana": "xiāng kàn", "sentence_source": "generated"}, {"text": "她和他在走廊上相看了一下，又低下头去。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子相看着，忽然都笑了出来。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相看了", "label": "体标"}, {"form": "相看着", "label": "体标"}, {"form": "相看过", "label": "体标"}], "register": "书面", "sense_fingerprint": "彼此互相看一看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确答案：相看（xiāng kàn），意思是互相看一看或仔细看一看。"}, {"text": "想看", "is_correct": false, "explanation": "想看（xiǎng kàn）与相看（xiāng kàn）声调不同：xiǎng 是第三声，xiāng 是第一声。意思是想要观看。"}, {"text": "先看", "is_correct": false, "explanation": "先看（xiān kàn）与相看（xiāng kàn）韵尾不同：xiān 以 -n 收尾，xiāng 以 -ng 收尾。意思是先行观看。"}, {"text": "相抗", "is_correct": false, "explanation": "相抗（xiāng kàng）与相看（xiāng kàn）韵尾不同：kàng 以 -ng 收尾，kàn 以 -n 收尾。意思是互相抵抗。"}], "explanations": {"相看": "正确答案：相看（xiāng kàn），意思是互相看一看或仔细看一看。", "想看": "想看（xiǎng kàn）与相看（xiāng kàn）声调不同：xiǎng 是第三声，xiāng 是第一声。意思是想要观看。", "先看": "先看（xiān kàn）与相看（xiāng kàn）韵尾不同：xiān 以 -n 收尾，xiāng 以 -ng 收尾。意思是先行观看。", "相抗": "相抗（xiāng kàng）与相看（xiāng kàn）韵尾不同：kàng 以 -ng 收尾，kàn 以 -n 收尾。意思是互相抵抗。"}, "sentence_index": null, "correct_answer": "相看"}, "level_3": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确。“在雨中”的场景下，双方无声对看，符合“谁也没有先开口”。"}, {"text": "聊天", "is_correct": false, "explanation": "语义：聊天要开口说话，与“谁也没有先开口”直接矛盾。"}, {"text": "交谈", "is_correct": false, "explanation": "语义：交谈需要双方说话，与句末表示沉默的描写相矛盾。"}, {"text": "唠嗑", "is_correct": false, "explanation": "语域：唠嗑是口语词，不合书面的叙述语体，且同样与“谁也没有先开口”矛盾。"}], "explanations": {"相看": "正确。“在雨中”的场景下，双方无声对看，符合“谁也没有先开口”。", "聊天": "语义：聊天要开口说话，与“谁也没有先开口”直接矛盾。", "交谈": "语义：交谈需要双方说话，与句末表示沉默的描写相矛盾。", "唠嗑": "语域：唠嗑是口语词，不合书面的叙述语体，且同样与“谁也没有先开口”矛盾。"}, "sentence_index": 0, "correct_answer": "相看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向窗外相看了一眼，然后关上了窗。", "explanation": "这里应该用〈瞥〉。相看表示互看一看或仔细看一看，需要注视一段时间；此处只是匆匆看一眼，应用瞥。"}, {"text": "他相看了一下那首歌，觉得很好听。", "explanation": "这里应该用〈听〉。相看指用眼睛看，听歌要用“听”，不能用相看。"}, {"text": "他走进会场，相看了一圈四周。", "explanation": "这里应该用〈环顾〉。相看表示仔细看一看某物，把四周快速看一圈是环顾，不能用相看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确。“隔着桌子”与“不知道说什么”描写的是隔着距离彼此对看、无话可说的情形。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：隔着桌子无法拥抱，与“隔着桌子”的距离相矛盾。"}, {"text": "亲吻", "is_correct": false, "explanation": "语义：隔着桌子无法亲吻，与“隔着桌子”的距离相矛盾。"}, {"text": "倾诉", "is_correct": false, "explanation": "语义：倾诉是诉说心事，与“不知道说什么”直接矛盾。"}], "explanations": {"相看": "正确。“隔着桌子”与“不知道说什么”描写的是隔着距离彼此对看、无话可说的情形。", "拥抱": "语义：隔着桌子无法拥抱，与“隔着桌子”的距离相矛盾。", "亲吻": "语义：隔着桌子无法亲吻，与“隔着桌子”的距离相矛盾。", "倾诉": "语义：倾诉是诉说心事，与“不知道说什么”直接矛盾。"}, "sentence_index": 6, "correct_answer": "相看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他朝目标相看了一眼，然后走开。", "explanation": "这里应该用〈瞄〉。相看表示互看一看或仔细看一看，不表示对准目标的一瞬间打量；此处应用瞄。"}, {"text": "她在车站相看，等待朋友到来。", "explanation": "这里应该用〈张望〉。相看指互看一看或仔细看某物，等人时四处查看应用张望，相看不表示四处寻找。"}, {"text": "他用目光相看了整个教室。", "explanation": "这里应该用〈扫视〉。扫视是从头到尾快速看一遍，相看强调仔细看一看某物，不能用于整个教室的快速环视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位老师很相看许久，点了点头。", "corrected_sentence": "两位老师相看许久，点了点头。", "error_description": "错误：“很”是程度副词，不能修饰动词“相看”。正确形式是删去“很”，说“两位老师相看许久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个孩子正在相看了，忽然都笑了出来。", "corrected_sentence": "两个孩子正在相看，忽然都笑了出来。", "error_description": "错误：“正在”表示动作进行中，句末的“了”表示动作完成，二者不能同时用于“相看”。正确形式是删去“了”，说“两个孩子正在相看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
