INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互相对看；也指仔细察看，以判断是否合意。", "primary_collocate": null, "pronunciation": "xiāng kàn", "ipa": "ɕiaŋ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "两个人隔着人群相看，什么也没说。", "target_word": "相看", "complexity_tier": "T3", "furigana": "xiāng kàn", "sentence_source": "generated"}, {"text": "他们相看了一会儿，都没有说话。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年不见，母女俩相看着流下了眼泪。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在操场边相看，都忍不住笑了。", "target_word": "相看", "complexity_tier": "T3", "furigana": "xiāng kàn", "sentence_source": "generated"}, {"text": "老朋友在车站相看，一时说不出话。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们站在门口，默默相看。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只小猫在窗边相看了很久。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们相看无言，心里都很难过。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时他们偷偷相看，然后笑了。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "争吵之后，两个人谁也不说话，只是相看。", "target_word": "相看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相看了", "label": "体标"}, {"form": "相看着", "label": "体标"}, {"form": "相看过", "label": "体标"}], "register": "书面", "sense_fingerprint": "双方互相对着看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89324, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确答案：相看（xiāng kàn），意思是双方互相对看。"}, {"text": "想看", "is_correct": false, "explanation": "想看（xiǎng kàn）与相看（xiāng kàn）声调不同：xiǎng 是第三声，xiāng 是第一声。意思是想要观看。"}, {"text": "先看", "is_correct": false, "explanation": "先看（xiān kàn）与相看（xiāng kàn）韵尾不同：xiān 以 -n 收尾，xiāng 以 -ng 收尾。意思是先行观看。"}, {"text": "相抗", "is_correct": false, "explanation": "相抗（xiāng kàng）与相看（xiāng kàn）韵尾不同：kàng 以 -ng 收尾，kàn 以 -n 收尾。意思是互相抵抗。"}], "explanations": {"相看": "正确答案：相看（xiāng kàn），意思是双方互相对看。", "想看": "想看（xiǎng kàn）与相看（xiāng kàn）声调不同：xiǎng 是第三声，xiāng 是第一声。意思是想要观看。", "先看": "先看（xiān kàn）与相看（xiāng kàn）韵尾不同：xiān 以 -n 收尾，xiāng 以 -ng 收尾。意思是先行观看。", "相抗": "相抗（xiāng kàng）与相看（xiāng kàn）韵尾不同：kàng 以 -ng 收尾，kàn 以 -n 收尾。意思是互相抵抗。"}, "sentence_index": null, "correct_answer": "相看"}, "level_3": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确。“隔着人群”说明距离远，“什么也没说”与隔空对看、无声相望相合。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：隔着人群无法拥抱，与“隔着人群”的距离相矛盾。"}, {"text": "握手", "is_correct": false, "explanation": "搭配：握手需要双方走近、伸手相握，与“隔着人群”不搭配。"}, {"text": "说话", "is_correct": false, "explanation": "语义：说话要开口，与句末“什么也没说”直接矛盾。"}], "explanations": {"相看": "正确。“隔着人群”说明距离远，“什么也没说”与隔空对看、无声相望相合。", "拥抱": "语义：隔着人群无法拥抱，与“隔着人群”的距离相矛盾。", "握手": "搭配：握手需要双方走近、伸手相握，与“隔着人群”不搭配。", "说话": "语义：说话要开口，与句末“什么也没说”直接矛盾。"}, "sentence_index": 0, "correct_answer": "相看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众安静地相看舞台上的表演。", "explanation": "这里应该用〈观看〉。相看指双方彼此对看，观众看舞台是单方面的，不能用相看。"}, {"text": "她在病床前相看着熟睡的孩子。", "explanation": "这里应该用〈注视〉。相看要求双方互相看，此处只是一人看熟睡的孩子，应用注视。"}, {"text": "他一直相看着手机屏幕，没有抬头。", "explanation": "这里应该用〈盯〉。相看指双方互看，他对着屏幕单向地看，应用盯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相看", "is_correct": true, "explanation": "正确。“隔着桌子”与“不知道说什么”描写的是隔着距离彼此对看、无话可说的情形。"}, {"text": "写作", "is_correct": false, "explanation": "语义：小猫不会写作，在窗边写作的情境不成立。"}, {"text": "修理", "is_correct": false, "explanation": "语义：小猫不会修理东西，与窗边相看的情境不合。"}, {"text": "投票", "is_correct": false, "explanation": "语义：小猫没有投票的能力，与句子描写的情境不合。"}], "explanations": {"相看": "正确。“隔着桌子”与“不知道说什么”描写的是隔着距离彼此对看、无话可说的情形。", "写作": "语义：小猫不会写作，在窗边写作的情境不成立。", "修理": "语义：小猫不会修理东西，与窗边相看的情境不合。", "投票": "语义：小猫没有投票的能力，与句子描写的情境不合。"}, "sentence_index": 6, "correct_answer": "相看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在窗前，相看着远处的山。", "explanation": "这里应该用〈凝视〉。相看是双方互看，一人对着远山专注地看，应用凝视。"}, {"text": "他在车站相看，等待朋友到来。", "explanation": "这里应该用〈张望〉。等人时四处查看要用张望，相看指双方互看。"}, {"text": "他狠狠地相看了我一眼。", "explanation": "这里应该用〈瞪〉。相看不含怒视之义，且要求双方互看，“狠狠地”的单向怒视应用瞪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人正在相看了，谁也没有说话。", "corrected_sentence": "两个人正在相看，谁也没有说话。", "error_description": "错误：“正在”表示动作正在进行，句末的“了”表示动作完成，二者不能同时用于“相看”。正确形式是去掉“了”，说“两个人正在相看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们互相相看了许久，都没有开口。", "corrected_sentence": "他们相看了许久，都没有开口。", "error_description": "错误：“相”本身已经含有“互相”的意思，前面再加“互相”属于重复。正确形式是删去“互相”，说“他们相看了许久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
