INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把话讲得太满，不留一点余地。", "primary_collocate": null, "pronunciation": "shuō sǐ", "ipa": "ʂuɔ˥ sɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "事情还没做完，别把话说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把话说死了，现在很难改口。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要说死，以后可能会变。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有说死，只说可能会考。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意不能把话说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕以后有变化，所以没说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事还不一定，别说死了。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说死了不会去，后来又去了。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的事，我不想说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不把话说死，总留一点余地。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说死了", "label": "体标"}, {"form": "没说死", "label": "否定"}, {"form": "說死", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对还没定的事把话讲满，以后难以改口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89359, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说死", "is_correct": true, "explanation": "正确。说死：把话讲得太满，不留余地。"}, {"text": "水死", "is_correct": false, "explanation": "shuǐ（第三声）与 shuō（第一声）韵母和声调都不同，意思是淹死。"}, {"text": "睡死", "is_correct": false, "explanation": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡得很沉。"}, {"text": "戳死", "is_correct": false, "explanation": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺死。"}, {"text": "说是", "is_correct": false, "explanation": "第二音节 shì（第四声）与 sǐ（第三声）声母不同（sh 与 s）且声调不同，意思是据说或表示确认。"}], "explanations": {"说死": "正确。说死：把话讲得太满，不留余地。", "水死": "shuǐ（第三声）与 shuō（第一声）韵母和声调都不同，意思是淹死。", "睡死": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡得很沉。", "戳死": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺死。", "说是": "第二音节 shì（第四声）与 sǐ（第三声）声母不同（sh 与 s）且声调不同，意思是据说或表示确认。"}, "sentence_index": null, "correct_answer": "说死"}, "level_3": {"options": [{"text": "说死", "is_correct": true, "explanation": "说死：把话讲得太满，不留余地，符合“别把话……”的劝阻语境。"}, {"text": "说累", "is_correct": false, "explanation": "搭配：“说累”的主语是说话的人，不能说“把话说累”。"}, {"text": "说教", "is_correct": false, "explanation": "配价：“说教”是不及物动词，不能带“把话”作宾语。"}, {"text": "说活", "is_correct": false, "explanation": "语义：“说活”指把话说得有余地，与句中要表达的“不留余地”相反，句意不通。"}], "explanations": {"说死": "说死：把话讲得太满，不留余地，符合“别把话……”的劝阻语境。", "说累": "搭配：“说累”的主语是说话的人，不能说“把话说累”。", "说教": "配价：“说教”是不及物动词，不能带“把话”作宾语。", "说活": "语义：“说活”指把话说得有余地，与句中要表达的“不留余地”相反，句意不通。"}, "sentence_index": 0, "correct_answer": "说死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师说死了那本书。", "explanation": "这里应该用〈借〉。说死指把话讲得绝对、不留余地，不能用于借书这类事情。"}, {"text": "他在报纸上说死了这篇文章。", "explanation": "这里应该用〈发表〉。说死指把话讲得绝对，不能用于公开刊登文章。"}, {"text": "他说死了老师的问题。", "explanation": "这里应该用〈回答〉。说死是对结果或判断下绝对断言，不能表示对问题作答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说死", "is_correct": true, "explanation": "说死：把话讲得太满，此处指不要把还没定的事说绝，符合句意。"}, {"text": "说快", "is_correct": false, "explanation": "语义：“说快”指说话速度快，与“这件事还不一定”的语境无关，句意不通。"}, {"text": "说假", "is_correct": false, "explanation": "搭配：“说假”不是常用搭配，句中要表达的是不宜过早下断言，不能用“说假”。"}, {"text": "说慢", "is_correct": false, "explanation": "语义：“说慢”指说话速度慢，与句中劝阻下断言的语境无关，句意不通。"}], "explanations": {"说死": "说死：把话讲得太满，此处指不要把还没定的事说绝，符合句意。", "说快": "语义：“说快”指说话速度快，与“这件事还不一定”的语境无关，句意不通。", "说假": "搭配：“说假”不是常用搭配，句中要表达的是不宜过早下断言，不能用“说假”。", "说慢": "语义：“说慢”指说话速度慢，与句中劝阻下断言的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "说死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈说死了一首歌。", "explanation": "这里应该用〈唱〉。说死指把话讲绝对，不能表示演唱歌曲。"}, {"text": "他在书里说死了这个人的经历。", "explanation": "这里应该用〈讲述〉。说死是对结果或判断下绝对断言，不能用于叙述经历。"}, {"text": "老师说死了我的名字。", "explanation": "这里应该用〈称呼〉。说死指把话讲绝对，不能表示叫人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别把话说死掉，留点余地。", "corrected_sentence": "你别把话说死，留点余地。", "error_description": "补语错误：“说死”已是动补结构，“死”后不能再加“掉”，应说“你别把话说死”，不能说“说死掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把话说死地了，大家都很不满意。", "corrected_sentence": "他把话说死了，大家都很不满意。", "error_description": "助词错误：“说死”后不能加“地”，动补结构后应接“了”，应说“他把话说死了”，不能说“说死地了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
