INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89368, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说；用于引出或接续所说的话。", "primary_collocate": null, "pronunciation": "shuō dào", "ipa": "ʂwo⁵⁵ tɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "他想了想，说道：“我同意。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢说道：“年轻人，要多读书。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说道：“欢迎你来我家。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看着大家，说道：“今天的会很重要。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我说道：“路上要小心。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李站起来说道：“我来帮你。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师停了一下，接着说道：“现在开始考试。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他叹了口气，说道：“我真的没办法。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长走上台，说道：“同学们，早上好。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶看着窗外，说道：“又下雪了。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "说；置于引语之前，如他说道：“……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说道", "is_correct": true, "explanation": "正确：“说道”用于引语之前，引出要说的话，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，不能用来引出“我同意”这样的话。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要食物作宾语，不能用来引出一句话。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“想了想”之后要说话的情境不符。"}], "explanations": {"说道": "正确：“说道”用于引语之前，引出要说的话，与句意相符。", "唱": "语义：“唱”指唱歌，不能用来引出“我同意”这样的话。", "吃": "配价：“吃”需要食物作宾语，不能用来引出一句话。", "睡": "语义：“睡”与“想了想”之后要说话的情境不符。"}, "sentence_index": 0, "correct_answer": "说道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理看着大家，说道一杯水。", "explanation": "这里应该用〈喝〉。“说道”只能引出说的话，“一杯水”要用“喝”。"}, {"text": "经理在纸上说道：“请大家准时到场。”", "explanation": "这里应该用〈写道〉。“说道”指说出的话，写在纸上要用“写道”。"}, {"text": "校长站起来，说道一扇门。", "explanation": "这里应该用〈开〉。“说道”只能引出说的话，“一扇门”要用“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说道", "is_correct": true, "explanation": "正确：“说道”用于引语之前，引出“现在开始考试”，与句意相符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是跑步动作，不能用来引出“现在开始考试”这样的话。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”是看的动作，不能用来引出一句话。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能接引语。"}], "explanations": {"说道": "正确：“说道”用于引语之前，引出“现在开始考试”，与句意相符。", "跑": "语义：“跑”是跑步动作，不能用来引出“现在开始考试”这样的话。", "看": "语义：“看”是看的动作，不能用来引出一句话。", "哭": "配价：“哭”是不及物动词，后面不能接引语。"}, "sentence_index": 6, "correct_answer": "说道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在河边，说道一条小船。", "explanation": "这里应该用〈划〉。“说道”只能引出说的话，“一条小船”要用“划”。"}, {"text": "奶奶看着窗外，说道一件衣服。", "explanation": "这里应该用〈拿〉。“说道”只能引出话语，“一件衣服”是实物，要用“拿”。"}, {"text": "奶奶看着窗外，说道一朵花。", "explanation": "这里应该用〈摘〉。“说道”只能引出话语，“一朵花”要用“摘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她想了一会儿，说道着：“我们明天见。”", "corrected_sentence": "她想了一会儿，说道：“我们明天见。”", "error_description": "错误：“说道着”应为“说道”。“说道”是引出说话的书面词，后面不接“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈想了想，接着说道过：“我们先吃饭吧。”", "corrected_sentence": "妈妈想了想，接着说道：“我们先吃饭吧。”", "error_description": "错误：“说道过”应为“说道”。“说道”是书面引出语，后面不接“过”，应删去“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
