INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人帮了你，你说好听的话让他知道你很高兴。", "primary_collocate": null, "pronunciation": "xiè", "ipa": "ɕjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "谢了，兄弟，你帮了大忙。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她接过花，笑着谢了我一声。", "target_word": "谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子拿到糖，马上谢了奶奶。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走的时候，一直谢个不停。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人上车后，向司机谢了又谢。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给他让座，他连声谢我。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别谢我，我只是顺手帮个忙。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮了我，我当面谢一下才好。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人吃完饭，站起来谢了老板。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明接过笔，小声说谢，然后走了。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "谢谢", "label": "重叠"}, {"form": "谢了", "label": "体标"}, {"form": "道谢", "label": "复合"}, {"form": "謝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "谢：受到帮助后当面用话语道谢，如“谢了”“连声谢我”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谢", "is_correct": true, "explanation": "正确。谢：受到帮助后当面用话语道谢。"}, {"text": "歇", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是休息。"}, {"text": "鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是鞋子。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xiè（第四声）声调不同，意思是书写。"}, {"text": "借", "is_correct": false, "explanation": "jiè 与 xiè 声母不同（j 与 x），意思是借用。"}, {"text": "血", "is_correct": false, "explanation": "xuè 与 xiè 的介音不同（u 与 i），意思是血液。"}], "explanations": {"谢": "正确。谢：受到帮助后当面用话语道谢。", "歇": "xiē（第一声）与 xiè（第四声）声调不同，意思是休息。", "鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是鞋子。", "写": "xiě（第三声）与 xiè（第四声）声调不同，意思是书写。", "借": "jiè 与 xiè 声母不同（j 与 x），意思是借用。", "血": "xuè 与 xiè 的介音不同（u 与 i），意思是血液。"}, "sentence_index": null, "correct_answer": "谢"}, "level_3": {"options": [{"text": "谢", "is_correct": true, "explanation": "谢：受到帮助后当面用话语道谢，符合句意。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打了”与“你帮了大忙”的感谢语境矛盾，句意不通。"}, {"text": "怨", "is_correct": false, "explanation": "语义：“怨了”表示埋怨，与“你帮了大忙”的语境矛盾。"}, {"text": "瞪", "is_correct": false, "explanation": "体貌：“瞪了”是瞪眼的神态动作，与道谢的语境不合。"}], "explanations": {"谢": "谢：受到帮助后当面用话语道谢，符合句意。", "打": "语义：“打了”与“你帮了大忙”的感谢语境矛盾，句意不通。", "怨": "语义：“怨了”表示埋怨，与“你帮了大忙”的语境矛盾。", "瞪": "体貌：“瞪了”是瞪眼的神态动作，与道谢的语境不合。"}, "sentence_index": 0, "correct_answer": "谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一起谢了一场电影。", "explanation": "这里应该用〈看〉。谢是道谢，不能用于观看电影。"}, {"text": "他一直在谢歌，很有精神。", "explanation": "这里应该用〈唱歌〉。谢是向人道谢，不能用于唱歌。"}, {"text": "他一直在谢觉。", "explanation": "这里应该用〈睡觉〉。谢是道谢，不能用于睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EX