INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "谢", "is_correct": true, "explanation": "正确。谢：受到帮助后当面用话语道谢。"}, {"text": "斜", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是倾斜。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是一些。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 xiè 声母不同（j 与 x），意思是界限。"}, {"text": "协", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是配合。"}], "explanations": {"谢": "正确。谢：受到帮助后当面用话语道谢。", "斜": "xié（第二声）与 xiè（第四声）声调不同，意思是倾斜。", "些": "xiē（第一声）与 xiè（第四声）声调不同，意思是一些。", "界": "jiè 与 xiè 声母不同（j 与 x），意思是界限。", "协": "xié（第二声）与 xiè（第四声）声调不同，意思是配合。"}, "sentence_index": null, "correct_answer": "谢"}, "level_3": {"options": [{"text": "谢", "is_correct": true, "explanation": "谢：对帮助过自己的人表示感激，此处指对方不必道谢，符合句意。"}, {"text": "骗", "is_correct": false, "explanation": "语义：“骗我”与“我只是顺手帮个忙”的语境不合，句意不通。"}, {"text": "碰", "is_correct": false, "explanation": "搭配：“碰我”与“我只是顺手帮个忙”的语境不搭配，句意不通。"}, {"text": "吓", "is_correct": false, "explanation": "语义：“吓我”与“我只是顺手帮个忙”的语境相反，句意不通。"}], "explanations": {"谢": "谢：对帮助过自己的人表示感激，此处指对方不必道谢，符合句意。", "骗": "语义：“骗我”与“我只是顺手帮个忙”的语境不合，句意不通。", "碰": "搭配：“碰我”与“我只是顺手帮个忙”的语境不搭配，句意不通。", "吓": "语义：“吓我”与“我只是顺手帮个忙”的语境相反，句意不通。"}, "sentence_index": 6, "correct_answer": "谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真地谢了那辆自行车。", "explanation": "这里应该用〈修理〉。谢是对人表示感激，不能以物品作宾语。"}, {"text": "他很快谢完了房间。", "explanation": "这里应该用〈打扫〉。谢是道谢，不能用于清理房间。"}, {"text": "他一笔一划地谢着作业。", "explanation": "这里应该用〈写〉。谢是道谢，不能用于书写作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她笑着谢他一声过。", "corrected_sentence": "她笑着谢他一声。", "error_description": "“过”不能放在动量补语“一声”之后；若要表示完成，应说“谢过他一声”。本题的错误形式“谢他一声过”，正确形式为“谢他一声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我当面谢他一声过。", "corrected_sentence": "我当面谢他一声。", "error_description": "“过”不能放在动量补语“一声”之后；去掉“过”即为“我当面谢他一声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
