INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "然后，表示承接前面的动作或情况。", "primary_collocate": null, "pronunciation": "ér hòu", "ipa": "ɚ˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "先把窗户关好，而后再睡觉。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝完茶，而后站起来走了。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先写名字，而后写日期。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先笑了笑，而后点了点头。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先坐地铁，而后换公共汽车。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲课文，而后让学生回答问题。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先到银行取钱，而后去超市买菜。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把菜洗干净，而后再切。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先吃了饭，而后写作业。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家先热身，而后开始跑步。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "承接前面的动作，表示然后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“先把窗户关好”之后再睡觉，“而后”表示这种承接关系。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同时进行，与“先关好窗户”的先后顺序相矛盾。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”表示共同进行，与“先”所示的先后次序不合。"}, {"text": "早已", "is_correct": false, "explanation": "搭配：“早已”表示先前已完成，与“先……再……”的承接结构叠用，语义重复且不通顺。"}], "explanations": {"而后": "正确。“先把窗户关好”之后再睡觉，“而后”表示这种承接关系。", "同时": "语义：“同时”表示同时进行，与“先关好窗户”的先后顺序相矛盾。", "一齐": "语义：“一齐”表示共同进行，与“先”所示的先后次序不合。", "早已": "搭配：“早已”表示先前已完成，与“先……再……”的承接结构叠用，语义重复且不通顺。"}, "sentence_index": 0, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他虽然很累，而后还是坚持把工作做完了。", "explanation": "这里应该用〈但是〉。而后只表示承接，不表示转折，“虽然……还是……”的让步结构中不能用而后。"}, {"text": "他不但会唱歌，而后也会跳舞。", "explanation": "这里应该用〈而且〉。“不但……”需要和“而且”搭配表示递进，而后只表示先后，不能用于此。"}, {"text": "这件事明明很简单，而后没有人做好。", "explanation": "这里应该用〈却〉。“明明”表示与结果相反，应用〈却〉表示转折；而后只表示承接，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“他先到银行取钱”之后去超市买菜，“而后”表示这种先后承接。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同行动，与“先到银行取钱”的先后顺序不合。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：“反复”修饰多次重复的动作，与“取钱”这一次性行动不搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突发，与“先取钱，再去买菜”的有序安排不合。"}], "explanations": {"而后": "正确。“他先到银行取钱”之后去超市买菜，“而后”表示这种先后承接。", "一起": "语义：“一起”表示共同行动，与“先到银行取钱”的先后顺序不合。", "反复": "搭配：“反复”修饰多次重复的动作，与“取钱”这一次性行动不搭配。", "忽然": "语义：“忽然”表示突发，与“先取钱，再去买菜”的有序安排不合。"}, "sentence_index": 6, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论天气如何，而后我们都会出发。", "explanation": "这里应该用〈始终〉。“无论……都……”表示条件无关、一贯如此，而后只表示先后承接，不能用于此。"}, {"text": "这不是他的错，而后是我的错。", "explanation": "这里应该用〈而是〉。表示对立的判断要用而是，而后表示先后，不能用于此。"}, {"text": "而后，我们的第一步是复习课文。", "explanation": "这里应该用〈首先〉。“第一步”表示开始，而后表示承接前面的动作，二者矛盾，应用首先。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先把门锁好，再而后出门。", "corrected_sentence": "先把门锁好，而后出门。", "error_description": "错误：“再”与“而后”都表示先后承接，不能叠用。去掉“再”，正确形式为“先把门锁好，而后出门。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她先去超市买菜，然后而后回家做饭。", "corrected_sentence": "她先去超市买菜，而后回家做饭。", "error_description": "错误：“然后”与“而后”同义，不能叠用。正确形式是只用“而后”，说“她先去超市买菜，而后回家做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
