INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商店里卖的东西。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xuɔ˥˩", "syllable_count": 1, "sentences": [{"text": "这家商店的货很全。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的货都摆好了。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的货真多，我都看花眼了。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的货比别的店便宜。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在店里挑了很多货。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛奶还有货吗？", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里没货了，你明天再来吧。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，店里的货特别好卖。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的货不多，但是都很新。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上把货摆在店里。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货", "label": "量词"}, {"form": "貨", "label": "繁体"}], "register": "口语", "sense_fingerprint": "顾客在商店里能买到的东西，常说有货、没货", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89387, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：货 huò，指商店里卖的东西。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò 声调不同，意思是活着、灵活。"}, {"text": "过", "is_correct": false, "explanation": "guò 与 huò 声母不同（g 与 h），意思是经过、过去。"}, {"text": "扩", "is_correct": false, "explanation": "kuò 与 huò 声母不同（k 与 h），意思是扩大。"}], "explanations": {"货": "正确答案：货 huò，指商店里卖的东西。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。", "活": "huó（第二声）与 huò 声调不同，意思是活着、灵活。", "过": "guò 与 huò 声母不同（g 与 h），意思是经过、过去。", "扩": "kuò 与 huò 声母不同（k 与 h），意思是扩大。"}, "sentence_index": null, "correct_answer": "货"}, "level_3": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：“这家商店的货”指店里卖的东西，“很全”形容货品齐全。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不是商店陈列的东西，商店里不会“很全”学生。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是商店卖的东西，“很全”也不能形容天气。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“很全”不搭配“味道”，说“味道很全”不通。"}], "explanations": {"货": "正确答案：“这家商店的货”指店里卖的东西，“很全”形容货品齐全。", "学生": "语义：学生不是商店陈列的东西，商店里不会“很全”学生。", "天气": "语义：天气不是商店卖的东西，“很全”也不能形容天气。", "味道": "搭配：“很全”不搭配“味道”，说“味道很全”不通。"}, "sentence_index": 0, "correct_answer": "货"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我送给朋友一份货。", "explanation": "这里应该用〈礼物〉。货指店里卖的东西，送给朋友的物品要说礼物。"}, {"text": "这场晚会的货很精彩。", "explanation": "这里应该用〈节目〉。货指供出售的商品，晚会上的表演要说节目。"}, {"text": "他考了第一名，老师奖给他一件货。", "explanation": "这里应该用〈奖品〉。货指店里卖的东西，颁给学生的奖励要说奖品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89387, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：货 huò，指商店里卖的东西。"}, {"text": "错", "is_correct": false, "explanation": "cuò 与 huò 声母不同（c 与 h），声调相同，意思是错误。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 huò 韵母不同（u 与 uo），意思是住户、门户。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 huò 韵母不同（ui 与 uo），意思是会议、会不会。"}, {"text": "画", "is_correct": false, "explanation": "huà 与 huò 韵母不同（ua 与 uo），意思是图画、画画。"}], "explanations": {"货": "正确答案：货 huò，指商店里卖的东西。", "错": "cuò 与 huò 声母不同（c 与 h），声调相同，意思是错误。", "户": "hù 与 huò 韵母不同（u 与 uo），意思是住户、门户。", "会": "huì 与 huò 韵母不同（ui 与 uo），意思是会议、会不会。", "画": "huà 与 huò 韵母不同（ua 与 uo），意思是图画、画画。"}, "sentence_index": null, "correct_answer": "货"}, "level_3": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：“店里没货了”指店里的商品卖光了，与店铺语境吻合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能放在店里，也不是店里卖的东西。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮与店铺无关，“店里没月亮了”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体态，店里不会“没身材”。"}], "explanations": {"货": "正确答案：“店里没货了”指店里的商品卖光了，与店铺语境吻合。", "天空": "语义：天空不能放在店里，也不是店里卖的东西。", "月亮": "语义：月亮与店铺无关，“店里没月亮了”说不通。", "身材": "体貌：身材是人的体态，店里不会“没身材”。"}, "sentence_index": 6, "correct_answer": "货"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上搬来一座货。", "explanation": "量词用错：“座”用于山、房屋等大型固定物，货不用“座”计量，应说“一批货”或“一车货”。"}, {"text": "店门口摆着一朵货。", "explanation": "量词用错：“朵”用于花、云等，货不用“朵”计量，应说“一批货”。"}, {"text": "他每天早上拖来一条货。", "explanation": "量词用错：“条”用于细长的东西，货不用“条”计量，应说“一车货”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店里那些卖不掉货要尽快处理。", "corrected_sentence": "店里那些卖不掉的货要尽快处理。", "error_description": "漏字：“卖不掉”修饰“货”时要加“的”，应说“卖不掉的货”，漏掉“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月进了一只货。", "corrected_sentence": "这个月进了一批货。", "error_description": "量词错误：货按批或车计量，“只”用于动物或单个小物件，不能说“一只货”，应改为“一批货”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
