INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供出售的物品；商品。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xuɔ˥˩", "syllable_count": 1, "sentences": [{"text": "这批货明天就能卖完。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这批货是刚到的。", "target_word": "货", "complexity_tier": "T3", "furigana": "lǎo bǎn shuō zhè pī huò shì gāng dào de", "sentence_source": "generated"}, {"text": "他的货又好又便宜，很多人来买。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货太多了，小店放不下。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种货现在很好卖。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上的货越来越多了。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖不出去的货只能放在仓库里。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在给客人看新到的货。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的货卖得很快。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把手里的货卖个好价钱。", "target_word": "货", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货", "label": "量词"}, {"form": "一车货", "label": "量词"}, {"form": "貨", "label": "繁体"}], "register": "口语", "sense_fingerprint": "批发或销售的商品，指整批或成堆待售的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：货 huò，指供出售的物品。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò 声调不同，意思是活着、灵活。"}, {"text": "过", "is_correct": false, "explanation": "guò 与 huò 声母不同（g 与 h），意思是经过、过去。"}, {"text": "扩", "is_correct": false, "explanation": "kuò 与 huò 声母不同（k 与 h），意思是扩大。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 huò 韵母不同（ua 与 uo），意思是话语。"}], "explanations": {"货": "正确答案：货 huò，指供出售的物品。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。", "活": "huó（第二声）与 huò 声调不同，意思是活着、灵活。", "过": "guò 与 huò 声母不同（g 与 h），意思是经过、过去。", "扩": "kuò 与 huò 声母不同（k 与 h），意思是扩大。", "话": "huà 与 huò 韵母不同（ua 与 uo），意思是话语。"}, "sentence_index": null, "correct_answer": "货"}, "level_3": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：“这批货”指待售的物品，与“卖完”搭配。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不能像商品一样被成批卖完。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“卖完”不能搭配“作业”，作业不是待售的东西。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能成批出售，也谈不上“卖完”。"}], "explanations": {"货": "正确答案：“这批货”指待售的物品，与“卖完”搭配。", "学生": "语义：学生是人，不能像商品一样被成批卖完。", "作业": "搭配：“卖完”不能搭配“作业”，作业不是待售的东西。", "空气": "语义：空气不能成批出售，也谈不上“卖完”。"}, "sentence_index": 0, "correct_answer": "货"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈送了我一个生日货。", "explanation": "这里应该用〈礼物〉。货指供出售的商品，送给别人的东西要说礼物，不说货。"}, {"text": "这场晚会的货很精彩。", "explanation": "这里应该用〈节目〉。货指供出售的商品，晚会上的表演要说节目。"}, {"text": "老师奖给他一件货。", "explanation": "这里应该用〈奖品〉。货指供出售的商品，颁给学生的奖励要说奖品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：货 huò，指供出售的物品。"}, {"text": "错", "is_correct": false, "explanation": "cuò 与 huò 声母不同（c 与 h），声调相同，意思是错误。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 huò 韵母不同（u 与 uo），意思是住户、门户。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 huò 韵母不同（ui 与 uo），意思是会议、会不会。"}, {"text": "画", "is_correct": false, "explanation": "huà 与 huò 韵母不同（ua 与 uo），意思是图画、画画。"}], "explanations": {"货": "正确答案：货 huò，指供出售的物品。", "错": "cuò 与 huò 声母不同（c 与 h），声调相同，意思是错误。", "户": "hù 与 huò 韵母不同（u 与 uo），意思是住户、门户。", "会": "huì 与 huò 韵母不同（ui 与 uo），意思是会议、会不会。", "画": "huà 与 huò 韵母不同（ua 与 uo），意思是图画、画画。"}, "sentence_index": null, "correct_answer": "货"}, "level_3": {"options": [{"text": "货", "is_correct": true, "explanation": "正确答案：“卖不出去的货”指卖不掉的待售物品，放进仓库合理。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子是人，不能“卖不出去”，也不能放在仓库里。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“卖不出去”不能搭配“太阳”，太阳也不能放进仓库。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想无法放进仓库，也不是待售的东西。"}], "explanations": {"货": "正确答案：“卖不出去的货”指卖不掉的待售物品，放进仓库合理。", "孩子": "语义：孩子是人，不能“卖不出去”，也不能放在仓库里。", "太阳": "搭配：“卖不出去”不能搭配“太阳”，太阳也不能放进仓库。", "思想": "语义：思想无法放进仓库，也不是待售的东西。"}, "sentence_index": 6, "correct_answer": "货"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一次进了一张货。", "explanation": "量词用错：“张”用于纸张、桌子等扁平物，货不用“张”计量，应说“一批货”或“一车货”。"}, {"text": "仓库里堆着一头货。", "explanation": "量词用错：“头”用于牲畜等动物，货不用“头”计量，应说“一批货”或“一车货”。"}, {"text": "我们店今天到了一根货。", "explanation": "量词用错：“根”用于细长的东西，货不用“根”计量，应说“一车货”或“一批货”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些卖不出去货要尽快降价处理。", "corrected_sentence": "这些卖不出去的货要尽快降价处理。", "error_description": "漏字：“卖不出去”修饰“货”时要加“的”，应说“卖不出去的货”，漏掉“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里今天来了一只货。", "corrected_sentence": "仓库里今天来了一车货。", "error_description": "量词错误：货按车或批计量，“只”用于动物或单个小物件，不能说“一只货”，应改为“一车货”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
