INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "体制是一个地方或一个单位里，做事和管事的办法。", "primary_collocate": null, "pronunciation": "tǐ zhì", "ipa": "tʰi˨˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的体制很灵活。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想改变现在的管理体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的人还不熟悉这里的体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢单位里的旧体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个医院的体制让工作很有效率。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们部门的体制比较宽松，大家可以自己安排时间。", "target_word": "体制", "complexity_tier": "T3", "furigana": "wǒ men bù mén de tǐ zhì bǐ jiào kuān sōng, dà jiā kě yǐ zì jǐ ān pái shí jiān.", "sentence_source": "generated"}, {"text": "他在这个体制里工作了十年。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的学校有不同的体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的体制能让大家做事更快。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的体制改了以后，工作方便多了。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "體制", "label": "繁体"}, {"form": "管理体制", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个地方或单位里做事和管事的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "正确：“体制”指单位的办事和管事方式，可以说“很灵活”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是公司的办事方式，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“身材”指人的身形，不用来描述公司，与“很灵活”也不搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来描述公司的办事方法。"}], "explanations": {"体制": "正确：“体制”指单位的办事和管事方式，可以说“很灵活”。", "声音": "语义：声音不是公司的办事方式，句子说不通。", "身材": "搭配：“身材”指人的身形，不用来描述公司，与“很灵活”也不搭配。", "颜色": "语义：颜色不能用来描述公司的办事方法。"}, "sentence_index": 0, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体制很好，每天都跑步。", "explanation": "这里应该用〈体质〉。“体制”指组织的制度，说人的身体素质要用“体质”。"}, {"text": "这件衣服的体制很漂亮。", "explanation": "这里应该用〈颜色〉。“漂亮”形容外观和颜色，体制是组织的制度，不能这样形容衣服。"}, {"text": "今天的体制很好。", "explanation": "这里应该用〈天气〉。“体制”是组织的制度，不能用来描述天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "正确：“这个体制”指单位的管理制度，他在里面工作，符合句子。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是工作的地方，句子说不通。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“在……里工作”的“里”前面要接单位或场所，早餐不能作场所。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是工作的地方，句子说不通。"}], "explanations": {"体制": "正确：“这个体制”指单位的管理制度，他在里面工作，符合句子。", "冰箱": "语义：冰箱不是工作的地方，句子说不通。", "早餐": "搭配：“在……里工作”的“里”前面要接单位或场所，早餐不能作场所。", "课本": "语义：课本不是工作的地方，句子说不通。"}, "sentence_index": 6, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都拿到体制。", "explanation": "这里应该用〈工资〉。“拿到”的是钱或奖金，体制是制度，不能被拿到。"}, {"text": "她每天早上都喝体制。", "explanation": "这里应该用〈牛奶〉。“喝”的是饮品，体制是组织的制度，不能被喝。"}, {"text": "这个体制很好听。", "explanation": "这里应该用〈音乐〉。“好听”形容声音或歌曲，体制是制度，不能被听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个单位换了一只体制。", "corrected_sentence": "这个单位换了一套体制。", "error_description": "错误形式：一只体制。“体制”的量词应该用“套”，“只”多用于动物，不能用来数体制。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没在别的公司见了这种体制。", "corrected_sentence": "我没在别的公司见过这种体制。", "error_description": "错误形式：没见了。表示经历的否定要用“没……过”，正确形式是“没见过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
