INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家机关、企业等的组织制度和管理办法。", "primary_collocate": null, "pronunciation": "tǐ zhì", "ipa": "tʰi˨˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家有自己的政治体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正在改革经济体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业的管理体制要跟着时代变。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过中国的教育体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗体制改革让看病更方便。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家大企业有一套完整的组织体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家机关的体制和公司不一样。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的体制差别很大。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解这个国家的法律体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定改变旧的体制。", "target_word": "体制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "體制", "label": "繁体"}, {"form": "政治体制", "label": "复合"}, {"form": "经济体制", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家机关、企业等的组织制度和管理办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "正确：“政治体制”指国家的政治制度，符合句子的语境。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是政治制度，“政治食物”没有意义。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋不是政治制度，句子说不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“政治”不能修饰面积，搭配不当。"}], "explanations": {"体制": "正确：“政治体制”指国家的政治制度，符合句子的语境。", "食物": "语义：食物不是政治制度，“政治食物”没有意义。", "房屋": "语义：房屋不是政治制度，句子说不通。", "面积": "搭配：“政治”不能修饰面积，搭配不当。"}, "sentence_index": 0, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体制很健康，每天都锻炼。", "explanation": "这里应该用〈身体〉。“体制”指组织或国家的制度，形容人的健康要用“身体”。"}, {"text": "这个国家的体制很丰富。", "explanation": "这里应该用〈文化〉。“丰富”形容文化、知识等，体制是制度，不能这样形容。"}, {"text": "他呼吸着新鲜的体制。", "explanation": "这里应该用〈空气〉。人呼吸的是空气，体制是抽象的制度，不能被呼吸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "正确：“体制”指机关和公司等的组织制度，可以用来比较两者的不同。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不是机关或公司的特点，句子说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能用来比较机关和公司的组织方式，句子说不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”只能和声音、设备搭配，不能用来说国家机关。"}], "explanations": {"体制": "正确：“体制”指机关和公司等的组织制度，可以用来比较两者的不同。", "香蕉": "语义：香蕉不是机关或公司的特点，句子说不通。", "钥匙": "语义：钥匙不能用来比较机关和公司的组织方式，句子说不通。", "音量": "搭配：“音量”只能和声音、设备搭配，不能用来说国家机关。"}, "sentence_index": 6, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带着体制出门了。", "explanation": "这里应该用〈伞〉。“带着”的是具体的东西，体制是抽象的制度，不能被带着出门。"}, {"text": "他握着体制开车。", "explanation": "这里应该用〈方向盘〉。“握”的是具体的东西，体制是制度，不能被握着。"}, {"text": "他写完了体制。", "explanation": "这里应该用〈作业〉。“写完”的是文字作业，体制是制度，不能被写完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家从来没改革了体制。", "corrected_sentence": "这个国家从来没改革过体制。", "error_description": "错误形式：没改革了。表示经历的否定要用“没……过”，正确形式是“没改革过”，“了”在这里不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学习了一只新的体制。", "corrected_sentence": "我们学习了一套新的体制。", "error_description": "错误形式：一只体制。“体制”的量词应该用“套”，“只”多用于动物，不能用来数体制。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
