INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "过去很有钱、很有地位的人家，住在大房子里。", "primary_collocate": null, "pronunciation": "guì zú", "ipa": "kwei˥˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "这个贵族家庭住在一座很大的房子里。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "zhè ge guì zú jiā tíng zhù zài yí zuò hěn dà de fáng zi lǐ.", "sentence_source": "generated"}, {"text": "古时候，贵族家里有很多仆人。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个贵族家庭有很多钱，也有很高的地位。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "nà ge guì zú jiā tíng yǒu hěn duō qián, yě yǒu hěn gāo de dì wèi.", "sentence_source": "generated"}, {"text": "贵族的孩子从小就请老师来家里教书。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是贵族家庭和穷人家的友情。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "zhè ge gù shi jiǎng de shì guì zú jiā tíng hé qióng rén jiā de yǒu qíng.", "sentence_source": "generated"}, {"text": "他家过去是贵族家庭，现在的房子还是很大。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "tā jiā guò qù shì guì zú jiā tíng, xiàn zài de fáng zi hái shì hěn dà.", "sentence_source": "generated"}, {"text": "贵族家庭常常在大房子里开舞会。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "guì zú jiā tíng cháng cháng zài dà fáng zi lǐ kāi wǔ huì.", "sentence_source": "generated"}, {"text": "那个贵族家庭的人每天坐马车出门。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "nà ge guì zú jiā tíng de rén měi tiān zuò mǎ chē chū mén.", "sentence_source": "generated"}, {"text": "这个贵族家庭的客厅里挂着很多旧画。", "target_word": "贵族", "complexity_tier": "T3", "furigana": "zhè ge guì zú jiā tíng de kè tīng lǐ guà zhe hěn duō jiù huà.", "sentence_source": "generated"}, {"text": "贵族家的花园大得像一个公园。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "贵族学校", "label": "复合"}, {"form": "貴族", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过去有钱有地位、住大房子的人家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贵族", "is_correct": true, "explanation": "正确：指过去很有钱、很有地位的人家，与“住在一座很大的房子里”相符。"}, {"text": "穷人", "is_correct": false, "explanation": "语义：“穷人”没有钱，一般住不起很大的房子，与句中的描述矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：“乞丐”没有固定住处，与“住在一座很大的房子里”明显矛盾。"}, {"text": "难民", "is_correct": false, "explanation": "搭配：“难民”一般与“逃离、收容”等搭配，不与“住在很大的房子里”搭配。"}], "explanations": {"贵族": "正确：指过去很有钱、很有地位的人家，与“住在一座很大的房子里”相符。", "穷人": "语义：“穷人”没有钱，一般住不起很大的房子，与句中的描述矛盾。", "乞丐": "语义：“乞丐”没有固定住处，与“住在一座很大的房子里”明显矛盾。", "难民": "搭配：“难民”一般与“逃离、收容”等搭配，不与“住在很大的房子里”搭配。"}, "sentence_index": 0, "correct_answer": "贵族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠做生意发了财，现在是一位贵族。", "explanation": "这里应该用〈富人〉。贵族指过去很有钱、很有地位的人家，靠做生意发财的现代人应说富人。"}, {"text": "村里那户贵族原来是卖豆腐的，近年才有钱盖了三层楼。", "explanation": "这里应该用〈富户〉。贵族指过去很有钱、很有地位的人家，原本卖豆腐、近年致富的人家应说富户。"}, {"text": "他年轻时没读过书，后来靠炒股成了一个贵族。", "explanation": "这里应该用〈富翁〉。贵族指过去很有钱、很有地位的人家，靠炒股致富的人应说富翁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贵族", "is_correct": true, "explanation": "正确：指过去很有钱、很有地位的人家，常在大房子里开舞会，符合句意。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”一般住不了很大的房子，也不会在大房子里开舞会，与句意矛盾。"}, {"text": "老百姓", "is_correct": false, "explanation": "语域：“老百姓”是口语化的泛称，与书面化的“贵族家庭”语境不搭，且与“开舞会”的描述不符。"}, {"text": "工人", "is_correct": false, "explanation": "语义：“工人”通常没有大房子和舞会，与句中的描述矛盾。"}], "explanations": {"贵族": "正确：指过去很有钱、很有地位的人家，常在大房子里开舞会，符合句意。", "农民": "语义：“农民”一般住不了很大的房子，也不会在大房子里开舞会，与句意矛盾。", "老百姓": "语域：“老百姓”是口语化的泛称，与书面化的“贵族家庭”语境不搭，且与“开舞会”的描述不符。", "工人": "语义：“工人”通常没有大房子和舞会，与句中的描述矛盾。"}, "sentence_index": 6, "correct_answer": "贵族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们家是靠炒房子发财的，算是一个贵族。", "explanation": "这里应该用〈暴发户〉。贵族指过去很有钱、很有地位的人家，新近靠炒房致富的人应说暴发户。"}, {"text": "村东头那个贵族原是个打铁的，去年才买下了三十多亩地。", "explanation": "这里应该用〈财主〉。贵族指过去很有钱、很有地位的人家，原本做手艺、近年致富的人家应说财主。"}, {"text": "他家是村里的贵族，去年才靠倒卖化肥发了财。", "explanation": "这里应该用〈土豪〉。贵族指过去很有钱、很有地位的人家，靠倒卖化肥近年暴富的人应说土豪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家附近住着一只贵族。", "corrected_sentence": "他家附近住着一户贵族。", "error_description": "量词错误：指家庭的“贵族”应用量词“户”，不能用“只”（“只”不用于人家或人）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只贵族家庭的孩子都很有礼貌。", "corrected_sentence": "这户贵族家庭的孩子都很有礼貌。", "error_description": "量词错误：“贵族家庭”指一户人家，应用量词“户”，不能用“只”（“只”不用于人家）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平民", "is_correct": true, "explanation": "正确：与“贵族”相对，指没有世袭特权的普通人。"}, {"text": "商人", "is_correct": false, "explanation": "商人指做买卖的人，与“贵族”在社会阶层的意义上不构成反义。"}, {"text": "工人", "is_correct": false, "explanation": "工人指从事体力或机器劳动的人，与“贵族”不构成反义。"}, {"text": "学者", "is_correct": false, "explanation": "学者指做学问的人，与“贵族”不构成反义。"}], "correct_answer": "平民", "explanations": {"平民": "正确：与“贵族”相对，指没有世袭特权的普通人。", "商人": "商人指做买卖的人，与“贵族”在社会阶层的意义上不构成反义。", "工人": "工人指从事体力或机器劳动的人，与“贵族”不构成反义。", "学者": "学者指做学问的人，与“贵族”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平民", "is_correct": true, "explanation": "正确：与“贵族”相对，指没有世袭特权的普通人。"}, {"text": "厨师", "is_correct": false, "explanation": "厨师指做饭的人，与“贵族”不构成反义。"}, {"text": "教师", "is_correct": false, "explanation": "教师指教书的人，与“贵族”不构成反义。"}, {"text": "士兵", "is_correct": false, "explanation": "士兵指军人，与“贵族”不构成反义。"}], "correct_answer": "平民", "explanations": {"平民": "正确：与“贵族”相对，指没有世袭特权的普通人。", "厨师": "厨师指做饭的人，与“贵族”不构成反义。", "教师": "教师指教书的人，与“贵族”不构成反义。", "士兵": "士兵指军人，与“贵族”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会中享有世袭特权和较高地位的阶层，也指这一阶层的成员。", "primary_collocate": null, "pronunciation": "guì zú", "ipa": "kwei˥˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "在古代欧洲，贵族享有很多特权。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵族的地位是从父母那里传下来的。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的贵族和平民差别很大。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的祖先是贵族，所以他生下来就有头衔。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王把土地送给了贵族。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵族不用交税，平民却要交很多税。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后来这个国家取消了贵族的特权。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法国大革命改变了贵族的命运。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个社会里，只有贵族才能当大官。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国现在还有贵族，他们有自己的头衔。", "target_word": "贵族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "贵族阶层", "label": "复合"}, {"form": "貴族", "label": "繁体"}], "register": "中性", "sense_fingerprint": "享有世袭特权的社会阶层及其成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贵族", "is_correct": true, "explanation": "正确：指享有世袭特权的社会阶层，与“享有很多特权”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”一般没有世袭特权，与“享有很多特权”矛盾。"}, {"text": "奴隶", "is_correct": false, "explanation": "语义：“奴隶”没有任何特权，与“享有很多特权”的意思相反。"}, {"text": "庶民", "is_correct": false, "explanation": "语域：“庶民”是中国古代的书面称谓，用于古代欧洲的语境不妥，且与“享有很多特权”矛盾。"}], "explanations": {"贵族": "正确：指享有世袭特权的社会阶层，与“享有很多特权”相符。", "农民": "语义：“农民”一般没有世袭特权，与“享有很多特权”矛盾。", "奴隶": "语义：“奴隶”没有任何特权，与“享有很多特权”的意思相反。", "庶民": "语域：“庶民”是中国古代的书面称谓，用于古代欧洲的语境不妥，且与“享有很多特权”矛盾。"}, "sentence_index": 0, "correct_answer": "贵族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在那个社会里，贵族靠考试才能进入政府当官。", "explanation": "这里应该用〈精英〉。贵族指享有世袭特权的阶层，靠考试进入政府的人应说精英。"}, {"text": "这个国家的贵族由全体选民投票产生。", "explanation": "这里应该用〈议员〉。贵族指享有世袭特权的阶层，由选民投票产生的人应说议员。"}, {"text": "他从小在农村长大，父母都是普通农民，他自己也是一个贵族。", "explanation": "这里应该用〈平民〉。贵族的身份是世袭的，父母是普通农民的人不属于贵族，应说平民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贵族", "is_correct": true, "explanation": "正确：指享有世袭特权的阶层，“取消了……的特权”与之相符。"}, {"text": "平民", "is_correct": false, "explanation": "语义：平民本来就没有特权，“取消了平民的特权”讲不通。"}, {"text": "仆人", "is_correct": false, "explanation": "语义：仆人一般没有什么特权，与“取消了……的特权”的语境不合。"}, {"text": "百姓", "is_correct": false, "explanation": "语域：“百姓”是口语化的泛称，与书面化的“取消特权”语境不搭，且百姓少有特权可取消。"}], "explanations": {"贵族": "正确：指享有世袭特权的阶层，“取消了……的特权”与之相符。", "平民": "语义：平民本来就没有特权，“取消了平民的特权”讲不通。", "仆人": "语义：仆人一般没有什么特权，与“取消了……的特权”的语境不合。", "百姓": "语域：“百姓”是口语化的泛称，与书面化的“取消特权”语境不搭，且百姓少有特权可取消。"}, "sentence_index": 6, "correct_answer": "贵族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他父亲是个普通工人，他靠做生意发了财，也算是一个贵族。", "explanation": "这里应该用〈新贵〉。贵族的身份是世袭的，父亲是普通工人的人，靠做生意发财只能说新贵。"}, {"text": "他的祖父是个木匠，他去年靠选票当上了村里的领导，也算一个贵族。", "explanation": "这里应该用〈村干部〉。贵族的身份是世袭的，祖上是木匠的人，靠选票当选只能说村干部。"}, {"text": "那位贵族在菜市场卖了二十年猪肉，他家祖祖辈辈都以杀猪为生。", "explanation": "这里应该用〈屠户〉。贵族指享有世袭特权的阶层，世代以杀猪为业的人应说屠户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国王把土地送给了三只贵族。", "corrected_sentence": "国王把土地送给了三位贵族。", "error_description": "量词错误：指人的“贵族”应用量词“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是那个国家里最有权势的一只贵族。", "corrected_sentence": "他是那个国家里最有权势的一位贵族。", "error_description": "量词错误：指人的“贵族”应用量词“位”，不能用“只”（“只”不用于人）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
