INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的一生;人的生活经历。", "primary_collocate": null, "pronunciation": "rén shēng", "ipa": "ʐən˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这本书讲的是一位老人的人生故事。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的人有不同的人生经历。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读了这本书,我对人生有了新的看法。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他的人生里,音乐一直很重要。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的人生因为那次旅行改变了。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的人生经历很丰富,去过很多国家。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生中最难忘的一天,是我结婚那天。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说,读书能让人生更有意思。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写一本关于自己人生的书。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学四年是人生中很重要的一段时间。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段人生", "label": "量词"}, {"form": "人生观", "label": "复合"}, {"form": "人生路", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词:人的一生,人的生活经历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89396, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生（rén shēng）指人的一生和生活经历，是正确答案。"}, {"text": "人称", "is_correct": false, "explanation": "sh 与 ch 声母不同，人称（rén chēng）指人称代词的类别，不是生活经历。"}, {"text": "人参", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（ng 与 n），人参是一种中药材。"}, {"text": "认生", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，认生指小孩怕见陌生人。"}], "explanations": {"人生": "人生（rén shēng）指人的一生和生活经历，是正确答案。", "人称": "sh 与 ch 声母不同，人称（rén chēng）指人称代词的类别，不是生活经历。", "人参": "shēng 与 shēn 韵母不同（ng 与 n），人参是一种中药材。", "认生": "rén（第二声）与 rèn（第四声）声调不同，认生指小孩怕见陌生人。"}, "sentence_index": null, "correct_answer": "人生"}, "level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生指人的生活经历，可以讲成“故事”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的经历，不能讲成“故事”。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指一群人的总数，不是个人的经历。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“故事”不搭配“价格”，价格不能讲成故事。"}], "explanations": {"人生": "人生指人的生活经历，可以讲成“故事”。", "天气": "语义：天气不是人的经历，不能讲成“故事”。", "人口": "语义：人口指一群人的总数，不是个人的经历。", "价格": "搭配：“故事”不搭配“价格”，价格不能讲成故事。"}, "sentence_index": 0, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在菜市场称了三斤人生。", "explanation": "这里不这么用。“人生”指人的一生或经历，是抽象的，不是可以称重的具体物品；菜市场称重的应是〈蔬菜〉这类食物。"}, {"text": "会议室里坐着二十个人生。", "explanation": "这里不这么用。人生不用来计数人，指人应说“人”。"}, {"text": "他把人生切成几片装在盒子里。", "explanation": "这里不这么用。“人生”指人的一生或经历，是抽象的，不是可以切片装盒的食物，切片装盒的应是〈蛋糕〉这类东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生指一生的经历，可以说“人生中最难忘的一天”。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁不会有“最难忘的一天”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是经历的范围，“水果中最难忘的一天”没有意义。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重中最难忘的一天”不搭配，体重是身体数据。"}], "explanations": {"人生": "人生指一生的经历，可以说“人生中最难忘的一天”。", "墙壁": "语义：墙壁不会有“最难忘的一天”。", "水果": "语义：水果不是经历的范围，“水果中最难忘的一天”没有意义。", "体重": "搭配：“体重中最难忘的一天”不搭配，体重是身体数据。"}, "sentence_index": 6, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的人生有五年。", "explanation": "这里应该用〈寿命〉。“人生”只用于人，电脑等物品的使用年限要说“寿命”。"}, {"text": "这座城市的人生已经有两千年了。", "explanation": "这里应该用〈历史〉。“人生”只用于人，城市的存在年限要说“历史”。"}, {"text": "我家有一条人生。", "explanation": "这里应该用〈段〉。人生作为经历的量词是“段”，不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一座很丰富的人生。", "corrected_sentence": "他有一段很丰富的人生。", "error_description": "错误：“人生”指一段经历，量词应为“段”，不能用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的人生过地很精彩。", "corrected_sentence": "她的人生过得很精彩。", "error_description": "错误：补语标记应用「得」，「过地」误用了状语标记「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
