INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89408, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "抓紧时间，加快速度。", "primary_collocate": null, "pronunciation": "gǎn kuài", "ipa": "kan˨˩ kʰuaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "时间不多了，我们赶快做吧。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离考试只有三天，要赶快复习。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大家赶快把作业交上来。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车八点开，我们得赶快出门。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，赶快把活儿干完。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快开始了，他赶快换好了衣服。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机会不多，你要赶快决定。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店六点关门，我们赶快去买。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还有十分钟，赶快写完这一页。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪要来了，农民赶快收粮食。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趕快", "label": "繁体"}], "register": "中性", "sense_fingerprint": "因时间有限而抓紧做事，常与时间紧迫的原因连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶快", "is_correct": true, "explanation": "正确答案：“时间不多了，我们赶快做吧”表示因时间紧而抓紧做事。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：时间不多时说“慢慢做”，与语境相反。"}, {"text": "从容", "is_correct": false, "explanation": "语域：“从容”偏书面，且与“时间不多”的紧迫语境相反。"}, {"text": "不必", "is_correct": false, "explanation": "语义：时间不多时说“不必做”，与语境矛盾。"}], "explanations": {"赶快": "正确答案：“时间不多了，我们赶快做吧”表示因时间紧而抓紧做事。", "慢慢": "语义：时间不多时说“慢慢做”，与语境相反。", "从容": "语域：“从容”偏书面，且与“时间不多”的紧迫语境相反。", "不必": "语义：时间不多时说“不必做”，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "赶快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我赶快在这家公司工作了十年。", "explanation": "这里应该用〈一直〉。赶快表示抓紧时间做事，长期持续的工作不能用赶快修饰。"}, {"text": "我赶快学会了游泳，用了三年时间。", "explanation": "这里应该用〈逐渐〉。赶快强调加快速度，三年的学习过程是逐渐掌握，要说逐渐。"}, {"text": "他赶快爱上了这座小城，每天都舍不得走。", "explanation": "这里应该用〈慢慢〉。赶快表示抓紧行动，对一座城市产生感情是逐渐的，要说慢慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶快", "is_correct": true, "explanation": "正确答案：“机会不多，你要赶快决定”表示因机会有限而抓紧做事。"}, {"text": "缓缓", "is_correct": false, "explanation": "语义：机会不多时说“缓缓决定”，与紧迫的语境相反。"}, {"text": "悠然", "is_correct": false, "explanation": "语域：“悠然”偏书面，与这种口语语境不符。"}, {"text": "慢悠悠", "is_correct": false, "explanation": "语义：机会不多时说“慢悠悠决定”，与语境矛盾。"}], "explanations": {"赶快": "正确答案：“机会不多，你要赶快决定”表示因机会有限而抓紧做事。", "缓缓": "语义：机会不多时说“缓缓决定”，与紧迫的语境相反。", "悠然": "语域：“悠然”偏书面，与这种口语语境不符。", "慢悠悠": "语义：机会不多时说“慢悠悠决定”，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "赶快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个病人赶快病了好几个月。", "explanation": "这里应该用〈一直〉。赶快表示抓紧时间，持续几个月的病不能用赶快修饰。"}, {"text": "他赶快缓缓地走过了马路。", "explanation": "这里应该用〈从容〉。赶快要求加快速度，缓缓地走路是不催促的样子，二者不能搭配。"}, {"text": "孩子们赶快在草地上躺了一整个下午。", "explanation": "这里应该用〈悠闲〉。赶快表示抓紧时间，整个下午躺着晒太阳是悠闲，不能用赶快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨快下来了，我们赶快了收衣服吧。", "corrected_sentence": "雨快下来了，我们赶快收衣服吧。", "error_description": "助词错误：“赶快”是副词，后面不能直接加“了”，应说“我们赶快收衣服吧”，不能说“赶快了收衣服吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时间不多了，你很赶快把钥匙找出来。", "corrected_sentence": "时间不多了，你赶快把钥匙找出来。", "error_description": "程度副词错误：“赶快”是副词，不能受程度副词“很”修饰，应说“你赶快把钥匙找出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
