INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示恰好、正好合适或正好够。", "primary_collocate": null, "pronunciation": "gāng gāng", "ipa": "kɑŋ˥ kɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这双鞋刚刚好,不大也不小。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些钱刚刚够买一张机票。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子刚刚放得下一张大床。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的天气刚刚好,不冷也不热。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间不大,放一张床刚刚好。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蛋糕刚刚分给每个人一小块。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这袋米刚刚一斤,不多也不少。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的钱刚刚够交房租,没有多的了。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些座位刚刚够全班坐下。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子刚刚能放进车里。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚", "label": "单字形式"}, {"form": "刚刚好", "label": "复合"}], "register": "中性", "sense_fingerprint": "刚刚:表示恰好,正好合适或正好够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3120a4a-a156-4081-aede-d5f843da90e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示恰好合适，与“不大也不小”相呼应。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，但句中说的是鞋子现在的大小状况。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示推测，与“不大也不小”这种确定的评价不合。"}, {"text": "行将", "is_correct": false, "explanation": "语域：“行将”是书面语，且表示尚未发生，与口语化的评价句不合。"}], "explanations": {"刚刚": "正确。“刚刚”表示恰好合适，与“不大也不小”相呼应。", "马上": "语义：“马上”表示即将发生，但句中说的是鞋子现在的大小状况。", "大概": "语义：“大概”表示推测，与“不大也不小”这种确定的评价不合。", "行将": "语域：“行将”是书面语，且表示尚未发生，与口语化的评价句不合。"}, "sentence_index": 0, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋刚刚太大了,穿不上。", "explanation": "“刚刚”表示恰好合适，与表示过分的“太”矛盾，两者不能同用。"}, {"text": "这件外套刚刚很合身，你穿吧。", "explanation": "这里误把“刚刚”当成可以受“很”修饰的程度词，与“很合身”的程度义混在一起；这种“刚刚”不能与“很”同用。"}, {"text": "这些菜刚刚很多，我们吃不完。", "explanation": "这里误把“刚刚”当成可以修饰“很多”这类笼统数量的程度词；它不能与“很多”搭配，应说“正好够”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示恰好是一斤，与“不多也不少”相合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能修饰“一斤”这样的数量。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将或立刻，与“一斤”这种既定数量不合。"}, {"text": "将", "is_correct": false, "explanation": "语域：“将”偏书面，且表示尚未发生，与“一斤”这种既定数量不合。"}], "explanations": {"刚刚": "正确。“刚刚”表示恰好是一斤，与“不多也不少”相合。", "正在": "搭配：“正在”表示动作进行中，不能修饰“一斤”这样的数量。", "马上": "语义：“马上”表示即将或立刻，与“一斤”这种既定数量不合。", "将": "语域：“将”偏书面，且表示尚未发生，与“一斤”这种既定数量不合。"}, "sentence_index": 6, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书刚刚太多，书架都放不下了。", "explanation": "“刚刚”表示恰好，与表示过分的“太”矛盾，不能同用。"}, {"text": "这间屋子刚刚很宽敞，住着很舒服。", "explanation": "这里误把“刚刚”当成可以受“很”修饰的程度词，与“很宽敞”的程度义混在一起；这种“刚刚”不能与“很”同用。"}, {"text": "他刚刚很聪明，一学就会。", "explanation": "这里误把“刚刚”当成程度副词来用；“刚刚”表示恰好，不能受“很”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子刚刚很合适,我就买了。", "corrected_sentence": "这条裤子刚刚好，我就买了。", "error_description": "“刚刚”表示恰好，不能受“很”修饰；“刚刚很合适”应去掉“很”，改为“刚刚好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的刚刚睡着了，你小声点。", "corrected_sentence": "孩子刚刚睡着了，你小声点。", "error_description": "“刚刚”是副词，不能放在“的”之后；“孩子的刚刚睡着了”应说“孩子刚刚睡着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
