INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89423, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不太坏，也不太差，还可以。", "primary_collocate": null, "pronunciation": "hái hǎo", "ipa": "xaɪ̯³⁵ xɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "我最近身体还好。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜还好，不太贵。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语还好，能听懂。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你累吗？”“还好，不太累。”", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气还好，不冷也不热。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得还好。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我住的地方还好，离学校不远。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作还好，就是有点忙。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机还好，用了三年没坏。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的生活还好，你不用担心。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不太坏也不太差；还可以，一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还好", "is_correct": true, "explanation": "正确。“还好”表示不太好也不太差，用于描述身体状况，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”用于形容外表，不能用来形容身体状况。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容身体状况。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格高，不能用来形容身体的状况。"}], "explanations": {"还好": "正确。“还好”表示不太好也不太差，用于描述身体状况，符合句意。", "漂亮": "搭配：“漂亮”用于形容外表，不能用来形容身体状况。", "甜": "搭配：“甜”形容味道，不能用来形容身体状况。", "贵": "语义：“贵”说价格高，不能用来形容身体的状况。"}, "sentence_index": 0, "correct_answer": "还好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天没有下雨，还好！", "explanation": "这里的“还好”表示庆幸没有出现更糟的结果，是另一个义项；本义项只表示“不太坏也不太差”。"}, {"text": "他差点迟到，还好赶上了火车。", "explanation": "这里的“还好”表示庆幸没有出现更糟的结果，是另一个义项；本义项只表示“不太坏也不太差”。"}, {"text": "他摔倒了，还好没有骨折。", "explanation": "这里的“还好”表示庆幸没有出现更糟的结果，是另一个义项，不能用本义项“还可以”来理解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还好", "is_correct": true, "explanation": "正确。“还好”表示还可以、不算差，用于描述住的地方，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容住的地方。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来形容住的地方。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”与后半句“离学校不远”矛盾，句意说不通。"}], "explanations": {"还好": "正确。“还好”表示还可以、不算差，用于描述住的地方，符合句意。", "咸": "搭配：“咸”形容味道，不能用来形容住的地方。", "聪明": "搭配：“聪明”形容人的智力，不能用来形容住的地方。", "远": "语义：“远”与后半句“离学校不远”矛盾，句意说不通。"}, "sentence_index": 6, "correct_answer": "还好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "还好，火车没有晚点，我们准时到了。", "explanation": "这里的“还好”表示庆幸没有出现更糟的结果，是另一个义项；本义项只表示“不太坏也不太差”。"}, {"text": "这是我还好的宝贝。", "explanation": "这里应该用〈珍贵〉。“还好”只表示不太坏也不太差，不能修饰“宝贝”这类被珍视的事物。"}, {"text": "还好他提前订了票，票没有卖完。", "explanation": "这里应该用〈幸好〉。“还好”在此要表示庆幸没有出现更糟的结果，本义项“不太坏也不太差”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近身体很还好，没有生病。", "corrected_sentence": "我最近身体还好，没有生病。", "error_description": "程度副词错误：“还好”表示“不太好也不太差”，不能用“很”修饰，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的服务还好地，价格也合理。", "corrected_sentence": "这家店的服务还好，价格也合理。", "error_description": "词尾错误：“还好”是形容词，后面不能加“地”，应删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
