INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89424, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示庆幸没有出现更糟的结果，意思接近“幸好”。", "primary_collocate": null, "pronunciation": "hái hǎo", "ipa": "xaɪ̯³⁵ xɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "还好你带了伞，我没被雨淋湿。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好我来得早，还有座位。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好没有人受伤。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好他及时给我打了电话。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好天气不冷，我们没有感冒。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好医生来得快，病人没事。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好我记得带钥匙。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好车开得不快，没出事故。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好大家都平安回来了。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还好你提醒了我，不然我就忘了。", "target_word": "还好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "庆幸；幸好，没有出现更糟的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还好", "is_correct": true, "explanation": "正确。“还好”表示庆幸没有出现更糟的结果，与后句“没被雨淋湿”呼应。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间紧接，不表示庆幸，与句意不符。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不变，不能表达庆幸没有更糟的结果。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预料相反，和“没被雨淋湿”的庆幸语气矛盾。"}], "explanations": {"还好": "正确。“还好”表示庆幸没有出现更糟的结果，与后句“没被雨淋湿”呼应。", "马上": "语义：“马上”表示时间紧接，不表示庆幸，与句意不符。", "一直": "语义：“一直”表示持续不变，不能表达庆幸没有更糟的结果。", "偏偏": "语义：“偏偏”表示与预料相反，和“没被雨淋湿”的庆幸语气矛盾。"}, "sentence_index": 0, "correct_answer": "还好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我中了彩票，还好！", "explanation": "这里应该用〈太好了〉。“还好”表示没有出现更糟的结果，不能用于值得高兴的事。"}, {"text": "这部电影还好，就是有点长。", "explanation": "这里的“还好”表示“不太坏”，是另一个义项，不是庆幸义项的用法。"}, {"text": "这幅画还好，美极了。", "explanation": "这里应该用〈非常美〉。“还好”只表示不算坏，与“美极了”的高度赞美矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还好", "is_correct": true, "explanation": "正确。“还好”表示庆幸，“我记得带钥匙”是值得庆幸的事，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何的选择，与“记得带钥匙”的语气不符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，不能表达庆幸的语气。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已完成，与句中庆幸的语气无关。"}], "explanations": {"还好": "正确。“还好”表示庆幸，“我记得带钥匙”是值得庆幸的事，符合句意。", "只好": "语义：“只好”表示无可奈何的选择，与“记得带钥匙”的语气不符。", "突然": "语义：“突然”表示事情忽然发生，不能表达庆幸的语气。", "已经": "语义：“已经”表示事情已完成，与句中庆幸的语气无关。"}, "sentence_index": 6, "correct_answer": "还好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的财务状况还好，已经欠了一亿元的债务。", "explanation": "这里应该用〈糟糕〉。“还好”只表示不算坏或庆幸没有更糟，不能用来形容一亿元债务这样的严重问题。"}, {"text": "这是我还好的宝贝。", "explanation": "这里应该用〈珍贵〉。“还好”只表示不算坏，不能修饰“宝贝”这类被珍视的事物。"}, {"text": "我拿到了奖学金，还好！", "explanation": "这里应该用〈超级开心〉。“还好”表示没有更糟，不能用于值得高兴的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不还好我昨天复习了，考试没有失败。", "corrected_sentence": "还好我昨天复习了，考试没有失败。", "error_description": "否定词错误：“还好”是表示庆幸的固定说法，前面不能加“不”。“不还好”表示“不太好”，与“考试没有失败”的庆幸语气矛盾。应去掉“不”，说“还好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很还好他提醒了我，我才没有忘记。", "corrected_sentence": "还好他提醒了我，我才没有忘记。", "error_description": "程度副词错误：“还好”本身表示庆幸，不能再用“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
