INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去或将来某个特定的日子。", "primary_collocate": null, "pronunciation": "nà tiān", "ipa": "na˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "下个月十号是我生日，那天你有空吗？", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛定在周六，那天我们一起去看。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了那天，别忘了带身份证。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚那天，天气一定很好。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好考试那天一起吃饭。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，朋友会来帮忙。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等到那天，你就会明白我的话。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，大家都哭了。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学那天，我要早点起床。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我那天几点出发。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那一天", "label": "扩展形式"}], "register": "中性", "sense_fingerprint": "指上文提到的、过去或将来某个特定的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那天", "is_correct": true, "explanation": "“那天”指某个特定的日子，这里指下个月十号，合适。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“今天”是现在，与“下个月十号”矛盾。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”是过去，与“下个月十号”矛盾。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是一天，“时间你有空吗”不通。"}], "explanations": {"那天": "“那天”指某个特定的日子，这里指下个月十号，合适。", "今天": "搭配：“今天”是现在，与“下个月十号”矛盾。", "昨天": "搭配：“昨天”是过去，与“下个月十号”矛盾。", "时间": "语义：“时间”不是一天，“时间你有空吗”不通。"}, "sentence_index": 0, "correct_answer": "那天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那天我在国外住了三年，很想家。", "explanation": "这里应该用〈那段时间〉。“那天”只指一天，不能用来说住了几年的事；说一段时间要用“那段时间”。"}, {"text": "我们全家一直住在那天。", "explanation": "这里应该用〈那里〉。“住在”后面要说地点，“那天”是时间，不能指住的地方。"}, {"text": "那天是我的朋友。", "explanation": "这里应该用〈那个人〉。指人要用“那个人”，“那天”指日子，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那天", "is_correct": true, "explanation": "“那天”指将来或过去的某个日子，这里是“等到那天”，合适。"}, {"text": "上周", "is_correct": false, "explanation": "搭配：“等到”指将来的时间点，“上周”是过去，不搭配。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是一周的单位，“等到星期”不能指一个确定的日子。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是时间，“等到冰箱”不通。"}], "explanations": {"那天": "“那天”指将来或过去的某个日子，这里是“等到那天”，合适。", "上周": "搭配：“等到”指将来的时间点，“上周”是过去，不搭配。", "星期": "语义：“星期”是一周的单位，“等到星期”不能指一个确定的日子。", "冰箱": "语义：“冰箱”不是时间，“等到冰箱”不通。"}, "sentence_index": 6, "correct_answer": "那天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们还没定好日期，那天咱们一起吃饭吧。", "explanation": "这里应该用〈哪天〉。还没定下来的日子要用“哪天”，“那天”指双方已经知道的某一天。"}, {"text": "那天很贵，我没买。", "explanation": "这里应该用〈那个〉。“那个”指东西，“那天”只指日子，不能用来指物品。"}, {"text": "我们那天每天都去公园。", "explanation": "这里应该用〈每天〉。“那天”指某一天，与“每天”矛盾；说反复做的事要用“每天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们那的天一起去了海边。", "corrected_sentence": "我们那天一起去了海边。", "error_description": "错误：“那”与“天”之间多加了“的”，“那天”是一个整体的时间词，不能拆开。正确：应说“我们那天一起去了海边”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一那天，我一直在家里看书。", "corrected_sentence": "那一天，我一直在家里看书。", "error_description": "数词“一”要放在指示词“那”后面，应说“那一天”，不能说“一那天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谦虚", "is_correct": true, "explanation": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难或危险，与“骄傲”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人亲切主动，与“骄傲”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指反应快、有智慧，与“骄傲”没有反义关系。"}], "correct_answer": "谦虚", "explanations": {"谦虚": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。", "勇敢": "“勇敢”指不怕困难或危险，与“骄傲”没有反义关系。", "热情": "“热情”指待人亲切主动，与“骄傲”没有反义关系。", "聪明": "“聪明”指反应快、有智慧，与“骄傲”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谦虚", "is_correct": true, "explanation": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“骄傲”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”与“复杂”相对，与“骄傲”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好、待人友善，与“骄傲”没有反义关系。"}], "correct_answer": "谦虚", "explanations": {"谦虚": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。", "安静": "“安静”与“吵闹”相对，与“骄傲”没有反义关系。", "简单": "“简单”与“复杂”相对，与“骄傲”没有反义关系。", "善良": "“善良”指心地好、待人友善，与“骄傲”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "觉得自己很好，别人都不如自己。", "primary_collocate": null, "pronunciation": "jiāo ào", "ipa": "tɕjɑʊ˥ ɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他觉得自己最好，太骄傲了。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很骄傲，从来不听别人的话。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骄傲的人看不起别人。", "target_word": "骄傲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别那么骄傲，你也有错的时候。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直很骄傲，所以朋友越来越少。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子骄傲得谁都不理。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理骄傲地说：“这里没有人比我强。”", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他赢了一次就骄傲了，不想再学习。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的骄傲让同事们很不舒服。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骄傲的小王觉得别人都不如他。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骄傲地", "label": "状语形式"}, {"form": "骄傲自满", "label": "复合"}, {"form": "驕傲", "label": "繁体"}], "register": "通用", "sense_fingerprint": "骄傲：自以为了不起、看不起别人的态度，含贬义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骄傲", "is_correct": true, "explanation": "“骄傲”指自以为了不起、看不起别人，与“觉得自己最好”的语境一致。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”与“觉得自己最好”的自信态度相矛盾，句意不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”说身高，与自我评价无关，句意不通。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”与“觉得自己最好”相矛盾，句意不通。"}], "explanations": {"骄傲": "“骄傲”指自以为了不起、看不起别人，与“觉得自己最好”的语境一致。", "懦弱": "语义：“懦弱”与“觉得自己最好”的自信态度相矛盾，句意不通。", "矮": "体貌：“矮”说身高，与自我评价无关，句意不通。", "胆小": "语义：“胆小”与“觉得自己最好”相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "骄傲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被人误会了，心里很骄傲，气得直跺脚。", "explanation": "这里应该用〈生气〉。骄傲表示觉得自己比别人好，不能表示被误会后的恼怒。"}, {"text": "失败后，他骄傲地哭了起来。", "explanation": "这里应该用〈伤心〉。骄傲表示自满，不能用来形容伤心哭泣的样子。"}, {"text": "听到雷声，他骄傲地躲进了被子里。", "explanation": "这里应该用〈害怕〉。骄傲表示觉得自己比别人好，不能用来形容躲进被子、胆怯的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骄傲", "is_correct": true, "explanation": "“骄傲”表示看不起别人，与“这里没有人比我强”的自夸语气一致。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”与自夸的语气不符，句意不通。"}, {"text": "客气", "is_correct": false, "explanation": "语义：“客气”表示谦让有礼，与“这里没有人比我强”的自夸语气矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”说身高，不能用来修饰说话的样子。"}], "explanations": {"骄傲": "“骄傲”表示看不起别人，与“这里没有人比我强”的自夸语气一致。", "悲伤": "语义：“悲伤”与自夸的语气不符，句意不通。", "客气": "语义：“客气”表示谦让有礼，与“这里没有人比我强”的自夸语气矛盾。", "高": "体貌：“高”说身高，不能用来修饰说话的样子。"}, "sentence_index": 6, "correct_answer": "骄傲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向老师认错时，很骄傲地红了脸。", "explanation": "这里应该用〈不好意思〉。骄傲表示觉得自己比别人好，不能用来形容认错时脸红窘迫的样子。"}, {"text": "上台前，他骄傲地捂着嘴，小声地问：“我能不能不上去？”", "explanation": "这里应该用〈胆怯〉。骄傲表示觉得自己比别人好，与小声恳求不上去的样子相矛盾。"}, {"text": "他一进教室就很骄傲地低下了头。", "explanation": "这里应该用〈害羞〉。低头表示害羞，与骄傲的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骄傲的看了我们一眼，什么话也没说。", "corrected_sentence": "他骄傲地看了我们一眼，什么话也没说。", "error_description": "错误形式“骄傲的看”；正确形式“骄傲地看”。动词前的状语要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近突然骄傲下来了。", "corrected_sentence": "他最近突然骄傲起来了。", "error_description": "“骄傲”表示状态开始出现时要用趋向补语“起来”；“下来”多用于表示平静、减弱的状态（如“安静下来”），与“骄傲”搭配不自然。错误形式“骄傲下来”，正确形式为“骄傲起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "部分", "is_correct": true, "explanation": "正确。“部分”与“整体”构成反义，指整体之中的局部。"}, {"text": "成员", "is_correct": false, "explanation": "语义：“成员”指组织中的个人，与“整体”不构成反义关系。"}, {"text": "环境", "is_correct": false, "explanation": "语义：“环境”指周围的情况，与“整体”不构成反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：“节奏”指有规律的变化，与“整体”不构成反义关系。"}], "correct_answer": "部分", "explanations": {"部分": "正确。“部分”与“整体”构成反义，指整体之中的局部。", "成员": "语义：“成员”指组织中的个人，与“整体”不构成反义关系。", "环境": "语义：“环境”指周围的情况，与“整体”不构成反义关系。", "节奏": "语义：“节奏”指有规律的变化，与“整体”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "部分", "is_correct": true, "explanation": "正确。“部分”与“整体”构成反义，指整体之中的局部。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是房屋的构件，与“整体”不构成反义关系。"}, {"text": "乐章", "is_correct": false, "explanation": "语义：“乐章”指乐曲的段落，与“整体”不构成反义关系。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的时段，与“整体”不构成反义关系。"}], "correct_answer": "部分", "explanations": {"部分": "正确。“部分”与“整体”构成反义，指整体之中的局部。", "窗户": "语义：“窗户”是房屋的构件，与“整体”不构成反义关系。", "乐章": "语义：“乐章”指乐曲的段落，与“整体”不构成反义关系。", "季节": "语义：“季节”指一年中的时段，与“整体”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体是所有的部分合在一起。", "primary_collocate": null, "pronunciation": "zhěng tǐ", "ipa": "ʈʂɤŋ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "手和脚都是身体的一部分,身体是一个整体。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都是班级这个整体的一部分。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个整体由三个部分组成。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师把机器看作一个统一的整体来设计。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子只是树的一部分,不是整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套家具是一个整体,不能分开卖。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河和大山合在一起,成了一个美丽的整体。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个零件都重要,因为机器是一个整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个人配合得好,像一个整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一幅画是一个整体，不能只看一个小地方。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整体性", "label": "复合"}, {"form": "整体上", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体:各个部分合在一起形成的一个统一的东西,与部分相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3120a4a-a156-4081-aede-d5f843da90e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。“整体”指身体是各部分合成的统一体，与“一部分”相对应。"}, {"text": "集体", "is_correct": false, "explanation": "语义：“集体”指由人组成的群体，身体不是人群，句意不合。"}, {"text": "全体", "is_correct": false, "explanation": "搭配：“全体”指人员的全部，不能说“身体是一个全体”。"}, {"text": "单位", "is_correct": false, "explanation": "语义：“单位”指机构或计量单位，身体不是这种组织，句意不合。"}], "explanations": {"整体": "正确。“整体”指身体是各部分合成的统一体，与“一部分”相对应。", "集体": "语义：“集体”指由人组成的群体，身体不是人群，句意不合。", "全体": "搭配：“全体”指人员的全部，不能说“身体是一个全体”。", "单位": "语义：“单位”指机构或计量单位，身体不是这种组织，句意不合。"}, "sentence_index": 0, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "整体同学都参加了比赛，场面很热闹。", "explanation": "这里应用“全体”。“整体”指各部分合成的统一体，指人群的全部要用“全体”。"}, {"text": "这套家具是一块整体，不能分开卖。", "explanation": "量词错误：“整体”作为统一体的名词，前面应用“个”或“套”，“块”不能用来计量“整体”。"}, {"text": "整体城市都很安静，夜里听不到声音。", "explanation": "这里应用“整个”。“整体”指统一体，不能直接修饰“城市”这类具体的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。河与山合在一起，成为一个统一的整体，与句意相合。"}, {"text": "总和", "is_correct": false, "explanation": "语义：“总和”指数量相加的结果，不能描述河与山合成的景象。"}, {"text": "单位", "is_correct": false, "explanation": "语义：“单位”指机构或计量单位，与自然景物的描写不合。"}, {"text": "同盟", "is_correct": false, "explanation": "搭配：“同盟”指政治或军事上的联合，不用于描写自然景物。"}], "explanations": {"整体": "正确。河与山合在一起，成为一个统一的整体，与句意相合。", "总和": "语义：“总和”指数量相加的结果，不能描述河与山合成的景象。", "单位": "语义：“单位”指机构或计量单位，与自然景物的描写不合。", "同盟": "搭配：“同盟”指政治或军事上的联合，不用于描写自然景物。"}, "sentence_index": 6, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "整体学生都已经到齐了，我们可以出发了。", "explanation": "这里应用“全体”。“整体”是统一的事物，不能直接修饰人群。"}, {"text": "这些菜的整体很多，我们吃不完。", "explanation": "这里误把统一体的“整体”当成计数的数量词来用，应说“很多”或“全部”。"}, {"text": "这幅画是一块整体。", "explanation": "量词错误：“整体”前应用“个”，“块”不能用来计量“整体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台设备是一个的整体，不能拆开用。", "corrected_sentence": "这台设备是一个整体，不能拆开用。", "error_description": "数量短语“一个”与名词“整体”之间不能加“的”，应直接说“一个整体”。“一个的整体”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这组画是一只整体，要挂在一起。", "corrected_sentence": "这组画是一个整体，要挂在一起。", "error_description": "“整体”前的量词应用“个”。“只”一般用于动物、鞋袜等，不能用来修饰“整体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
