INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下一次；紧接着的另一次。", "primary_collocate": null, "pronunciation": "xià cì", "ipa": "ɕja˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这次我先走，下次你先走。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太晚了，我们下次再聊吧。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次考试我一定会认真复习。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次没赶上火车，下次要早点出门。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次开会的时间还没有定下来。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我这次忘了带伞，下次一定会带。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你上次请客，下次轮到我请你。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说下次来的时候会带着孩子。", "target_word": "下次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很好吃，下次我还想来。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次只买了一本书，下次多买几本。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "紧接当前这一次之后的另一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
