INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89461, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着某个办法或别人说的话去做。", "primary_collocate": null, "pronunciation": "yī zhào", "ipa": "i˥ ʈʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请依照老师说的做。", "target_word": "依照", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他依照医生的话吃药。", "target_word": "依照", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以依照说明书安装。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们依照原来的办法做吧。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她依照妈妈教的方法做了蛋糕。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人依照图纸盖了这座房子。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子依照老师的要求写完了作业。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你依照这个步骤做，就不会错。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他依照朋友说的去找工作。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "依照爸爸的话，他把房间收拾好了。", "target_word": "依照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依照着", "label": "体标"}], "register": "书面", "sense_fingerprint": "依照：照着别人的话、办法或图纸去做，后接具体动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依照", "is_correct": true, "explanation": "“依照”表示照着别人的话去做，“请……老师说的做”语义通顺。"}, {"text": "违反", "is_correct": false, "explanation": "语义：“违反”表示不遵守，与“请……老师说的做”的语境相反，句意不通。"}, {"text": "无视", "is_correct": false, "explanation": "语义：“无视”表示不把某事放在眼里，与“请……老师说的做”的要求矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避”的对象多是人或危险，不能与“老师说的做”这样的指令搭配。"}], "explanations": {"依照": "“依照”表示照着别人的话去做，“请……老师说的做”语义通顺。", "违反": "语义：“违反”表示不遵守，与“请……老师说的做”的语境相反，句意不通。", "无视": "语义：“无视”表示不把某事放在眼里，与“请……老师说的做”的要求矛盾。", "躲避": "搭配：“躲避”的对象多是人或危险，不能与“老师说的做”这样的指令搭配。"}, "sentence_index": 0, "correct_answer": "依照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该依照大家的力量。", "explanation": "这里应该用〈依靠〉。依照表示照着办法或别人的话去做，不能表示靠某种力量。"}, {"text": "这些花依照墙根摆成了一排，很好看。", "explanation": "这里应该用〈沿着〉。依照表示遵照办法或根据，不能表示沿着墙根的位置。"}, {"text": "他依照镜子整理了头发。", "explanation": "这里应该用〈对着〉。依照只用于办法、规定或别人的话，不能指照着镜子这样的具体物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依照", "is_correct": true, "explanation": "“依照”表示照着别人的要求去做，“孩子……老师的要求写完了作业”语义通顺。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与顺从老师要求的行为不符，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“写完了作业”的结果相矛盾，句意不通。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“写完了作业”的结果相矛盾。"}], "explanations": {"依照": "“依照”表示照着别人的要求去做，“孩子……老师的要求写完了作业”语义通顺。", "嘲笑": "语义：“嘲笑”与顺从老师要求的行为不符，句意不通。", "拒绝": "语义：“拒绝”与“写完了作业”的结果相矛盾，句意不通。", "逃避": "语义：“逃避”与“写完了作业”的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "依照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子依照他爸爸，长得很像。", "explanation": "这里应该用〈像〉。依照表示遵照办法或根据，不能表示相貌相似。"}, {"text": "他依照一只小狗，走进了教室。", "explanation": "这里应该用〈跟着〉。依照引出的是办法、规定或别人的话，不能接动物表示跟随。"}, {"text": "他依照生日，跑去买了一个蛋糕。", "explanation": "这里应该用〈为了〉。依照表示遵照的根据，不能指行动的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划被依照老师的要求改了。", "corrected_sentence": "这个计划依照老师的要求改了。", "error_description": "错误形式“被依照”；正确形式“依照”。“依照”是动词，表示照着别人的要求去做，不能放在“被”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他依照老师的方法着练习。", "corrected_sentence": "他依照老师的方法练习。", "error_description": "错误形式“依照老师的方法着练习”；正确形式“依照老师的方法练习”。“着”是表示持续的体标，不能插在宾语“方法”和动词“练习”之间，多余的“着”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
