INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89462, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "按照；以某事物为根据。", "primary_collocate": null, "pronunciation": "yī zhào", "ipa": "i˥ ʈʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "依照规定，这里不能停车。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "依照法律，每个人都要交税。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校依照成绩分班。", "target_word": "依照", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "依照公司的规定，周末要休息。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "依照合同，他得在月底付钱。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛依照时间表进行。", "target_word": "依照", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "依照天气预报，明天会下雨。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "依照调查结果，新政策将在明年开始实施。", "target_word": "依照", "complexity_tier": "T3", "furigana": "yī zhào diào chá jié guǒ, xīn zhèng cè jiāng zài míng nián kāi shǐ shí shī.", "sentence_source": "generated"}, {"text": "依照要求，我们把表格交上去了。", "target_word": "依照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板依照经验选了这批货。", "target_word": "依照", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "依照：介词，引出做事的根据，如规定、法律、合同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb3c2ad-6ea0-4776-af68-8b3eb92505cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依照", "is_correct": true, "explanation": "“依照”是介词，引出做事的根据，“……规定，这里不能停车”语义通顺。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，与“规定”组合后句意不通。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，与“规定，这里不能停车”的根据关系不符，句意不通。"}, {"text": "对着", "is_correct": false, "explanation": "搭配：“对着”表示面向某物，不能引出规定作为根据。"}], "explanations": {"依照": "“依照”是介词，引出做事的根据，“……规定，这里不能停车”语义通顺。", "替": "语义：“替”表示代替，与“规定”组合后句意不通。", "为了": "语义：“为了”表示目的，与“规定，这里不能停车”的根据关系不符，句意不通。", "对着": "搭配：“对着”表示面向某物，不能引出规定作为根据。"}, "sentence_index": 0, "correct_answer": "依照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "依照很冷，我们只好待在家里。", "explanation": "这里应该用〈因为〉。依照引出的是规定、办法等根据，不能接“很冷”这样的状态来表示原因。"}, {"text": "依照一只猫，他走出了教室。", "explanation": "这里应该用〈跟着〉。依照引出的是规定、办法或别人的话，不能接动物表示跟随。"}, {"text": "依照一个小时，他终于把作业写完了。", "explanation": "这里应该用〈用了〉。依照引出根据，不能用来表示花费的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依照", "is_correct": true, "explanation": "“依照”是介词，引出根据，“……天气预报，明天会下雨”语义通顺。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向，天气预报不是方向，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "语义：“朝”表示朝向某处，与天气预报无关，句意不通。"}, {"text": "往", "is_correct": false, "explanation": "搭配：“往”多与地点或路线搭配，不能引出天气预报。"}], "explanations": {"依照": "“依照”是介词，引出根据，“……天气预报，明天会下雨”语义通顺。", "向": "语义：“向”表示方向，天气预报不是方向，句意不通。", "朝": "语义：“朝”表示朝向某处，与天气预报无关，句意不通。", "往": "搭配：“往”多与地点或路线搭配，不能引出天气预报。"}, "sentence_index": 6, "correct_answer": "依照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "依照河边走，就能找到公园。", "explanation": "这里应该用〈顺着〉。依照表示遵照办法或以根据为准，不能表示沿着某条路线走。"}, {"text": "依照他的朋友，我们一起吃了晚饭。", "explanation": "这里应该用〈和〉。依照不能引出一起行动的对象。"}, {"text": "依照这里，我找到了钥匙。", "explanation": "这里应该用〈在〉。依照不能引出地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里被依照学校的规定不能吸烟。", "corrected_sentence": "这里依照学校的规定不能吸烟。", "error_description": "错误形式“被依照”；正确形式“依照”。介词“依照”前面不能加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生依照的校规，不能在这里停车。", "corrected_sentence": "学生依照校规，不能在这里停车。", "error_description": "错误形式“依照的校规”；正确形式“依照校规”。“依照”是介词，后面直接接名词作宾语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c10624-d044-46ff-8300-5a4002ed5a7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
