INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医院、机关等单位按业务性质划分出的科室。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "孩子发烧了，应该挂哪个科的号？", "target_word": "科", "complexity_tier": "T3", "furigana": "hái zi fā shāo le, yīng gāi guà nǎ ge kē de hào?", "sentence_source": "generated"}, {"text": "这家医院有十几个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院的哪个科工作？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你的病要去另一个科看。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所医院分很多科，看病前要先弄清楚该看哪个科。", "target_word": "科", "complexity_tier": "T3", "furigana": "zhè suǒ yī yuàn fēn hěn duō kē, kàn bìng qián yào xiān nòng qīng chu gāi kàn nǎ ge kē.", "sentence_source": "generated"}, {"text": "护士问我要看哪个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学分了很多科，每一科都有自己的图书室。", "target_word": "科", "complexity_tier": "T3", "furigana": "zhè suǒ dà xué fēn le hěn duō kē, měi yì kē dōu yǒu zì jǐ de tú shū shì.", "sentence_source": "generated"}, {"text": "这家医院的哪一科最有名？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个科都有一位负责人。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚从那个科调到这个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科室", "label": "复合"}, {"form": "科学", "label": "复合"}], "register": "中性", "sense_fingerprint": "医院、单位等按业务分出的科室类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指医院、单位等按业务分出的科室。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。"}, {"text": "壳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是壳。"}, {"text": "刻", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是刻。"}, {"text": "克", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}], "explanations": {"科": "正确：本词，指医院、单位等按业务分出的科室。", "渴": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。", "壳": "ké（第二声）与 kē（第一声）声调不同，意思是壳。", "刻": "kè（第四声）与 kē（第一声）声调不同，意思是刻。", "克": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指医院里按业务分出的科室，“挂……的号”说的就是挂哪个科。"}, {"text": "班", "is_correct": false, "explanation": "语义：“班”指学生的班级，与医院挂号的科室不符。"}, {"text": "系", "is_correct": false, "explanation": "语义：“系”是大学里的院系，医院挂号不用“系”。"}, {"text": "部", "is_correct": false, "explanation": "搭配：医院挂号一般说“挂哪个科的号”，不说“挂哪个部的号”。"}], "explanations": {"科": "正确：指医院里按业务分出的科室，“挂……的号”说的就是挂哪个科。", "班": "语义：“班”指学生的班级，与医院挂号的科室不符。", "系": "语义：“系”是大学里的院系，医院挂号不用“系”。", "部": "搭配：医院挂号一般说“挂哪个科的号”，不说“挂哪个部的号”。"}, "sentence_index": 0, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋科很高，有十几层。", "explanation": "这里应该用〈楼〉。“科”指科室，是机构，不是建筑物，应说“楼”。"}, {"text": "我把这个科装进书包，带回了家。", "explanation": "这里应该用〈课本〉。“科”指科室，是机构，不能装进书包，应说“课本”。"}, {"text": "他在医院里当了十年的科，每天给病人看病。", "explanation": "这里应该用〈医生〉。“科”指科室，是机构，不能说“当科”，当医生才是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指医院、单位等按业务分出的科室。"}, {"text": "课", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是课程。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是可以。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}], "explanations": {"科": "正确：本词，指医院、单位等按业务分出的科室。", "课": "kè（第四声）与 kē（第一声）声调不同，意思是课程。", "可": "kě（第三声）与 kē（第一声）声调不同，意思是可以。", "咳": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。", "客": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指学校里的一类，“分了很多科”指分出许多院系、科目一类的单位。"}, {"text": "楼", "is_correct": false, "explanation": "搭配：“分”出的多是院系、部门，不说“分了很多楼”。"}, {"text": "层", "is_correct": false, "explanation": "语义：“层”指楼层，与“分”出学术单位的意思不符。"}, {"text": "室", "is_correct": false, "explanation": "语义：“室”指房间，与前后“每一……都有自己的图书室”的意思不通。"}], "explanations": {"科": "正确：指学校里的一类，“分了很多科”指分出许多院系、科目一类的单位。", "楼": "搭配：“分”出的多是院系、部门，不说“分了很多楼”。", "层": "语义：“层”指楼层，与“分”出学术单位的意思不符。", "室": "语义：“室”指房间，与前后“每一……都有自己的图书室”的意思不通。"}, "sentence_index": 6, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午还要上一节科，老师讲得很快。", "explanation": "这里应该用〈课〉。“上一节”指上课，科室不能用来说上课。"}, {"text": "他每天早上都去超市买科，回家做饭。", "explanation": "这里应该用〈菜〉。“科”指科室或学科类别，不能去超市买，应说“买菜”。"}, {"text": "这家医院新开了一科，专门给病人卖冰淇淋。", "explanation": "这里应该用〈小卖部〉。“科”指科室，是医疗或行政部门，卖东西的地方应说小卖部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院有三只科。", "corrected_sentence": "这家医院有三个科。", "error_description": "量词错误：“科”是科室，应用量词“个”，不能用“只”（“只”不用于科室）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司各科们都有一位负责人。", "corrected_sentence": "公司各科都有一位负责人。", "error_description": "多加“们”：“各科”本身已表示全部，后面不能再加“们”，应说“各科都有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "等等是说后面还有,这里不再说了。", "primary_collocate": null, "pronunciation": "děng děng", "ipa": "tɤŋ˨˩ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "桌上有苹果、香蕉、西瓜等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会说中文、英文、日文等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖米、面、肉、鱼等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爱运动，比如跑步、游泳、打球等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有花、树、小鸟等等。", "target_word": "等等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的包里有书、手机、钥匙等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教了我们问路、买东西、点菜等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京、上海、广州等等都是大城市。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天可以去爬山、放风筝、看花等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天要做饭、洗衣服、打扫房间等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "列举末尾，表示同类的还有，不再一一说出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示同类的还有，不再一一说出，与“苹果、香蕉、西瓜”的列举相合。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示仅此而已，把列举说成到此为止，与“还有同类”的意思相反。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与现代汉语日常陈述的语域不合。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成或变化，这里是静态的存在陈述，不合。"}], "explanations": {"等等": "“等等”放在列举末尾，表示同类的还有，不再一一说出，与“苹果、香蕉、西瓜”的列举相合。", "而已": "语义：“而已”表示仅此而已，把列举说成到此为止，与“还有同类”的意思相反。", "矣": "语域：“矣”是文言语气词，与现代汉语日常陈述的语域不合。", "了": "体貌：“了”表示完成或变化，这里是静态的存在陈述，不合。"}, "sentence_index": 0, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一共只有三个人：小明、小红、小刚等等。", "explanation": "“一共只有三个人”已经说明列全，却又用〈等等〉表示后面还有同类，把封闭的一组说成未完；应去掉〈等等〉。"}, {"text": "我爸爸只有一个哥哥，叫王伟等等。", "explanation": "〈等等〉接在“只有一个哥哥”后面，表示还有同类，但这里只有一个人，没有可以并列的几项；这是把〈等等〉当成随口说“还有别的”。"}, {"text": "我今天只买了一个苹果等等。", "explanation": "〈等等〉表示列举后还有同类，前面至少需要两项并列；只有一个苹果时不能用〈等等〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示“问路、买东西、点菜”之外还有同类的内容，不再一一说出。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：“罢了”表示只是如此，与列举还未结束的意思不合。"}, {"text": "啦", "is_correct": false, "explanation": "语域：“啦”口语色彩很重，与这句中性的陈述不合。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”多用于追问或延续话题，这里是陈述，不合。"}], "explanations": {"等等": "“等等”放在列举末尾，表示“问路、买东西、点菜”之外还有同类的内容，不再一一说出。", "罢了": "语义：“罢了”表示只是如此，与列举还未结束的意思不合。", "啦": "语域：“啦”口语色彩很重，与这句中性的陈述不合。", "呢": "语义：“呢”多用于追问或延续话题，这里是陈述，不合。"}, "sentence_index": 6, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年有春、夏、秋、冬等等。", "explanation": "季节只有四个，已经列全，是封闭的一组，不能再用〈等等〉表示还有别的。"}, {"text": "东、南、西、北等等都是方向。", "explanation": "方向只有四个，是封闭的一组，已经列全，这里不应使用〈等等〉。"}, {"text": "一只手有五根手指等等。", "explanation": "手指数量固定，列举已经完整，〈等等〉在这里表示还有别的是不成立的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去超市买了苹果、香蕉、牛奶、等等。", "corrected_sentence": "我们去超市买了苹果、香蕉、牛奶等等。", "error_description": "错误在于〈等等〉前多加了顿号，写成“牛奶、等等”，把它当成了一个并列项。正确的写法是〈等等〉直接接在最后一项后面：“牛奶等等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有图书馆、食堂、操场等等等等。", "corrected_sentence": "我们学校有图书馆、食堂、操场等等。", "error_description": "错误在于〈等等〉重复成“等等等等”。正确的写法是只用一次〈等等〉：“操场等等”，表示列举后还有同类。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
