INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词,表示列举未完。", "primary_collocate": null, "pronunciation": "děng děng", "ipa": "tɤŋ˨˩ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "这家店卖鞋、帽子、衣服等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国菜有饺子、面条、米饭等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里有冰箱、电视、洗衣机等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会打篮球、踢足球、打乒乓球等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天买了牛奶、鸡蛋、面包等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物园里有老虎、大象、熊猫等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里有小说、词典、杂志等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的活动有唱歌、跳舞、比赛等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过法国、德国、意大利等等。", "target_word": "等等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我想看电影、逛街、睡觉等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在几个并列项目之后，表示列举没有结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示“鞋、帽子、衣服”之外还有同类的商品，不再一一说出。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：“罢了”表示只此而已，与列举未完的意思不合。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与现代汉语日常叙述的语域不合。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成或变化，这里是对店里商品的静态陈述，不合。"}], "explanations": {"等等": "“等等”放在列举末尾，表示“鞋、帽子、衣服”之外还有同类的商品，不再一一说出。", "罢了": "语义：“罢了”表示只此而已，与列举未完的意思不合。", "矣": "语域：“矣”是文言语气词，与现代汉语日常叙述的语域不合。", "了": "体貌：“了”表示完成或变化，这里是对店里商品的静态陈述，不合。"}, "sentence_index": 0, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们家唯一的孩子等等。", "explanation": "〈等等〉表示列举未完，前面要有并列的几项；“唯一的孩子”只有一个，却用〈等等〉表示还有同类，与〈等等〉的用法不符。"}, {"text": "我们家的小狗叫旺财等等。", "explanation": "〈等等〉要接在并列的几项之后；这里只说了一只狗的名字，却加〈等等〉表示还有同类，这是误用。"}, {"text": "我今天只吃了一个鸡蛋等等。", "explanation": "〈等等〉要求前面是并列的几项，只有一个鸡蛋时不能用〈等等〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示“小说、词典、杂志”之外还有同类的书，不再一一说出。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示仅此而已，与列举未完的意思不合。"}, {"text": "啦", "is_correct": false, "explanation": "语域：“啦”口语色彩很重，与这句中性的陈述不合。"}, {"text": "来着", "is_correct": false, "explanation": "体貌：“来着”表示回想先前的情况，这里是当下的陈述，不合。"}], "explanations": {"等等": "“等等”放在列举末尾，表示“小说、词典、杂志”之外还有同类的书，不再一一说出。", "而已": "语义：“而已”表示仅此而已，与列举未完的意思不合。", "啦": "语域：“啦”口语色彩很重，与这句中性的陈述不合。", "来着": "体貌：“来着”表示回想先前的情况，这里是当下的陈述，不合。"}, "sentence_index": 6, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一周有周一、周二、周三、周四、周五、周六、周日等等。", "explanation": "一周的天数是固定的，已经列全，不能再用〈等等〉表示还有别的。"}, {"text": "一个人有两只手、两只脚等等。", "explanation": "人的手脚数量固定，列举已经完整，这里用〈等等〉是多余的。"}, {"text": "中国有四个直辖市：北京、上海、天津、重庆等等。", "explanation": "直辖市只有四个，已经全部列出，是封闭的一组；〈等等〉表示还有别的，在这里不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市卖牛奶、鸡蛋、面包、等等。", "corrected_sentence": "这家超市卖牛奶、鸡蛋、面包等等。", "error_description": "错误在于〈等等〉前多了顿号，写成“面包、等等”。正确的写法是〈等等〉直接接在最后一项“面包”后面，中间不加标点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢看书、听歌、画画等等等等。", "corrected_sentence": "我喜欢看书、听歌、画画等等。", "error_description": "错误在于〈等等〉重复成“等等等等”。正确的写法是只用一次〈等等〉，表示后面还有同类的爱好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
