INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妻子(口语)。", "primary_collocate": null, "pronunciation": "lǎo pó", "ipa": "lɑʊ˨˩˦ pʰwo˧˥", "syllable_count": 2, "sentences": [{"text": "他的老婆是医生。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生带着老婆去旅行了。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友娶了一个好老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱他的老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的老婆在银行工作。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天送老婆上班。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥的老婆是我同学。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工资都给了老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想早点找个老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的老婆比他小两岁。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "口语中指妻子，如“他的老婆是医生”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3120a4a-a156-4081-aede-d5f843da90e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老婆", "is_correct": true, "explanation": "“老婆”指妻子，放在“他的___是医生”中，说的是他的妻子职业。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”是动物，不能是医生，句子语境不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”是物品，不能与“是医生”构成人的身份说明。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不能是医生，与“是医生”搭配不成立。"}], "explanations": {"老婆": "“老婆”指妻子，放在“他的___是医生”中，说的是他的妻子职业。", "小狗": "语义：“小狗”是动物，不能是医生，句子语境不通。", "椅子": "搭配：“椅子”是物品，不能与“是医生”构成人的身份说明。", "汽车": "语义：“汽车”不能是医生，与“是医生”搭配不成立。"}, "sentence_index": 0, "correct_answer": "老婆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子对母亲说：“老婆，我饿了。”", "explanation": "这里应该用〈妈妈〉。“老婆”是丈夫称妻子的话，孩子不能用它称呼母亲。"}, {"text": "他对陌生人说：“老婆，请问厕所在哪儿？”", "explanation": "这里应该用〈先生〉。“老婆”只指妻子，不能用来称呼不认识的人。"}, {"text": "同事对我说：“老婆，你的文件呢？”", "explanation": "这里应该用〈小王〉。“老婆”只指妻子，不能用来称呼同事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老婆", "is_correct": true, "explanation": "“老婆”指妻子，放在“我哥哥的___是我同学”中，说的是哥哥的妻子。"}, {"text": "女士", "is_correct": false, "explanation": "语域：“女士”是礼貌称呼，不能用来指哥哥的妻子这种家庭关系。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”是搭乘交通工具的人，与“我哥哥的……是我同学”的语境不符。"}, {"text": "售货员", "is_correct": false, "explanation": "语义：“售货员”是职业身份，不能是哥哥的家人，也不能与“同学”的身份对应。"}], "explanations": {"老婆": "“老婆”指妻子，放在“我哥哥的___是我同学”中，说的是哥哥的妻子。", "女士": "语域：“女士”是礼貌称呼，不能用来指哥哥的妻子这种家庭关系。", "乘客": "语义：“乘客”是搭乘交通工具的人，与“我哥哥的……是我同学”的语境不符。", "售货员": "语义：“售货员”是职业身份，不能是哥哥的家人，也不能与“同学”的身份对应。"}, "sentence_index": 6, "correct_answer": "老婆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈对儿子说：“老婆，你今天回家吃饭吗？”", "explanation": "这里应该用〈宝贝〉。“老婆”是丈夫称妻子的话，母亲不能拿它称呼儿子。"}, {"text": "服务员对客人说：“老婆，您的饭好了。”", "explanation": "这里应该用〈女士〉。“老婆”只指丈夫的妻子，不能用来称呼客人。"}, {"text": "教练对队员说：“老婆，再跑一圈。”", "explanation": "这里应该用〈小伙子〉。“老婆”只指妻子，不能用来称呼男队员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的老婆的在银行工作。", "corrected_sentence": "他的老婆在银行工作。", "error_description": "错误：“他的老婆的在银行工作”，“老婆”后面多加了一个“的”。正确：“他的老婆在银行工作”，“的”只用在领属词“他”后面，“老婆”后不再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一只好老婆。", "corrected_sentence": "他找到了一个好老婆。", "error_description": "错误：“一只好老婆”；正确：“一个好老婆”。“只”用于动物，指人应当用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
