INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警方是警察那一边的人。", "primary_collocate": null, "pronunciation": "jǐng fāng", "ipa": "tɕiŋ˨˩˦ fɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "警方到了现场。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方正在找那个小偷。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方说,昨晚没有人受伤。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙交给了警方。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方请大家不要在这里停车。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子丢了以后，妈妈立刻向警方报告。", "target_word": "警方", "complexity_tier": "T3", "furigana": "hái zi diū le yǐ hòu, mā ma lì kè xiàng jǐng fāng bào gào.", "sentence_source": "generated"}, {"text": "警方问了他很多问题。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方在路口等着那辆红色的车。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方已经找到了丢失的钱包。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人告诉警方,他昨天看见过那个人。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "警察一方的人，如“警方到了现场”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3120a4a-a156-4081-aede-d5f843da90e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警方", "is_correct": true, "explanation": "正确。警方指警察一方，可以作主语到达现场。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：「到了现场」的主语应是能行动的人或团体，厨房是处所，不能到现场。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不是警察一方，不能到现场。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然现象，不是人或团体，不能到现场。"}], "explanations": {"警方": "正确。警方指警察一方，可以作主语到达现场。", "厨房": "搭配：「到了现场」的主语应是能行动的人或团体，厨房是处所，不能到现场。", "学校": "语义：学校是教育机构，不是警察一方，不能到现场。", "天空": "语义：天空是自然现象，不是人或团体，不能到现场。"}, "sentence_index": 0, "correct_answer": "警方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的表哥是一位警方。", "explanation": "这里应该用〈警察〉。警方指警察一方的集体，不能用个人量词〈位〉修饰。"}, {"text": "他是警方，每天都要巡逻。", "explanation": "这里应该用〈民警〉。警方指警察一方的集体，不能直接用来指一个人。"}, {"text": "我喜欢警方这个职业。", "explanation": "这里应该用〈警察〉。警方指警察一方，不指个人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警方", "is_correct": true, "explanation": "正确。警方指警察一方，可以作主语提问。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能提问。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：「问」的主语应是能提问的人或机构，菜市场不能提问。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不能提问。"}], "explanations": {"警方": "正确。警方指警察一方，可以作主语提问。", "眼镜": "语义：眼镜是物品，不能提问。", "菜市场": "搭配：「问」的主语应是能提问的人或机构，菜市场不能提问。", "河流": "语义：河流是自然事物，不能提问。"}, "sentence_index": 6, "correct_answer": "警方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "张警方很年轻，很热心。", "explanation": "这里应该用〈警官〉。警方指警察一方，不能指一个人，称呼个人要说警官。"}, {"text": "我的邻居是警方，每天早上都去跑步。", "explanation": "这里应该用〈警员〉。警方是集体概念，不能用来指邻居这样的一个人。"}, {"text": "那位警方抓住了小偷。", "explanation": "这里应该用〈警察〉。警方指警察一方的集体，不能用〈位〉指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把包裹交给了一个警方。", "corrected_sentence": "他把包裹交给了警方。", "error_description": "「警方」是集体概念，前面不能加「一个」这类个体量词，应直接说「交给了警方」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警方的找来了那个证人。", "corrected_sentence": "警方找来了那个证人。", "error_description": "错误：「警方的找来了」，「的」插在主语与动词之间，句子不成立，应去掉「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
