INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指警察部门或警察机关。", "primary_collocate": null, "pronunciation": "jǐng fāng", "ipa": "tɕiŋ˨˩˦ fɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "市警方今天发了一个新通知。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方的网站上有一个电话号码。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事由警方负责。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方每年都会办很多安全活动。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地警方提醒大家小心电话骗子。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方发布了一条新消息。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在警方工作了二十年。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口停着一辆警车，是警方派来的。", "target_word": "警方", "complexity_tier": "T3", "furigana": "xué xiào mén kǒu tíng zhe yí liàng jǐng chē, shì jǐng fāng pài lái de.", "sentence_source": "generated"}, {"text": "警方公布了去年的数字。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有问题,可以问当地警方。", "target_word": "警方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "警察部门或机关，如“当地警方发布通知”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3120a4a-a156-4081-aede-d5f843da90e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警方", "is_correct": true, "explanation": "正确。警方指警察机关，可以发布通知。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能发布通知。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不能发布通知。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：「发通知」的主语应是机构或人，水果不能发通知。"}], "explanations": {"警方": "正确。警方指警察机关，可以发布通知。", "天气": "语义：天气是自然现象，不能发布通知。", "河流": "语义：河流是自然事物，不能发布通知。", "水果": "搭配：「发通知」的主语应是机构或人，水果不能发通知。"}, "sentence_index": 0, "correct_answer": "警方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在警方教书，给学生上课。", "explanation": "这里应该用〈学校〉。警方指警察机关，不是教书上课的地方。"}, {"text": "他明天要去警方做手术。", "explanation": "这里应该用〈医院〉。警方指警察机关，不是医疗机构，不能做手术。"}, {"text": "一名警方在办公室里工作。", "explanation": "这里应该用〈警察〉。警方指机构，不能用个人量词〈名〉修饰；指一个人要说〈警察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警方", "is_correct": true, "explanation": "正确。警方指警察机关，可以作工作单位。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是工作单位。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能作工作单位。"}, {"text": "父亲", "is_correct": false, "explanation": "搭配：「在…工作」的地点应是单位或场所，不能是人。"}], "explanations": {"警方": "正确。警方指警察机关，可以作工作单位。", "天空": "语义：天空不是工作单位。", "眼镜": "语义：眼镜是物品，不能作工作单位。", "父亲": "搭配：「在…工作」的地点应是单位或场所，不能是人。"}, "sentence_index": 6, "correct_answer": "警方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在当地警方买了一本词典。", "explanation": "这里应该用〈书店〉。警方指警察机关，不是卖书的地方。"}, {"text": "我周末去当地警方取钱。", "explanation": "这里应该用〈银行〉。警方指警察机关，不是存取钱的地方。"}, {"text": "我周末和朋友去当地警方看电影。", "explanation": "这里应该用〈电影院〉。警方指警察机关，不是放映电影的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e570c94d-cde9-4c5f-a852-efc7f827fb76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
