INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开自己的国家。", "primary_collocate": null, "pronunciation": "qù guó", "ipa": "tɕʰy˥˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他年轻时去国，很少回家。", "target_word": "去国", "complexity_tier": "T3", "furigana": "tā niánqīng shí qù guó hěn shǎo huí jiā", "sentence_source": "generated"}, {"text": "为了学习，他决定去国几年。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位诗人去国多年，一直想念家乡。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去国那天，亲人都来送他。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国以后，她每年春节都很想家。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，他当年去国时才二十岁。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争开始后，许多人不得不去国。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去国三十年，没有忘记母语。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国的人，常常会梦见故乡。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她去国时，只带了一个小箱子。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "去国怀乡", "label": "复合"}], "register": "书面", "sense_fingerprint": "离开自己所在的祖国，到外国去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：退休通常在年老之后，与句中的“年轻时”矛盾。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国到外国，与“很少回家”的语境相符。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世之后不能“很少回家”，与句子的前提不合。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能作人的行为，与“年轻时”的句式不合。"}], "explanations": {"退休": "语义：退休通常在年老之后，与句中的“年轻时”矛盾。", "去国": "去国：离开本国到外国，与“很少回家”的语境相符。", "去世": "语义：去世之后不能“很少回家”，与句子的前提不合。", "装修": "搭配：“装修”的对象是房屋，不能作人的行为，与“年轻时”的句式不合。"}, "sentence_index": 0, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都去国吃早饭。", "explanation": "这里应该用〈在家〉。去国指离开本国，不能用来说在家里吃饭。"}, {"text": "他每天早上去国跑步。", "explanation": "这里应该用〈晨练〉。去国指离开本国，不能用来说在本地早上锻炼身体。"}, {"text": "他周末都去国看书。", "explanation": "这里应该用〈去图书馆〉。去国指离开本国，不能用来说周末在国内去某处看书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：战争中的“不得不”是被迫离开，“唱歌”与此矛盾。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国，与“战争开始后被迫”的语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与战争中被迫的情境不合，句意说不通。"}, {"text": "观光", "is_correct": false, "explanation": "搭配：“不得不”后接被迫的行为，“观光”不能表示被迫。"}], "explanations": {"唱歌": "语义：战争中的“不得不”是被迫离开，“唱歌”与此矛盾。", "去国": "去国：离开本国，与“战争开始后被迫”的语境相符。", "游泳": "语义：“游泳”与战争中被迫的情境不合，句意说不通。", "观光": "搭配：“不得不”后接被迫的行为，“观光”不能表示被迫。"}, "sentence_index": 6, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父母去年去国到上海。", "explanation": "这里应该用〈迁居〉。去国是离开本国，不能用来说在国内搬到另一个城市。"}, {"text": "他一早就去国买菜。", "explanation": "这里应该用〈出门〉。去国指离开本国，不能用来说早上外出办事。"}, {"text": "他每天去国挑水。", "explanation": "这里应该用〈去井边〉。去国指离开本国，不能用来说在本地去井边打水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他三十岁时被去国，就再也没回来。", "corrected_sentence": "他三十岁时去国，就再也没回来。", "error_description": "被字句错误：“去国”是不及物动词，不能用“被”字句，应去掉“被”，写作“他三十岁时去国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很去国十年，没有回家。", "corrected_sentence": "他去国十年，没有回家。", "error_description": "副词错误：程度副词“很”不能修饰动作动词“去国”，应去掉“很”，写作“他去国十年，没有回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
