INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（书面）离开本国。", "primary_collocate": null, "pronunciation": "qù guó", "ipa": "tɕʰy˥˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "诗人去国之后，写下了很多思乡的诗。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自幼去国，晚年才回到故土。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位学者去国数十年，仍然心系祖国。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三十岁那年去国，从此再没回来。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国多年的游子，终于回到了家乡。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一年他去国，什么也没带。", "target_word": "去国", "complexity_tier": "T3", "furigana": "nà yī nián tā qù guó shénme yě méi dài", "sentence_source": "generated"}, {"text": "她去国前，在故乡的老屋住了最后一夜。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战乱之年，不少读书人只好去国避难。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去国之人，最怕听到乡音。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早年去国求学，后来在海外任教。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "去国怀乡", "label": "复合"}], "register": "书面", "sense_fingerprint": "书面语：离开本国，远走他乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "团聚", "is_correct": false, "explanation": "语义：团聚之后不会写思乡的诗，与句中的“思乡”矛盾。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国，与后文“写下了很多思乡的诗”相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能作诗人的人生事件，与“之后”的句式不合。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世之后无法写诗，与句意矛盾。"}], "explanations": {"团聚": "语义：团聚之后不会写思乡的诗，与句中的“思乡”矛盾。", "去国": "去国：离开本国，与后文“写下了很多思乡的诗”相符。", "装修": "搭配：“装修”的对象是房屋，不能作诗人的人生事件，与“之后”的句式不合。", "去世": "语义：去世之后无法写诗，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都去国做饭。", "explanation": "这里应该用〈下厨〉。去国指离开本国，不能用来说在家里做饭。"}, {"text": "她每周都去国逛街。", "explanation": "这里应该用〈上街〉。去国指离开本国，不能用来说在本地外出逛街。"}, {"text": "他周末总是去国整理房间。", "explanation": "这里应该用〈在家〉。去国指离开本国，不能用来说在家里做家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：出生前不可能住在老屋，与句中的情况矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“住了最后一夜”的离别语境不合。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国，与“在故乡住了最后一夜”的离别语境相符。"}, {"text": "下棋", "is_correct": false, "explanation": "搭配：“下棋”不能用于“住在老屋最后一夜”这种时间背景。"}], "explanations": {"出生": "语义：出生前不可能住在老屋，与句中的情况矛盾。", "唱歌": "语义：“唱歌”与“住了最后一夜”的离别语境不合。", "去国": "去国：离开本国，与“在故乡住了最后一夜”的离别语境相符。", "下棋": "搭配：“下棋”不能用于“住在老屋最后一夜”这种时间背景。"}, "sentence_index": 6, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家上个月去国到郊区。", "explanation": "这里应该用〈搬家〉。去国是离开本国，不能用来说在国内搬到郊区。"}, {"text": "知青们去国插队。", "explanation": "这里应该用〈下乡〉。去国指离开本国，不能用来说到农村插队。"}, {"text": "他每天早上去国散步。", "explanation": "这里应该用〈出门〉。去国指离开本国，不能用来说早上外出散步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去国着十年，从未回乡。", "corrected_sentence": "他去国十年，从未回乡。", "error_description": "体标错误：“去国”表示一次性离开的瞬时动作，不能用“着”表示持续，“去国着十年”不成立；应去掉“着”，写作“他去国十年，从未回乡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很去国三年，再也没有回家。", "corrected_sentence": "他去国三年，再也没有回家。", "error_description": "副词错误：程度副词“很”不能修饰动作动词“去国”，应去掉“很”，写作“他去国三年，再也没有回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
