INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "财产是一个人有的钱和东西。", "primary_collocate": null, "pronunciation": "cái chǎn", "ipa": "tsʰai̯˧˥ tʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的财产很多。", "target_word": "财产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是我的财产。", "target_word": "财产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没有什么财产。", "target_word": "财产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有钱，也有很多财产。", "target_word": "财产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把财产放在银行里。", "target_word": "财产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的财产就是这个小房子。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有一些财产，但是不爱花钱。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的钱和东西都是你的财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他卖掉了一部分财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想要丈夫的财产。", "target_word": "财产", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "財產", "label": "繁体"}, {"form": "私有财产", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人拥有的钱和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财产", "is_correct": true, "explanation": "财产指一个人拥有的钱和东西，可以说“很多”。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：“很多”说数量，不说水平，水平应说“高”。"}, {"text": "能力", "is_correct": false, "explanation": "搭配：能力常说“强”，不说“很多”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是一个人拥有的东西，不能说“很多”。"}], "explanations": {"财产": "财产指一个人拥有的钱和东西，可以说“很多”。", "水平": "搭配：“很多”说数量，不说水平，水平应说“高”。", "能力": "搭配：能力常说“强”，不说“很多”。", "天气": "语义：天气不是一个人拥有的东西，不能说“很多”。"}, "sentence_index": 0, "correct_answer": "财产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天给财产浇水，财产长得很快。", "explanation": "这里不这么用。财产是钱和东西，不是植物，不会生长。"}, {"text": "他把财产喝进了肚子里。", "explanation": "这里不这么用。财产不能喝，“喝”只搭配液体。"}, {"text": "我们家有一只财产。", "explanation": "这里应该用〈笔〉。财产多用“笔”计量，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财产", "is_correct": true, "explanation": "财产指一个人有的钱和东西，可以说“有一些财产”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是一个人拥有的财物，不能说“有一些空气，但是不爱花钱”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是可以拥有的财物，不能用来说“不爱花钱”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是数值，不说“有一些身高”。"}], "explanations": {"财产": "财产指一个人有的钱和东西，可以说“有一些财产”。", "空气": "语义：空气不是一个人拥有的财物，不能说“有一些空气，但是不爱花钱”。", "温度": "语义：温度不是可以拥有的财物，不能用来说“不爱花钱”。", "身高": "搭配：身高是数值，不说“有一些身高”。"}, "sentence_index": 6, "correct_answer": "财产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的财产很鲜艳。", "explanation": "这里应该用〈颜色〉。“财产”指钱和东西，不能用来形容画面的颜色。"}, {"text": "那个小孩很会唱歌，财产的声音很好听。", "explanation": "这里应该用〈嗓音〉。“财产”指钱和东西，不是声音，不能用来形容声音好听。"}, {"text": "这张桌子的财产很长。", "explanation": "这里应该用〈尺寸〉。“财产”指钱和东西，不能用来表示物体的长短，描述大小、长短要说“尺寸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他财产。", "corrected_sentence": "这是他的财产。", "error_description": "漏掉定语标记：表示所属时要用“的”，应说“他的财产”，不能说“他财产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有很多财产们。", "corrected_sentence": "她有很多财产。", "error_description": "错误：“财产”是表示钱物的名词，不能加“们”表示复数，应说“很多财产”，不能说“财产们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
