INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "个人或集体拥有的钱财、物品、房屋等。", "primary_collocate": null, "pronunciation": "cái chǎn", "ipa": "tsʰai̯˧˥ tʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他把所有的财产都留给了孩子。", "target_word": "财产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子是我们家最大的财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人去世后，财产由儿子继承。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的财产要登记清楚。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律保护每个人的财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的财产不多，但是生活很快乐。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷偷走了他不少财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾让这家人失去了全部财产。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻两人共同的财产要平分。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生的财产都捐给了学校。", "target_word": "财产", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "個人財產", "label": "繁体"}, {"form": "私有财产", "label": "复合"}, {"form": "国有财产", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或集体拥有的钱财、物品、房屋等总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财产", "is_correct": true, "explanation": "财产指个人或集体拥有的钱财、物品、房屋等，可以留给孩子。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被留给别人。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不能被留给别人。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“留给”不搭配“温度”。"}], "explanations": {"财产": "财产指个人或集体拥有的钱财、物品、房屋等，可以留给孩子。", "天气": "语义：天气不能被留给别人。", "季节": "语义：季节不能被留给别人。", "温度": "搭配：“留给”不搭配“温度”。"}, "sentence_index": 0, "correct_answer": "财产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天浇水施肥，财产长得很好。", "explanation": "这里不这么用。“财产”指钱物，不是可以浇水施肥、会长大的植物。"}, {"text": "他对家人的财产很深。", "explanation": "这里应该用〈感情〉。“财产”指钱和物，不能用来表示感情的深浅。"}, {"text": "我家有一块财产。", "explanation": "这里应该用〈笔〉。财产作为一整份钱物，量词用“笔”，不用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财产", "is_correct": true, "explanation": "财产指个人拥有的钱物，“偷走”他的财产是常见说法。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“偷走”可搭配财物，体力不能被偷走。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人拥有的财物，不能被偷。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能被偷走。"}], "explanations": {"财产": "财产指个人拥有的钱物，“偷走”他的财产是常见说法。", "体力": "搭配：“偷走”可搭配财物，体力不能被偷走。", "空气": "语义：空气不是人拥有的财物，不能被偷。", "年龄": "语义：年龄不能被偷走。"}, "sentence_index": 6, "correct_answer": "财产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的财产很高。", "explanation": "这里应该用〈工资〉。财产指积累下来的钱物，不是每月的收入，不能用“每个月”来计算。"}, {"text": "那个学生考了第一名，财产真了不起。", "explanation": "这里不这么用。财产是钱物，不是人，不能去考试或被夸奖。"}, {"text": "这篇文章的财产很长。", "explanation": "这里应该用〈篇幅〉。“财产”指钱和物，文章的长短要说“篇幅”，不能用“财产”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲留下了一只财产。", "corrected_sentence": "父亲留下了一笔财产。", "error_description": "量词错误：“财产”一份一份计，应说“一笔财产”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把全部财产们卖掉了。", "corrected_sentence": "他把全部财产卖掉了。", "error_description": "错误：“财产”是表示钱物的名词，不能加“们”表示复数，应说“全部财产”，不能说“财产们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
