INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89497, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "说完一件事，再来说它的另一边。", "primary_collocate": null, "pronunciation": "lìng yì fāng miàn", "ipa": "liŋ˥˩ i˥˩ faŋ˥ mjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "一方面我想去旅游，另一方面我又怕花钱。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作工资高，另一方面，工作时间也很长。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一方面要上班，另一方面还要照顾孩子。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在城市很方便，另一方面，房子太贵了。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这家饭馆好吃，另一方面，价格也不便宜。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面他很聪明，另一方面他也很努力。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让生活变方便了，另一方面，也让人少说话了。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一方面高兴，另一方面又有点儿担心。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服颜色好看，另一方面，样子也很新。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面天气太热，另一方面，路上也很堵，所以我没去。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "先说一边，再转说事情的另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另一方面", "is_correct": true, "explanation": "正确：与前面的“一方面”呼应，引出同一件事的另一个方面，即“怕花钱”。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，但“怕花钱”不是“想去旅游”的结果，句意不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“又怕花钱”并非由“想去旅游”导致，不能用此词。"}, {"text": "总之", "is_correct": false, "explanation": "搭配：“总之”用于归纳前文，不与“一方面”呼应，用在两个分句之间不自然。"}], "explanations": {"另一方面": "正确：与前面的“一方面”呼应，引出同一件事的另一个方面，即“怕花钱”。", "因此": "语义：“因此”表示因果，但“怕花钱”不是“想去旅游”的结果，句意不通。", "所以": "语义：“所以”表示结果，“又怕花钱”并非由“想去旅游”导致，不能用此词。", "总之": "搭配：“总之”用于归纳前文，不与“一方面”呼应，用在两个分句之间不自然。"}, "sentence_index": 0, "correct_answer": "另一方面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天买了一本书，另一方面，我还买了一支笔。", "explanation": "这里应该用〈另外〉。另一方面用于同一件事的不同方面；两样各自独立的东西要用〈另外〉。"}, {"text": "天气很冷，另一方面，我们就不出门了。", "explanation": "这里表示因果，应该用〈所以〉。另一方面不表示因果关系。"}, {"text": "他先去超市买菜，另一方面，又去银行取了钱。", "explanation": "这里表示动作的先后顺序，应该用〈然后〉。另一方面不表示时间上的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另一方面", "is_correct": true, "explanation": "正确：引出“让人少说话”这一同一事物的另一个方面，与前面的“方便”形成对照。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示先后顺序，这里并不是先后的关系，句意不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示假设条件不成立时的结果，与“手机让生活变方便”的叙述无关。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”表示庆幸，不能接“也让人少说话了”这样的负面变化。"}], "explanations": {"另一方面": "正确：引出“让人少说话”这一同一事物的另一个方面，与前面的“方便”形成对照。", "首先": "语义：“首先”表示先后顺序，这里并不是先后的关系，句意不通。", "否则": "语义：“否则”表示假设条件不成立时的结果，与“手机让生活变方便”的叙述无关。", "幸好": "搭配：“幸好”表示庆幸，不能接“也让人少说话了”这样的负面变化。"}, "sentence_index": 6, "correct_answer": "另一方面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们讨论了周末的计划，另一方面，顺便提醒你，明天要交作业。", "explanation": "这里是转到另一件事，应该用〈另外〉。另一方面只用于同一件事的不同方面，不用于引出别的事。"}, {"text": "下雨了，另一方面，我们就取消了比赛。", "explanation": "这里表示因果，应该用〈所以〉。另一方面不表示因果关系。"}, {"text": "他一开始很害怕失败，另一方面，后来却变得很有信心。", "explanation": "这里说的是前后时间上的变化，另一方面不表示时间先后。去掉“另一方面”即可，“后来”已经表明先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他另一方面喜欢运动，另一方面也喜欢看书。", "corrected_sentence": "他一方面喜欢运动，另一方面也喜欢看书。", "error_description": "第一个“另一方面”应改为“一方面”。“一方面……另一方面……”是前后呼应的固定格式，第一个分句要用“一方面”，第二个才用“另一方面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一面喜欢唱歌，另一方面也喜欢画画。", "corrected_sentence": "她一方面喜欢唱歌，另一方面也喜欢画画。", "error_description": "“一面”应改为“一方面”。“另一方面”要与前面的“一方面”呼应，前一分句应用“一方面”，不能用“一面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
