INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来引出与前面所说相对或补充的另一个方面。", "primary_collocate": null, "pronunciation": "lìng yì fāng miàn", "ipa": "liŋ˥˩ i˥˩ faŋ˥ mjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "学外语很难，另一方面，它也很有意思。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要多玩，另一方面，也要按时睡觉。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面要努力工作，另一方面也要注意休息。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机很快，另一方面，价钱也比火车贵。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一方面夸他进步大，另一方面也提醒他别骄傲。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西很方便，另一方面，有时东西不好。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一方面喜欢大城市，另一方面又想回老家。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一方面在招人，另一方面也在减少费用。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法省钱，另一方面，也能省不少时间。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一方面写书，另一方面还在大学教课。", "target_word": "另一方面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "引出相对或补充的另一个方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另一方面", "is_correct": true, "explanation": "正确：引出“有意思”这一与前面“难”相对的另一个方面，前后形成对照。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，但“有意思”不是“很难”的结果，句意不通。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示先后顺序，这里并不是先后的关系，句意不通。"}, {"text": "总之", "is_correct": false, "explanation": "搭配：“总之”用于归纳总结，不与“一方面”呼应，且与前面的“很难”不衔接。"}], "explanations": {"另一方面": "正确：引出“有意思”这一与前面“难”相对的另一个方面，前后形成对照。", "因此": "语义：“因此”表示因果，但“有意思”不是“很难”的结果，句意不通。", "首先": "语义：“首先”表示先后顺序，这里并不是先后的关系，句意不通。", "总之": "搭配：“总之”用于归纳总结，不与“一方面”呼应，且与前面的“很难”不衔接。"}, "sentence_index": 0, "correct_answer": "另一方面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先吃了午饭，另一方面，又去图书馆看书了。", "explanation": "这里表示动作的先后，应该用〈然后〉。另一方面不表示时间上的先后。"}, {"text": "东西太多了，另一方面，我们就打了车。", "explanation": "这里表示因果，应该用〈所以〉。另一方面不表示因果关系。"}, {"text": "我们讨论了这次旅行的计划，另一方面，顺便说一下，明天要下雨。", "explanation": "这里是转到另一件事，应该用〈另外〉。另一方面只用于同一件事的不同方面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另一方面", "is_correct": true, "explanation": "正确：引出“想回老家”这一与“喜欢大城市”相对的另一个方面。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，但“喜欢大城市”不是“想回老家”的原因，句意不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示假设条件不成立时的结果，与前面的喜好并无关联。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”表示庆幸，多接有利的结果，不能接“又想回老家”这样的选择。"}], "explanations": {"另一方面": "正确：引出“想回老家”这一与“喜欢大城市”相对的另一个方面。", "所以": "语义：“所以”表示结果，但“喜欢大城市”不是“想回老家”的原因，句意不通。", "否则": "语义：“否则”表示假设条件不成立时的结果，与前面的喜好并无关联。", "幸好": "搭配：“幸好”表示庆幸，多接有利的结果，不能接“又想回老家”这样的选择。"}, "sentence_index": 6, "correct_answer": "另一方面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力学习，另一方面，他考上了大学。", "explanation": "这里表示结果，应该用〈因此〉。另一方面只引出同一件事的另一个方面，不引出结果。"}, {"text": "他刚来的时候很害羞，另一方面，后来变得很开朗。", "explanation": "这里说的是前后时间上的变化，另一方面不表示时间先后。去掉“另一方面”即可，“后来”已经表明先后。"}, {"text": "我今天去了书店，另一方面，我还去了银行。", "explanation": "这里是两件互不相关的事，应该用〈另外〉。另一方面只用于同一件事的不同方面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作另一方面很累，另一方面工资也很高。", "corrected_sentence": "这份工作一方面很累，另一方面工资也很高。", "error_description": "第一个“另一方面”应改为“一方面”。“一方面……另一方面……”是前后呼应的固定格式，第一个分句要用“一方面”，第二个才用“另一方面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先在大学教课，另一方面，后来开始写书。", "corrected_sentence": "他先在大学教课，后来开始写书。", "error_description": "“另一方面”只用于同一件事的不同方面，不表示时间上的先后。这里是先后发生的两件事，应删去“另一方面”，直接用“后来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
