INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89502, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指代某一类事物。", "primary_collocate": null, "pronunciation": "nà zhǒng", "ipa": "na˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他不是那种爱说话的人。", "target_word": "那种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最怕那种很热的天气。", "target_word": "那种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那种老房子现在越来越少了。", "target_word": "那种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢那种安静的生活。", "target_word": "那种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不是那种会骗人的人。", "target_word": "那种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那种水果在北方很贵。", "target_word": "那种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他开了一家卖那种旧书的店。", "target_word": "那种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那种手机现在没人用了。", "target_word": "那种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟爱看那种有动物的电影。", "target_word": "那种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸不爱吃那种太甜的蛋糕。", "target_word": "那种", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指代某一类事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那种", "is_correct": true, "explanation": "正确：「那种爱说话的人」指这一类人，「那种」作定语修饰「人」，句子通顺。"}, {"text": "哪种", "is_correct": false, "explanation": "语义：「哪种」表示疑问，「他不是哪种爱说话的人」不是正常的陈述句。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」是复数疑问词，不能用来对「他」作肯定或否定的陈述。"}, {"text": "那只", "is_correct": false, "explanation": "搭配：「只」多用于动物，不能用来修饰「爱说话的人」。"}], "explanations": {"那种": "正确：「那种爱说话的人」指这一类人，「那种」作定语修饰「人」，句子通顺。", "哪种": "语义：「哪种」表示疑问，「他不是哪种爱说话的人」不是正常的陈述句。", "哪些": "语义：「哪些」是复数疑问词，不能用来对「他」作肯定或否定的陈述。", "那只": "搭配：「只」多用于动物，不能用来修饰「爱说话的人」。"}, "sentence_index": 0, "correct_answer": "那种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题那种难，我做不出来。", "explanation": "这里应该用〈那么〉。「那种」指一类事物，不能表示程度；表示程度应说「那么难」。"}, {"text": "那种王老师上课很有趣，你去听吧。", "explanation": "这里应该用〈那位〉。「那种」指一类人，不能用来指称某一位特定的人，应说「那位王老师」。"}, {"text": "那种北京很大，我想去看看。", "explanation": "这里应该去掉〈那种〉，直接说「北京很大」。「那种」指一类事物，不能修饰「北京」这样的专有地名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那种", "is_correct": true, "explanation": "正确：「卖那种旧书的店」指卖这一类旧书的店，「那种」作定语修饰「旧书」，句子通顺。"}, {"text": "那位", "is_correct": false, "explanation": "搭配：「那位」只指人，不能修饰「旧书」。"}, {"text": "何种", "is_correct": false, "explanation": "语域：「何种」是书面语，且带疑问意味，与这句叙述不协调。"}, {"text": "什么", "is_correct": false, "explanation": "语义：「什么」表示疑问，「卖什么旧书的店」是问句式，不能用来指定一类书。"}], "explanations": {"那种": "正确：「卖那种旧书的店」指卖这一类旧书的店，「那种」作定语修饰「旧书」，句子通顺。", "那位": "搭配：「那位」只指人，不能修饰「旧书」。", "何种": "语域：「何种」是书面语，且带疑问意味，与这句叙述不协调。", "什么": "语义：「什么」表示疑问，「卖什么旧书的店」是问句式，不能用来指定一类书。"}, "sentence_index": 6, "correct_answer": "那种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子那种重，我提不动。", "explanation": "这里应该用〈那么〉。「那种」指一类事物，不能表示程度；表示程度应说「那么重」。"}, {"text": "那种小明在操场上踢球，你去叫他吧。", "explanation": "这里应该去掉〈那种〉，直接说「小明在操场上踢球」。「那种」指一类人，不能修饰特定的人名。"}, {"text": "那种张阿姨在门口，你去叫她吧。", "explanation": "这里应该用〈那位〉。「那种」指一类人，不能指称门口某一位特定的人，应说「那位张阿姨」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不喜欢那种个吵闹的生活。", "corrected_sentence": "她不喜欢那种吵闹的生活。", "error_description": "「那种」后面不能直接加量词「个」。「那种」是指示代词，修饰名词时不接量词，应说「那种吵闹的生活」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了三那种旧书。", "corrected_sentence": "我买了那种旧书。", "error_description": "数词「三」不能放在「那种」前面。「那种」前不加数词，应说「我买了那种旧书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
