INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89522, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "清楚明白地表现出来,容易看出。", "primary_collocate": null, "pronunciation": "xiǎn rán", "ipa": "ɕjɛn˨˩˦ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "他的脸色显然不太好。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上都是水,显然刚下过雨。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他的样子,显然很累。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事显然不是他的错。", "target_word": "显然", "complexity_tier": "T3", "furigana": "zhè jiàn shì xiǎn rán bú shì tā de cuò", "sentence_source": "generated"}, {"text": "他显然没有听懂老师的话。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里的灯亮着,显然有人在家。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的差别显然很大。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她显然很喜欢这份礼物。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上没有人,显然大家都回家了。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他显然在说谎,我不相信他。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "根据表现清楚看出情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "显然", "is_correct": true, "explanation": "「显然」表示从表现看出明显情况，与「脸色不太好」搭配，句意通顺。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：「亲自」修饰的是人的动作，不能修饰「脸色不太好」这样的状态。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：「幸好」表示庆幸，与「脸色不太好」的情况不相符，句子不通。"}, {"text": "偷偷", "is_correct": false, "explanation": "搭配：「偷偷」修饰隐秘的动作，不能修饰脸色。"}], "explanations": {"显然": "「显然」表示从表现看出明显情况，与「脸色不太好」搭配，句意通顺。", "亲自": "搭配：「亲自」修饰的是人的动作，不能修饰「脸色不太好」这样的状态。", "幸好": "语义：「幸好」表示庆幸，与「脸色不太好」的情况不相符，句子不通。", "偷偷": "搭配：「偷偷」修饰隐秘的动作，不能修饰脸色。"}, "sentence_index": 0, "correct_answer": "显然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你显然吃饭了吗？", "explanation": "这里应该用〈是不是〉。「显然」表示情况明显可见，不用于询问；询问对方是否吃饭要用「是不是」。"}, {"text": "请你显然把门关上。", "explanation": "这里应该用〈务必〉。「显然」指情况明显可见，不能用于请求或命令；要求对方一定做到时用「务必」。"}, {"text": "他没有任何表现，我却显然看出他很生气。", "explanation": "这里应该用〈自以为〉。「显然」表示证据明显可见，与「没有任何表现」矛盾；只是主观判断时应说「自以为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显然", "is_correct": true, "explanation": "「显然」表示明显看出，与「两个人的差别」「很大」搭配，句意通顺。"}, {"text": "略微", "is_correct": false, "explanation": "语义：「略微」表示程度轻，与「很大」的程度矛盾，句子不通。"}, {"text": "轻轻", "is_correct": false, "explanation": "搭配：「轻轻」修饰轻柔的动作，不能修饰「差别很大」。"}, {"text": "稍", "is_correct": false, "explanation": "语义：「稍」表示略微，与「很大」的程度相冲突。"}], "explanations": {"显然": "「显然」表示明显看出，与「两个人的差别」「很大」搭配，句意通顺。", "略微": "语义：「略微」表示程度轻，与「很大」的程度矛盾，句子不通。", "轻轻": "搭配：「轻轻」修饰轻柔的动作，不能修饰「差别很大」。", "稍": "语义：「稍」表示略微，与「很大」的程度相冲突。"}, "sentence_index": 6, "correct_answer": "显然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看不清他的脸，但他显然是在对我笑。", "explanation": "这里应该用〈好像〉。「显然」表示情况明显可见，而句中说「看不清他的脸」，证据与判断矛盾，应用「好像」表示推测。"}, {"text": "这个颜色显然很难看，我觉得。", "explanation": "这里应该用〈似乎〉。「显然」指客观上明显看出的事实，不能与「我觉得」这类主观判断搭配，表示主观印象应用「似乎」。"}, {"text": "我不知道，可是显然他会来。", "explanation": "这里应该用〈大概〉。「显然」指明显可见的情况，说话人说「不知道」时只能推测，应用「大概」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她显然的很开心。", "corrected_sentence": "她显然很开心。", "error_description": "错误：「显然」作状语修饰「很开心」，后面不加「的」，应说「她显然很开心」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个显然问题。", "corrected_sentence": "这是一个显然的问题。", "error_description": "错误：「显然」修饰名词「问题」时要加结构助词「的」，应说「显然的问题」，不能省去「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
