INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89528, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "紧接在当前这个之后的那一个。", "primary_collocate": null, "pronunciation": "xià yí gè", "ipa": "ɕja˥˩ i˧˥ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "请看下一个问题。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个路口往左走。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个周末我想去爬山。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个节目是唱歌。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一课讲完了，下一个环节是讨论。", "target_word": "下一个", "complexity_tier": "T3", "furigana": "zhè yí kè jiǎng wán le, xià yí ge huánjié shì tǎolùn.", "sentence_source": "generated"}, {"text": "你先做这道题,再做下一个题目。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在下一个红绿灯见面。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个季节是春天。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说下一个目标是考好成绩。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲完这一课,开始讲下一个故事。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下一次", "label": "复合"}, {"form": "上一个", "label": "复合"}, {"form": "下一個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "下一个:修饰名词,指紧接着的这一项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下一个", "is_correct": true, "explanation": "下一个：修饰“问题”，指紧接着的这一个。"}, {"text": "下一次", "is_correct": false, "explanation": "搭配：“下一次”指下一回的时间，不能修饰“问题”，“请看下一次问题”说不通。"}, {"text": "下一周", "is_correct": false, "explanation": "搭配：“下一周”指时间段，不能修饰“问题”，“下一周问题”不成立。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示每日，与“紧接着的那个问题”的顺序义无关。"}], "explanations": {"下一个": "下一个：修饰“问题”，指紧接着的这一个。", "下一次": "搭配：“下一次”指下一回的时间，不能修饰“问题”，“请看下一次问题”说不通。", "下一周": "搭配：“下一周”指时间段，不能修饰“问题”，“下一周问题”不成立。", "每天": "语义：“每天”表示每日，与“紧接着的那个问题”的顺序义无关。"}, "sentence_index": 0, "correct_answer": "下一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们吃完饭，下一个出发去车站。", "explanation": "这里应该用〈随后〉。表示紧接着某事之后要用随后，“下一个”只指排在后面的人或事物，不能表示动作的先后。"}, {"text": "他先练完琴，下一个才去吃饭。", "explanation": "这里应该用〈后来〉。表示事情发生的先后要用后来，“下一个”不能作时间副词。"}, {"text": "下一个同学都来了，教室很热闹。", "explanation": "这里应该用〈每个〉。表示全部的人要用每个，“下一个”只指紧接着的那一个，不能表示全体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下一个", "is_correct": true, "explanation": "下一个：修饰“红绿灯”，指紧接着的这一个。"}, {"text": "这一天", "is_correct": false, "explanation": "搭配：“这一天”指日子，不能修饰“红绿灯”，“在这一天红绿灯见面”说不通。"}, {"text": "下个月", "is_correct": false, "explanation": "搭配：“下个月”指时间段，不能修饰“红绿灯”，句子不成立。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去的时间，与“见面”的将来语境不符。"}], "explanations": {"下一个": "下一个：修饰“红绿灯”，指紧接着的这一个。", "这一天": "搭配：“这一天”指日子，不能修饰“红绿灯”，“在这一天红绿灯见面”说不通。", "下个月": "搭配：“下个月”指时间段，不能修饰“红绿灯”，句子不成立。", "上周": "语义：“上周”指过去的时间，与“见面”的将来语境不符。"}, "sentence_index": 6, "correct_answer": "下一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨停了，下一个我们就去公园。", "explanation": "这里应该用〈然后〉。表示先后相接的动作要用然后，“下一个”只指排在后面的人或事物，不能引出后续的动作。"}, {"text": "讲完这个，下一个我还有一个问题。", "explanation": "这里应该用〈另外〉。补充另一件事要用另外，“下一个”指紧接着的那一个，不表示补充。"}, {"text": "我们先练习，下一个讨论问题。", "explanation": "这里应该用〈接下来〉。表示接着做某事要用接下来，“下一个”不能作时间副词引出动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一段讲完了，请看节目下一个。", "corrected_sentence": "这一段讲完了，请看下一个节目。", "error_description": "错误：“节目下一个”，“下一个”是修饰名词的定语，必须放在名词前面，不能放在名词后面；正确：“下一个节目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "讨论结束了，这下一个环节是朗读。", "corrected_sentence": "讨论结束了，下一个环节是朗读。", "error_description": "错误：“这下一个环节”，“下一个”前不能加指示词“这”，它本身已表示紧接着的那一项；正确：“下一个环节是朗读”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
