INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt1_core', '{"pos": "结果补语", "semantic_class": "function", "definition": "尽是用完了,一点也不剩。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "这口老井的水，用了几百年也用不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè kǒu lǎo jǐng de shuǐ, yòng le jǐ bǎi nián yě yòng bú jìn.", "sentence_source": "generated"}, {"text": "爸爸留下的钱，我一辈子也花不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "bà ba liú xià de qián, wǒ yí bèi zi yě huā bú jìn.", "sentence_source": "generated"}, {"text": "这片森林的木材，砍了几代人也砍不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn sēn lín de mù cái, kǎn le jǐ dài rén yě kǎn bú jìn.", "sentence_source": "generated"}, {"text": "这座大山里的泉水，取了一年也取不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè zuò dà shān lǐ de quán shuǐ, qǔ le yì nián yě qǔ bú jìn.", "sentence_source": "generated"}, {"text": "他有花不尽的钱。", "target_word": "尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子有用不尽的力气。", "target_word": "尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座金矿的金子，挖一辈子也挖不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè zuò jīn kuàng de jīn zi, wā yí bèi zi yě wā bú jìn.", "sentence_source": "generated"}, {"text": "这片草原的牧草，牛羊吃一辈子也吃不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn cǎo yuán de mù cǎo, niú yáng chī yí bèi zi yě chī bú jìn.", "sentence_source": "generated"}, {"text": "这片海里的鱼，捕了几十年也捕不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn hǎi lǐ de yú, bǔ le jǐ shí nián yě bǔ bú jìn.", "sentence_source": "generated"}, {"text": "这笔遗产太多了，我们子孙三代也花不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè bǐ yí chǎn tài duō le, wǒ men zǐ sūn sān dài yě huā bú jìn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡", "label": "繁体"}, {"form": "用尽", "label": "复合"}, {"form": "无尽", "label": "复合"}], "register": "中性", "sense_fingerprint": "尽|结果补语|V不尽:用完、穷尽、一点不剩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尽", "is_correct": true, "explanation": "尽 jìn（第四声）：用完、一点不剩，是正确答案。"}, {"text": "金", "is_correct": false, "explanation": "金 jīn（第一声）与 jìn（第四声）声调不同，意思是金子。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、不松。"}, {"text": "静", "is_correct": false, "explanation": "静 jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}, {"text": "今", "is_correct": false, "explanation": "今 jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}], "explanations": {"尽": "尽 jìn（第四声）：用完、一点不剩，是正确答案。", "金": "金 jīn（第一声）与 jìn（第四声）声调不同，意思是金子。", "紧": "紧 jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、不松。", "静": "静 jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。", "今": "今 jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}, "sentence_index": null, "correct_answer": "尽"}, "level_3": {"options": [{"text": "尽", "is_correct": true, "explanation": "“用不尽”即用到一点不剩，符合“用了几百年也用不尽”的语境。"}, {"text": "上", "is_correct": false, "explanation": "语义：“用不上”表示用不到、没有用处，与“用了几百年”的语境矛盾。"}, {"text": "起", "is_correct": false, "explanation": "语义：“用不起”表示负担不起费用，与老井之水取用无需花钱的语境不合。"}, {"text": "动", "is_correct": false, "explanation": "搭配：“用不动”说物体无法挪动，不能用来形容用水，搭配不当。"}], "explanations": {"尽": "“用不尽”即用到一点不剩，符合“用了几百年也用不尽”的语境。", "上": "语义：“用不上”表示用不到、没有用处，与“用了几百年”的语境矛盾。", "起": "语义：“用不起”表示负担不起费用，与老井之水取用无需花钱的语境不合。", "动": "搭配：“用不动”说物体无法挪动，不能用来形容用水，搭配不当。"}, "sentence_index": 0, "correct_answer": "尽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于把作业做尽了，可以去玩了。", "explanation": "这里应该用〈完〉。“尽”多用于钱财、粮食、力气等可以耗尽的东西，表示用到一点不剩；作业做完要说“做完”。"}, {"text": "我把厨房打扫尽了，你可以进来了。", "explanation": "这里应该用〈完〉。“尽”表示一点不剩，不用于打扫这类动作的结束；打扫完要说“打扫完”。"}, {"text": "这学期的课我上尽了，下周开始放假。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，不用于课程结束；课上完要说“上完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尽", "is_correct": true, "explanation": "尽 jìn（第四声）：用完、一点不剩，是正确答案。"}, {"text": "筋", "is_correct": false, "explanation": "筋 jīn（第一声）与 jìn（第四声）声调不同，意思是筋骨、肌腱。"}, {"text": "斤", "is_correct": false, "explanation": "斤 jīn（第一声）与 jìn（第四声）声调不同，意思是重量单位“斤”。"}, {"text": "净", "is_correct": false, "explanation": "净 jìng 与 jìn 韵母不同（-ng 与 -n），意思是干净。"}, {"text": "竟", "is_correct": false, "explanation": "竟 jìng 与 jìn 韵母不同（-ng 与 -n），意思是竟然、居然。"}, {"text": "信", "is_correct": false, "explanation": "信 xìn（第四声）与 jìn 声母不同（x 与 j），意思是相信、信件。"}], "explanations": {"尽": "尽 jìn（第四声）：用完、一点不剩，是正确答案。", "筋": "筋 jīn（第一声）与 jìn（第四声）声调不同，意思是筋骨、肌腱。", "斤": "斤 jīn（第一声）与 jìn（第四声）声调不同，意思是重量单位“斤”。", "净": "净 jìng 与 jìn 韵母不同（-ng 与 -n），意思是干净。", "竟": "竟 jìng 与 jìn 韵母不同（-ng 与 -n），意思是竟然、居然。", "信": "信 xìn（第四声）与 jìn 声母不同（x 与 j），意思是相信、信件。"}, "sentence_index": null, "correct_answer": "尽"}, "level_3": {"options": [{"text": "尽", "is_correct": true, "explanation": "“挖不尽”即挖到一点不剩，符合“挖一辈子也挖不尽”的语境。"}, {"text": "通", "is_correct": false, "explanation": "语义：“挖不通”指挖不穿、挖不透，与金子数量多、挖不完的语境不合。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“挖不下”不是常用的结果补语搭配，“下”不能表示挖到一点不剩。"}, {"text": "清", "is_correct": false, "explanation": "搭配：“挖不清”表示挖得不清楚，不能说明金子挖尽的结果。"}], "explanations": {"尽": "“挖不尽”即挖到一点不剩，符合“挖一辈子也挖不尽”的语境。", "通": "语义：“挖不通”指挖不穿、挖不透，与金子数量多、挖不完的语境不合。", "下": "搭配：“挖不下”不是常用的结果补语搭配，“下”不能表示挖到一点不剩。", "清": "搭配：“挖不清”表示挖得不清楚，不能说明金子挖尽的结果。"}, "sentence_index": 6, "correct_answer": "尽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议终于开尽了，大家都松了一口气。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，多用于钱财、粮食、力气等可以耗尽的东西；会议结束要用“完”。"}, {"text": "这封信我写尽了，马上寄出去。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，多用于钱财、粮食、力气等；写信写完要说“写完”。"}, {"text": "这张桌子我擦尽了，你可以坐了。", "explanation": "这里应该用〈干净〉。擦到干干净净要说“擦干净”；“尽”表示一点不剩，不用于擦桌子这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些粮食，吃一辈子也吃尽不了。", "corrected_sentence": "这些粮食，吃一辈子也吃不尽。", "error_description": "错误形式“吃尽不了”，应为“吃不尽”。可能补语的否定式是“V不尽”，“不”要放在动词和“尽”之间，不能写成“V尽不了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井的水，抽一个月也抽得不尽。", "corrected_sentence": "这口井的水，抽一个月也抽不尽。", "error_description": "错误形式“抽得不尽”，应为“抽不尽”。可能补语的否定式是“V不尽”，“得”不能插在动词和“不”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专", "is_correct": true, "explanation": "专：只做一件事，与「兼」表示同时做另一件事相对，是反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：表示唱歌，与「兼」的意思没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑：表示奔跑，与「兼」的意思没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡：表示睡觉，与「兼」的意思没有反义关系。"}], "correct_answer": "专", "explanations": {"专": "专：只做一件事，与「兼」表示同时做另一件事相对，是反义关系。", "唱": "唱：表示唱歌，与「兼」的意思没有反义关系。", "跑": "跑：表示奔跑，与「兼」的意思没有反义关系。", "睡": "睡：表示睡觉，与「兼」的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专", "is_correct": true, "explanation": "专：只做一件事，与「兼」表示同时做另一件事相对，是反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：表示吃东西，与「兼」的意思没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：表示书写，与「兼」的意思没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：表示笑，与「兼」的意思没有反义关系。"}], "correct_answer": "专", "explanations": {"专": "专：只做一件事，与「兼」表示同时做另一件事相对，是反义关系。", "吃": "吃：表示吃东西，与「兼」的意思没有反义关系。", "写": "写：表示书写，与「兼」的意思没有反义关系。", "笑": "笑：表示笑，与「兼」的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "兼是一个人同时做两件事。", "primary_collocate": null, "pronunciation": "jiān", "ipa": "tɕjɛn˥", "syllable_count": 1, "sentences": [{"text": "他白天上班,晚上兼做家教。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师教数学,还兼着班主任。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在店里卖衣服,也兼管收钱。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王读书的时候兼做过服务员。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是司机，下班后也兼做快递员。", "target_word": "兼", "complexity_tier": "T3", "furigana": "tā shì sījī, xiàbān hòu yě jiān zuò kuàidìyuán.", "sentence_source": "generated"}, {"text": "我白天上班,周末兼做翻译。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家工作，还兼管家务。", "target_word": "兼", "complexity_tier": "T3", "furigana": "māma zài jiā gōngzuò, hái jiān guǎn jiāwù.", "sentence_source": "generated"}, {"text": "校长忙的时候,也兼教一节课。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理太忙,秘书兼管会议的事。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院工作,休息日兼做志愿者。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼着", "label": "体标"}, {"form": "兼了", "label": "体标"}, {"form": "兼职", "label": "复合"}, {"form": "兼任", "label": "复合"}], "register": "书面", "sense_fingerprint": "兼:同时做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时做另一件事，是正确答案。"}, {"text": "减", "is_correct": false, "explanation": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。"}, {"text": "江", "is_correct": false, "explanation": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}], "explanations": {"兼": "兼（jiān）：同时做另一件事，是正确答案。", "减": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。", "建": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。", "江": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。", "千": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「兼做」表示同时做另一件事，与白天上班、晚上做家教的语境相符。"}, {"text": "辞", "is_correct": false, "explanation": "搭配：「辞」多用于辞职、辞去职务，「辞做家教」不成词，也与白天上班的语境冲突。"}, {"text": "拒", "is_correct": false, "explanation": "语义：「拒做」表示拒绝去做，「晚上拒做家教」与句中做家教的意思相反。"}, {"text": "停", "is_correct": false, "explanation": "语义：「停做」表示停止，与「白天上班，晚上兼做」的并行意思相反。"}], "explanations": {"兼": "正确：「兼做」表示同时做另一件事，与白天上班、晚上做家教的语境相符。", "辞": "搭配：「辞」多用于辞职、辞去职务，「辞做家教」不成词，也与白天上班的语境冲突。", "拒": "语义：「拒做」表示拒绝去做，「晚上拒做家教」与句中做家教的意思相反。", "停": "语义：「停做」表示停止，与「白天上班，晚上兼做」的并行意思相反。"}, "sentence_index": 0, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我兼了一个苹果。", "explanation": "这里应该用〈吃〉。「兼」不能接具体食物作宾语，吃苹果要说〈吃〉。"}, {"text": "这家公司兼了那家小厂。", "explanation": "这里应该用〈兼并〉。「兼」单用不表示「吞并、收购」，要说「兼并」。"}, {"text": "他兼了一件新衣服。", "explanation": "这里应该用〈穿〉。「兼」不表示穿着，穿新衣服要说〈穿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时做另一件事，是正确答案。"}, {"text": "剑", "is_correct": false, "explanation": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。"}, {"text": "将", "is_correct": false, "explanation": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。"}, {"text": "迁", "is_correct": false, "explanation": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。"}, {"text": "检", "is_correct": false, "explanation": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}], "explanations": {"兼": "兼（jiān）：同时做另一件事，是正确答案。", "剑": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。", "将": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。", "迁": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。", "检": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「还兼管家务」表示在做妈妈工作的同时还管家务，与「还」表示增加的语义相符。"}, {"text": "请", "is_correct": false, "explanation": "搭配：「请」用于请人做事，「还请管家务」表示另找人管，与妈妈自己在家工作的语境不符。"}, {"text": "忘", "is_correct": false, "explanation": "语义：「忘」表示忘记，与「还」所表示的增加承担语义矛盾。"}, {"text": "躲", "is_correct": false, "explanation": "语义：「躲」表示躲避，与「还管家务」的承担语义相反。"}], "explanations": {"兼": "正确：「还兼管家务」表示在做妈妈工作的同时还管家务，与「还」表示增加的语义相符。", "请": "搭配：「请」用于请人做事，「还请管家务」表示另找人管，与妈妈自己在家工作的语境不符。", "忘": "语义：「忘」表示忘记，与「还」所表示的增加承担语义矛盾。", "躲": "语义：「躲」表示躲避，与「还管家务」的承担语义相反。"}, "sentence_index": 6, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去超市兼了一本书。", "explanation": "这里应该用〈买〉。「兼」不能直接接具体物品作宾语，去超市买书要说〈买〉。"}, {"text": "他下班时兼了超市。", "explanation": "这里应该用〈去〉。「兼」不能带处所作宾语，下班后去超市要说〈去〉。"}, {"text": "他很会兼了一只猫。", "explanation": "这里应该用〈养〉。「兼」不表示饲养，养猫要说〈养〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content,