INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同时做几件事或具有几种身份。", "primary_collocate": null, "pronunciation": "jiān", "ipa": "tɕjɛn˥", "syllable_count": 1, "sentences": [{"text": "他是我们的老板兼厨师。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生是医生兼作家。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是歌手兼演员。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子是客厅兼餐厅。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老师是班主任兼语文老师。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李是我的同学兼邻居。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这家店的店长兼收银员。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间是书房兼卧室。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是司机兼导游。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子是书桌兼饭桌。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼职", "label": "复合"}, {"form": "兼任", "label": "复合"}, {"form": "兼着", "label": "体标"}], "register": "书面", "sense_fingerprint": "兼:同时具有两种身份或用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时具有几种身份或用途，是正确答案。"}, {"text": "减", "is_correct": false, "explanation": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。"}, {"text": "江", "is_correct": false, "explanation": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}], "explanations": {"兼": "兼（jiān）：同时具有几种身份或用途，是正确答案。", "减": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。", "建": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。", "江": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。", "千": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「老板兼厨师」表示一人兼有两种身份，与句子的身份说明相符。"}, {"text": "辞", "is_correct": false, "explanation": "语义：「辞」表示解雇或辞去，「老板辞厨师」说的是辞退，与身份说明的语境不符。"}, {"text": "替", "is_correct": false, "explanation": "语义：「替」表示代替，「老板替厨师」说的是代替别人，与身份说明不符。"}, {"text": "请", "is_correct": false, "explanation": "搭配：「请」用于聘请别人，「老板请厨师」是另一件事，不能表示一人兼有两种身份。"}], "explanations": {"兼": "正确：「老板兼厨师」表示一人兼有两种身份，与句子的身份说明相符。", "辞": "语义：「辞」表示解雇或辞去，「老板辞厨师」说的是辞退，与身份说明的语境不符。", "替": "语义：「替」表示代替，「老板替厨师」说的是代替别人，与身份说明不符。", "请": "搭配：「请」用于聘请别人，「老板请厨师」是另一件事，不能表示一人兼有两种身份。"}, "sentence_index": 0, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把客厅和餐厅兼成一间。", "explanation": "这里应该用〈合并〉。「兼」表示同时具有两种身份或用途，不表示把两个空间合并成一个，要说「合并」。"}, {"text": "他很会兼学习和生活。", "explanation": "这里应该用〈兼顾〉。「兼」不单独表示「照顾到两方面」，要说「兼顾学习和生活」。"}, {"text": "两家公司兼了那家小厂。", "explanation": "这里应该用〈兼并〉。「兼」单用不表示「吞并、收购」，要说「兼并」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时具有几种身份或用途，是正确答案。"}, {"text": "剑", "is_correct": false, "explanation": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。"}, {"text": "将", "is_correct": false, "explanation": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。"}, {"text": "迁", "is_correct": false, "explanation": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。"}, {"text": "检", "is_correct": false, "explanation": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}], "explanations": {"兼": "兼（jiān）：同时具有几种身份或用途，是正确答案。", "剑": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。", "将": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。", "迁": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。", "检": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「店长兼收银员」表示一人兼有两种身份，与句子的身份说明相符。"}, {"text": "教", "is_correct": false, "explanation": "语义：「教」表示教导，「店长教收银员」说的是指导工作，与身份说明不符。"}, {"text": "带", "is_correct": false, "explanation": "语义：「带」表示带领，「店长带收银员」说的是带领他人，与一人兼有两种身份的意思不符。"}, {"text": "罚", "is_correct": false, "explanation": "搭配：「罚」多用于处罚违规者，「店长罚收银员」与身份说明的语境完全不搭。"}], "explanations": {"兼": "正确：「店长兼收银员」表示一人兼有两种身份，与句子的身份说明相符。", "教": "语义：「教」表示教导，「店长教收银员」说的是指导工作，与身份说明不符。", "带": "语义：「带」表示带领，「店长带收银员」说的是带领他人，与一人兼有两种身份的意思不符。", "罚": "搭配：「罚」多用于处罚违规者，「店长罚收银员」与身份说明的语境完全不搭。"}, "sentence_index": 6, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子兼了三条腿。", "explanation": "这里应该用〈有〉。「兼」表示兼有几种身份或用途，不表示拥有部件，这张桌子有三条腿要说〈有〉。"}, {"text": "他很会兼工作和生活。", "explanation": "这里应该用〈协调〉。「兼」不单独表示「配合、调和」，要说「协调工作和生活」。"}, {"text": "他把孩子兼给奶奶照顾。", "explanation": "这里应该用〈交给〉。「兼」不表示把人托付给别人，要说「交给」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间小屋是客厅兼了厨房。", "corrected_sentence": "这间小屋是客厅兼厨房。", "error_description": "错误：「兼了厨房」在「兼」后面加了「了」。正确：表示兼有两种用途，不能加「了」，应说「客厅兼厨房」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是老板又厨师。", "corrected_sentence": "他是老板兼厨师。", "error_description": "错误：「老板又厨师」，「又」是副词，不能连接两个身份名词；表示同时具有两种身份应当用「兼」，正确：「他是老板兼厨师」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
