INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“加上”是把一样东西再放进去，让原来的变多。", "primary_collocate": null, "pronunciation": "jiā shàng", "ipa": "tɕja˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "汤太淡了，再加上一点盐。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在名字后面加上你的电话号码。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡里再加上一块糖，就不苦了。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜再加上一点辣椒，味道会更好。", "target_word": "加上", "complexity_tier": "T3", "furigana": "zhè dào cài zài jiā shàng yì diǎn là jiāo, wèi dào huì gèng hǎo.", "sentence_source": "generated"}, {"text": "他在画上加上了一棵大树。", "target_word": "加上", "complexity_tier": "T3", "furigana": "tā zài huà shang jiā shàng le yì kē dà shù.", "sentence_source": "generated"}, {"text": "把你的年龄加上十，就是我的年龄。", "target_word": "加上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜不够吃，我们再加上两个吧。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在题目后面加上了一个问号。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕做好了，再加上一些水果。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在信的最后加上了一句“谢谢”。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "加上了", "label": "完成体"}, {"form": "加不上", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "把另一样东西或数量添加到原有的上面，使之增多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加上", "is_correct": true, "explanation": "加上（jiā shàng）：正确答案，指把东西添到原有的东西上面。"}, {"text": "加长", "is_correct": false, "explanation": "加长（jiā cháng）：第二个音节 cháng 与 shàng 的声母和声调都不同，意思是使变长，与“添上”无关。"}, {"text": "家长", "is_correct": false, "explanation": "家长（jiā zhǎng）：第二个音节 zhǎng 与 shàng 的声母（zh/sh）和声调不同，意思是父母或监护人。"}, {"text": "加仓", "is_correct": false, "explanation": "加仓（jiā cāng）：第二个音节 cāng 与 shàng 的声母和声调不同，意思是增加仓位。"}], "explanations": {"加上": "加上（jiā shàng）：正确答案，指把东西添到原有的东西上面。", "加长": "加长（jiā cháng）：第二个音节 cháng 与 shàng 的声母和声调都不同，意思是使变长，与“添上”无关。", "家长": "家长（jiā zhǎng）：第二个音节 zhǎng 与 shàng 的声母（zh/sh）和声调不同，意思是父母或监护人。", "加仓": "加仓（jiā cāng）：第二个音节 cāng 与 shàng 的声母和声调不同，意思是增加仓位。"}, "sentence_index": null, "correct_answer": "加上"}, "level_3": {"options": [{"text": "加上", "is_correct": true, "explanation": "正确：汤太淡，需要再添入一点盐，符合“加上”的意思。"}, {"text": "减去", "is_correct": false, "explanation": "语义：“减去”表示减少，与“汤太淡”需要增加咸味的语境相反。"}, {"text": "去掉", "is_correct": false, "explanation": "语义：“去掉”表示除去，汤太淡时不能再去掉盐。"}, {"text": "冲淡", "is_correct": false, "explanation": "搭配：“冲淡”的对象是味道或颜色，不能直接带“盐”作宾语。"}], "explanations": {"加上": "正确：汤太淡，需要再添入一点盐，符合“加上”的意思。", "减去": "语义：“减去”表示减少，与“汤太淡”需要增加咸味的语境相反。", "去掉": "语义：“去掉”表示除去，汤太淡时不能再去掉盐。", "冲淡": "搭配：“冲淡”的对象是味道或颜色，不能直接带“盐”作宾语。"}, "sentence_index": 0, "correct_answer": "加上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他加上了篮球队，每天都去训练。", "explanation": "这里应该用〈加入〉。加上表示把东西添到已有之物上面，参加团体要说“加入”，不能说“加上”。"}, {"text": "他的汉语水平加上了很多。", "explanation": "这里应该用〈提高〉。加上表示添上某物，水平的上升要用“提高”，不能说“加上”。"}, {"text": "他这几年的体重加上了十公斤。", "explanation": "这里应该用〈增加〉。加上表示把东西添到已有之物上面，体重的上升要用“增加”，不能说“加上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加上", "is_correct": true, "explanation": "正确：菜不够吃，再添两个符合“加上”的意思。"}, {"text": "减去", "is_correct": false, "explanation": "语义：“减去”表示减少，与“菜不够吃”的需要相矛盾。"}, {"text": "冲掉", "is_correct": false, "explanation": "搭配：“冲掉”用于水或污物，不能用于点的菜。"}, {"text": "退掉", "is_correct": false, "explanation": "语义：“退掉”是退回，菜不够吃时退掉两个与语境矛盾。"}], "explanations": {"加上": "正确：菜不够吃，再添两个符合“加上”的意思。", "减去": "语义：“减去”表示减少，与“菜不够吃”的需要相矛盾。", "冲掉": "搭配：“冲掉”用于水或污物，不能用于点的菜。", "退掉": "语义：“退掉”是退回，菜不够吃时退掉两个与语境矛盾。"}, "sentence_index": 6, "correct_answer": "加上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他加上了那次比赛，还拿了第一名。", "explanation": "这里应该用〈参加〉。加上表示添到已有之物上面，不用于参与活动。"}, {"text": "他在这次比赛中加上了很多经验。", "explanation": "这里应该用〈收获〉。加上表示添上某物，抽象的经验要用“收获”。"}, {"text": "他在比赛中加上了第一名。", "explanation": "这里应该用〈取得〉。加上表示添到已有之物上面，名次是比赛取得的结果，要说“取得第一名”，不能说“加上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在蛋糕上加上着一颗草莓。", "corrected_sentence": "她在蛋糕上加上了一颗草莓。", "error_description": "动态助词错误：“着”不能接在“加上”之后，应改为动态助词“了”，说“加上了一颗草莓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在日记最后加上起来一个笑脸。", "corrected_sentence": "他在日记最后加上了一个笑脸。", "error_description": "补语错误：“起来”不能接在“加上”之后，应删去，改为动态助词“了”，说“加上了一个笑脸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
