INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "abstract", "definition": "连词：在已有的条件、原因或数量之外，再补充一项，表示相加或追加。", "primary_collocate": null, "pronunciation": "jiā shàng", "ipa": "tɕja˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天气不好，加上路很远，我们没去。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很聪明，加上努力，成绩一直很好。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租很贵，加上离公司很远，他想搬家。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天很累，加上头疼，想早点睡觉。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车，加上下雨，我迟到了半小时。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工资加上奖金，他每月有一万块。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "五加六，再加上七，一共是十八。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的房租加上水电费，一共三千块。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他本来就爱吃肉，加上妈妈做得好，吃了很多。", "target_word": "加上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票加上住的钱，这次旅行要五千块。", "target_word": "加上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：在已有条件、原因或数量之外再补充一项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加上", "is_correct": true, "explanation": "加上（jiā shàng）：正确答案，这里指再补充一个条件或原因。"}, {"text": "家长", "is_correct": false, "explanation": "家长（jiā zhǎng）：第二个音节 zhǎng 与 shàng 的声母（zh/sh）和声调不同，意思是父母或监护人。"}, {"text": "家常", "is_correct": false, "explanation": "家常（jiā cháng）：第二个音节 cháng 与 shàng 的声母（ch/sh）和声调不同，意思是家里日常的，与“加上”不同。"}, {"text": "加仓", "is_correct": false, "explanation": "加仓（jiā cāng）：第二个音节 cāng 与 shàng 的声母和声调不同，意思是增加仓位。"}], "explanations": {"加上": "加上（jiā shàng）：正确答案，这里指再补充一个条件或原因。", "家长": "家长（jiā zhǎng）：第二个音节 zhǎng 与 shàng 的声母（zh/sh）和声调不同，意思是父母或监护人。", "家常": "家常（jiā cháng）：第二个音节 cháng 与 shàng 的声母（ch/sh）和声调不同，意思是家里日常的，与“加上”不同。", "加仓": "加仓（jiā cāng）：第二个音节 cāng 与 shàng 的声母和声调不同，意思是增加仓位。"}, "sentence_index": null, "correct_answer": "加上"}, "level_3": {"options": [{"text": "加上", "is_correct": true, "explanation": "正确：这里表示再补充一个不去的原因，符合“加上”的连词用法。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，路远不是天气不好造成的，与句意矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，路远与天气不好之间没有结果关系。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”需要与“还是”“仍然”等配合，单独用在此处不通顺。"}], "explanations": {"加上": "正确：这里表示再补充一个不去的原因，符合“加上”的连词用法。", "因此": "语义：“因此”表示结果，路远不是天气不好造成的，与句意矛盾。", "所以": "语义：“所以”表示因果，路远与天气不好之间没有结果关系。", "尽管": "搭配：“尽管”需要与“还是”“仍然”等配合，单独用在此处不通顺。"}, "sentence_index": 0, "correct_answer": "加上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天天气很好，加上我们没去，很可惜。", "explanation": "这里应该用〈可是〉。加上表示再补充一个条件或原因，表示转折要用“可是”，不能用“加上”。"}, {"text": "这次我们不去公园，加上去图书馆了。", "explanation": "这里应该用〈改为〉。加上表示再补充，不能表示替代；前面说不去公园，应说“改为去图书馆”。"}, {"text": "快走吧，加上我们就迟到了。", "explanation": "这里应该用〈否则〉。加上表示再补充，不能表示假设的后果，要用“否则”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加上", "is_correct": true, "explanation": "正确：再把七加上，与前面的和相加，符合“一共是十八”的算式。"}, {"text": "减去", "is_correct": false, "explanation": "语义：“减去”表示相减，再减去七会使总数变少，与“一共是十八”不符。"}, {"text": "乘以", "is_correct": false, "explanation": "语义：“乘以”表示相乘，十一再乘以七得七十七，与“一共是十八”不符。"}, {"text": "除以", "is_correct": false, "explanation": "语义：“除以”表示相除，十一除以七不等于十八，与“一共是十八”矛盾。"}], "explanations": {"加上": "正确：再把七加上，与前面的和相加，符合“一共是十八”的算式。", "减去": "语义：“减去”表示相减，再减去七会使总数变少，与“一共是十八”不符。", "乘以": "语义：“乘以”表示相乘，十一再乘以七得七十七，与“一共是十八”不符。", "除以": "语义：“除以”表示相除，十一除以七不等于十八，与“一共是十八”矛盾。"}, "sentence_index": 6, "correct_answer": "加上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天很冷，加上我们还是去了公园。", "explanation": "这里应该用〈虽然〉。加上表示再补充，不能表示让步，要用“虽然……还是……”。"}, {"text": "他很累，加上睡了。", "explanation": "这里应该用〈于是〉。加上表示再补充，不能引出动作的结果。"}, {"text": "他吃完饭，加上睡了。", "explanation": "这里应该用〈然后〉。加上表示补充，不能表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气冷，加上了风大，我们不想出去。", "corrected_sentence": "天气冷，加上风大，我们不想出去。", "error_description": "动态助词错误：连词“加上”表示再补充，后面不接动态助词“了”，应说“加上风大”，不能说“加上了风大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在路上堵车，加上加上下雨，就迟到了。", "corrected_sentence": "我们在路上堵车，加上下雨，就迟到了。", "error_description": "重复错误：连词“加上”只用一次，应说“加上下雨”，不能说“加上加上下雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
