INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "害怕是心里觉得不安全,想躲开。", "primary_collocate": null, "pronunciation": "hài pà", "ipa": "xaɪ˥˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "我害怕蛇，看到就想躲开。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫害怕洗澡，一听水声就跑。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他害怕见医生，所以一直不去医院。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟害怕黑，晚上不敢关灯睡觉。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人害怕坐飞机。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她害怕老鼠，看到就大叫。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子害怕打针，一看到医生就哭了。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从小就害怕高的地方。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗害怕大声音，一直躲在桌子下面。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人害怕一个人在家，晚上总睡不好。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害怕了", "label": "体标"}, {"form": "害怕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：觉得不安全而想躲开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示觉得不安全而想躲开，与“想躲开”相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”与后文“想躲开”矛盾，喜欢蛇的人不会想躲开。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”多用于客人、来宾，不说“迎接蛇”。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”是仔细看，与“看到就想躲开”不合。"}], "explanations": {"害怕": "“害怕”表示觉得不安全而想躲开，与“想躲开”相合。", "喜欢": "语义：“喜欢”与后文“想躲开”矛盾，喜欢蛇的人不会想躲开。", "迎接": "搭配：“迎接”多用于客人、来宾，不说“迎接蛇”。", "观察": "语义：“观察”是仔细看，与“看到就想躲开”不合。"}, "sentence_index": 0, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我害怕中午的阳光，所以每天都去晒太阳。", "explanation": "这里应该用〈喜欢〉。“害怕”表示觉得不安全、想躲开，“每天去晒太阳”是主动靠近，应表示喜爱，不能用“害怕”。"}, {"text": "他害怕妈妈送来的鲜花。", "explanation": "这里应该用〈感激〉。“害怕”表示觉得不安全、想躲开，“妈妈送来的鲜花”应表示感激或喜爱，不能用“害怕”。"}, {"text": "她害怕每天都能见到的好朋友。", "explanation": "这里应该用〈亲近〉。“害怕”表示觉得不安全、想躲开，“好朋友”让人亲近，不能用“害怕”表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示觉得打针不安全而想躲开，与“一看到医生就哭了”相合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”是期待，与“一看到医生就哭了”矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：孩子讨论打针与“一看到医生就哭了”的反应不协调，不符合这里的情境。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不与“打针”搭配，打针是注射的动作，不能喝。"}], "explanations": {"害怕": "“害怕”表示觉得打针不安全而想躲开，与“一看到医生就哭了”相合。", "盼望": "语义：“盼望”是期待，与“一看到医生就哭了”矛盾。", "讨论": "语义：孩子讨论打针与“一看到医生就哭了”的反应不协调，不符合这里的情境。", "喝": "搭配：“喝”不与“打针”搭配，打针是注射的动作，不能喝。"}, "sentence_index": 6, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈害怕看到孩子的笑脸。", "explanation": "这里应该用〈喜欢〉。“害怕”表示觉得不安全、想躲开，“看到孩子的笑脸”应表示喜爱，不能用“害怕”。"}, {"text": "我害怕这个周末的假期。", "explanation": "这里应该用〈期待〉。“害怕”表示觉得不安全、想躲开，“假期”令人期待，应用〈期待〉。"}, {"text": "她害怕天气很好的日子。", "explanation": "这里应该用〈向往〉。“害怕”表示觉得不安全、想躲开，“天气很好的日子”令人愉快，应用〈向往〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我害怕的不敢靠近狗。", "corrected_sentence": "我害怕得不敢靠近狗。", "error_description": "“得”与“的”混用：“害怕”后接表示程度结果的“得”，不能用“的”，应改为“害怕得不敢靠近狗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来别害怕狗。", "corrected_sentence": "她从来不害怕狗。", "error_description": "否定词用错：叙述习惯要用“不”，“别”只用于劝阻或祈使，应说“从来不害怕狗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
