INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到困难或危险时心中不安、胆怯。", "primary_collocate": null, "pronunciation": "hài pà", "ipa": "xaɪ˥˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "看到大狗跑过来，小孩很害怕。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里一个人走路，她有点害怕。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到危险时，不要害怕，要冷静。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他害怕地躲在门后面。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山路很陡，我害怕会摔下去。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她第一次上台，害怕得手都在抖。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打雷的时候，弟弟害怕极了。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别害怕，医生会帮你的。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不害怕困难。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过桥的时候，我害怕得不敢往下看。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害怕了", "label": "体标"}, {"form": "害怕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：遇到危险或困难时心里不安、胆怯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示看到大狗跑过来而心中胆怯，与“小孩很”相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”必须带宾语（欢迎某人或某事），“小孩很欢迎”缺少宾语，不成立。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是动作，不是心理状态，“小孩很游泳”不成立。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”必须带宾语（原谅某人），“小孩很原谅”缺少宾语，不成立。"}], "explanations": {"害怕": "“害怕”表示看到大狗跑过来而心中胆怯，与“小孩很”相合。", "欢迎": "配价：“欢迎”必须带宾语（欢迎某人或某事），“小孩很欢迎”缺少宾语，不成立。", "游泳": "语义：游泳是动作，不是心理状态，“小孩很游泳”不成立。", "原谅": "配价：“原谅”必须带宾语（原谅某人），“小孩很原谅”缺少宾语，不成立。"}, "sentence_index": 0, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很害怕你送的生日礼物。", "explanation": "这里应该用〈喜欢〉。“害怕”指遇到危险或困难时心中不安、胆怯，不能用来表示对生日礼物的喜爱。"}, {"text": "他害怕吃到好吃的蛋糕。", "explanation": "这里应该用〈期待〉。“害怕”指遇到危险或困难时心中不安，“好吃的蛋糕”令人期待，不能用“害怕”。"}, {"text": "她害怕每天都有好消息。", "explanation": "这里应该用〈盼望〉。“害怕”指心中不安、胆怯，“好消息”令人高兴，应用〈盼望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示打雷时心中胆怯，与“弟弟……极了”相合。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”是整理的动作，不是心理状态，与“打雷的时候”不相合。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”必须带宾语（表扬某人），“弟弟……极了”缺少宾语，不成立。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是洗身体的动作，不表示心理状态，与“打雷的时候”不相合。"}], "explanations": {"害怕": "“害怕”表示打雷时心中胆怯，与“弟弟……极了”相合。", "收拾": "语义：“收拾”是整理的动作，不是心理状态，与“打雷的时候”不相合。", "表扬": "配价：“表扬”必须带宾语（表扬某人），“弟弟……极了”缺少宾语，不成立。", "洗澡": "语义：“洗澡”是洗身体的动作，不表示心理状态，与“打雷的时候”不相合。"}, "sentence_index": 6, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她害怕这只小猫的可爱模样。", "explanation": "这里应该用〈喜欢〉。“害怕”指心中不安、胆怯，“可爱的模样”令人喜爱，应用〈喜欢〉。"}, {"text": "他害怕太阳每天都从东边升起。", "explanation": "这里应该用〈不在意〉。“害怕”指心中不安、胆怯，“太阳每天都从东边升起”是自然规律，应表示不在意。"}, {"text": "我害怕吃妈妈做的饭。", "explanation": "这里应该用〈爱吃〉。“害怕”指心中不安、胆怯，吃妈妈做的饭应表示喜欢，用〈爱吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他害怕的不敢出门。", "corrected_sentence": "他害怕得不敢出门。", "error_description": "“得”与“的”混用：表示程度结果的补语要用“得”，“害怕的”不能修饰后面的动词短语，应改为“害怕得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候把大狗害怕。", "corrected_sentence": "他小时候害怕大狗。", "error_description": "“害怕”是不及物心理动词，没有可处置的结果，不能用“把”字句处置其宾语，应说“害怕大狗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
