INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89587, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男孩或男人喜欢、常常在一起的女孩。", "primary_collocate": null, "pronunciation": "nǚ yǒu", "ipa": "ny˨˩˦ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的女友是一位小学老师。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末他要陪女友去看电影。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我女友做的饭特别好吃。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给女友买了一束红玫瑰。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李带着女友回家见父母。", "target_word": "女友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和女友认识三年了。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的女友住在上海，他们很少见面。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天是女友的生日，他订了蛋糕。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把女友的照片放在钱包里。", "target_word": "女友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女友说，她不喜欢吃辣的。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "前女友", "label": "复合"}], "register": "中性", "sense_fingerprint": "男方的恋爱对象，女朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89587, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。女友 nǚ yǒu，指男子的恋爱对象。"}, {"text": "男友", "is_correct": false, "explanation": "nán（第二声）与 nǚ（第三声）韵母不同（an 与 ü），声调也不同，意思是男朋友，与女友指的对象相反。"}, {"text": "难友", "is_correct": false, "explanation": "nàn（第四声）与 nǚ（第三声）韵母和声调都不同（an 与 ü），意思是同患难的人。"}, {"text": "旅友", "is_correct": false, "explanation": "lǚ 与 nǚ 声母不同（l 与 n），意思是旅途中的同伴。"}, {"text": "你有", "is_correct": false, "explanation": "nǐ（第三声）与 nǚ（第三声）韵母不同（i 与 ü），意思是“你有”，是短语。"}, {"text": "哪有", "is_correct": false, "explanation": "nǎ（第三声）与 nǚ（第三声）韵母不同（a 与 ü），意思是“哪有”，是反问短语。"}, {"text": "那有", "is_correct": false, "explanation": "nà（第四声）与 nǚ（第三声）韵母不同（a 与 ü），声调也不同，意思是“那有”，是短语。"}], "explanations": {"女友": "正确答案。女友 nǚ yǒu，指男子的恋爱对象。", "男友": "nán（第二声）与 nǚ（第三声）韵母不同（an 与 ü），声调也不同，意思是男朋友，与女友指的对象相反。", "难友": "nàn（第四声）与 nǚ（第三声）韵母和声调都不同（an 与 ü），意思是同患难的人。", "旅友": "lǚ 与 nǚ 声母不同（l 与 n），意思是旅途中的同伴。", "你有": "nǐ（第三声）与 nǚ（第三声）韵母不同（i 与 ü），意思是“你有”，是短语。", "哪有": "nǎ（第三声）与 nǚ（第三声）韵母不同（a 与 ü），意思是“哪有”，是反问短语。", "那有": "nà（第四声）与 nǚ（第三声）韵母不同（a 与 ü），声调也不同，意思是“那有”，是短语。"}, "sentence_index": null, "correct_answer": "女友"}, "level_3": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。“他的女友是一位小学老师”中，“女友”指男方的恋爱对象，与句意相符。"}, {"text": "女医生", "is_correct": false, "explanation": "语义：“一位小学老师”与“医生”的职业冲突，“他的女医生是一位小学老师”说不通。"}, {"text": "女学生", "is_correct": false, "explanation": "语义：“学生”不能同时是“小学老师”，身份矛盾。"}, {"text": "女司机", "is_correct": false, "explanation": "语义：“司机”与“小学老师”是两种职业，“他的女司机是一位小学老师”说不通。"}], "explanations": {"女友": "正确答案。“他的女友是一位小学老师”中，“女友”指男方的恋爱对象，与句意相符。", "女医生": "语义：“一位小学老师”与“医生”的职业冲突，“他的女医生是一位小学老师”说不通。", "女学生": "语义：“学生”不能同时是“小学老师”，身份矛盾。", "女司机": "语义：“司机”与“小学老师”是两种职业，“他的女司机是一位小学老师”说不通。"}, "sentence_index": 0, "correct_answer": "女友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和女友结婚十年了。", "explanation": "这里应该用〈妻子〉。女友指还在恋爱中的对象，已经结婚的应说“妻子”。"}, {"text": "我们科室的女友都很能干。", "explanation": "这里应该用〈同事〉。女友指男子喜欢的女孩，不能用来指同单位的女同事。"}, {"text": "班上的女友大多爱看小说。", "explanation": "这里应该用〈女生〉。女友指男子喜欢的女孩，不能泛指班上的女生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。“他的女友住在上海，他们很少见面”中，“女友”指恋爱对象，与异地、少见面的情况相符。"}, {"text": "女佣", "is_correct": false, "explanation": "语义：佣人通常与雇主同住，不会“很少见面”，与句中的情况不符。"}, {"text": "女邻居", "is_correct": false, "explanation": "语义：邻居通常住得很近，“住在上海”且“很少见面”与“邻居”的关系矛盾。"}, {"text": "女室友", "is_correct": false, "explanation": "语义：室友与“他”同住，而句中“住在上海”且“很少见面”，与室友的身份矛盾。"}], "explanations": {"女友": "正确答案。“他的女友住在上海，他们很少见面”中，“女友”指恋爱对象，与异地、少见面的情况相符。", "女佣": "语义：佣人通常与雇主同住，不会“很少见面”，与句中的情况不符。", "女邻居": "语义：邻居通常住得很近，“住在上海”且“很少见面”与“邻居”的关系矛盾。", "女室友": "语义：室友与“他”同住，而句中“住在上海”且“很少见面”，与室友的身份矛盾。"}, "sentence_index": 6, "correct_answer": "女友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹是一个女友，她很喜欢画画。", "explanation": "这里应该用〈女生〉。女友指男子的恋爱对象，不能用来称呼自己的妹妹。"}, {"text": "我的女友是个男生，他很温柔。", "explanation": "这里应该用〈恋人〉。女友只指女性恋爱对象，句中的对象是男生，应说“恋人”。"}, {"text": "这家店的女友卖的衣服很便宜。", "explanation": "这里应该用〈售货员〉。女友指男子喜欢的女孩，不能用来指店里的女售货员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带着一只女友去看电影。", "corrected_sentence": "他带着一位女友去看电影。", "error_description": "量词错误：“女友”指人，量词应用“位”或“个”，不能用“只”。正确说法是“一位女友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的女友的很喜欢旅行。", "corrected_sentence": "我的女友很喜欢旅行。", "error_description": "“的”位置错误：“的”后面紧接副词“很”，这是多余的。“女友的”后接名词是合法的（如“女友的朋友”），但这里“的”后接的是“很”，应删去，写作“我的女友很喜欢旅行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
