INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男子的恋爱对象；也指女性朋友。", "primary_collocate": null, "pronunciation": "nǚ yǒu", "ipa": "ny˨˩˦ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他向大家介绍了自己的新女友。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和几位女友今晚都来参加聚会。", "target_word": "女友", "complexity_tier": "T3", "furigana": "nǚ yǒu", "sentence_source": "generated"}, {"text": "王先生的女友长得又高又瘦。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和女友因为小事吵架了。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和几位女友周末常常一起去爬山。", "target_word": "女友", "complexity_tier": "T3", "furigana": "nǚ yǒu", "sentence_source": "generated"}, {"text": "他在女友面前总是很害羞。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天她和几位女友去喝茶了。", "target_word": "女友", "complexity_tier": "T3", "furigana": "nǚ yǒu", "sentence_source": "generated"}, {"text": "他的女友送了他一条围巾。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学时他有过一个女友，后来分手了。", "target_word": "女友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想和女友一起去旅行。", "target_word": "女友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "前女友", "label": "复合"}], "register": "中性", "sense_fingerprint": "男子的恋爱对象，也可泛指女性朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。女友 nǚ yǒu，指男子的恋爱对象，也可指女性朋友。"}, {"text": "男友", "is_correct": false, "explanation": "nán（第二声）与 nǚ（第三声）韵母不同（an 与 ü），声调也不同，意思是男朋友，与女友指的对象相反。"}, {"text": "难友", "is_correct": false, "explanation": "nàn（第四声）与 nǚ（第三声）韵母和声调都不同（an 与 ü），意思是同患难的人。"}, {"text": "旅友", "is_correct": false, "explanation": "lǚ 与 nǚ 声母不同（l 与 n），意思是旅途中的同伴。"}, {"text": "你有", "is_correct": false, "explanation": "nǐ（第三声）与 nǚ（第三声）韵母不同（i 与 ü），意思是“你有”，是短语。"}, {"text": "哪有", "is_correct": false, "explanation": "nǎ（第三声）与 nǚ（第三声）韵母不同（a 与 ü），意思是“哪有”，是反问短语。"}, {"text": "那有", "is_correct": false, "explanation": "nà（第四声）与 nǚ（第三声）韵母不同（a 与 ü），声调也不同，意思是“那有”，是短语。"}], "explanations": {"女友": "正确答案。女友 nǚ yǒu，指男子的恋爱对象，也可指女性朋友。", "男友": "nán（第二声）与 nǚ（第三声）韵母不同（an 与 ü），声调也不同，意思是男朋友，与女友指的对象相反。", "难友": "nàn（第四声）与 nǚ（第三声）韵母和声调都不同（an 与 ü），意思是同患难的人。", "旅友": "lǚ 与 nǚ 声母不同（l 与 n），意思是旅途中的同伴。", "你有": "nǐ（第三声）与 nǚ（第三声）韵母不同（i 与 ü），意思是“你有”，是短语。", "哪有": "nǎ（第三声）与 nǚ（第三声）韵母不同（a 与 ü），意思是“哪有”，是反问短语。", "那有": "nà（第四声）与 nǚ（第三声）韵母不同（a 与 ü），声调也不同，意思是“那有”，是短语。"}, "sentence_index": null, "correct_answer": "女友"}, "level_3": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。“自己的新女友”指男子的恋爱对象，与“介绍给大家”的语境相符。"}, {"text": "老朋友", "is_correct": false, "explanation": "语义：“新”与“老”矛盾，“自己的新老朋友”说不通。"}, {"text": "前任", "is_correct": false, "explanation": "语义：“前任”指已经过去的恋人，与“新”矛盾。"}, {"text": "前妻", "is_correct": false, "explanation": "语义：“前妻”指已离婚的妻子，与“新”矛盾，“他向大家介绍了自己的新前妻”说不通。"}], "explanations": {"女友": "正确答案。“自己的新女友”指男子的恋爱对象，与“介绍给大家”的语境相符。", "老朋友": "语义：“新”与“老”矛盾，“自己的新老朋友”说不通。", "前任": "语义：“前任”指已经过去的恋人，与“新”矛盾。", "前妻": "语义：“前妻”指已离婚的妻子，与“新”矛盾，“他向大家介绍了自己的新前妻”说不通。"}, "sentence_index": 0, "correct_answer": "女友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的女友前年就和他离婚了。", "explanation": "这里应该用〈妻子〉。女友指恋爱中的对象，没有结婚，不能说“离婚”。"}, {"text": "我妹妹是个女友，她很爱画画。", "explanation": "这里应该用〈女生〉。女友不能用来指自己的妹妹，妹妹既不是恋爱对象，也不是女性朋友。"}, {"text": "这位女友是我的男性朋友，我们常一起打球。", "explanation": "这里应该用〈朋友〉。女友指女性，不能用来指男性朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女友", "is_correct": true, "explanation": "正确答案。“昨天她和几位女友去喝茶了”中，“女友”指女性朋友，与句意相符。"}, {"text": "女婴", "is_correct": false, "explanation": "语义：婴儿不能去喝茶，与“去喝茶了”的情境矛盾。"}, {"text": "女犯人", "is_correct": false, "explanation": "语义：犯人一般不能随意外出喝茶，与句意不符。"}, {"text": "女鬼", "is_correct": false, "explanation": "语义：鬼魂不能去喝茶，“昨天她和几位女鬼去喝茶了”与常理相悖。"}], "explanations": {"女友": "正确答案。“昨天她和几位女友去喝茶了”中，“女友”指女性朋友，与句意相符。", "女婴": "语义：婴儿不能去喝茶，与“去喝茶了”的情境矛盾。", "女犯人": "语义：犯人一般不能随意外出喝茶，与句意不符。", "女鬼": "语义：鬼魂不能去喝茶，“昨天她和几位女鬼去喝茶了”与常理相悖。"}, "sentence_index": 6, "correct_answer": "女友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟是一个女友，他很爱运动。", "explanation": "这里应该用〈男孩〉。女友指女性，不能用来指男性的弟弟。"}, {"text": "他的女友是个很温柔的男生。", "explanation": "这里应该用〈男友〉。女友指女性，句中的对象是男生，应说“男友”。"}, {"text": "这次比赛的女友拿到了冠军。", "explanation": "这里应该用〈选手〉。女友指男子的恋爱对象或女性朋友，不能指比赛中的女选手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只女友，两人感情很好。", "corrected_sentence": "他有一位女友，两人感情很好。", "error_description": "量词错误：“女友”指人，量词应用“位”或“个”，不能用“只”。正确说法是“一位女友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的一只女友很爱看书。", "corrected_sentence": "我的一位女友很爱看书。", "error_description": "量词错误：“女友”指人，量词应用“位”或“个”，不能用“只”。正确说法是“我的一位女友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
