INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就地是就在那个地方,不到别处去。", "primary_collocate": null, "pronunciation": "jiù dì", "ipa": "tɕjoʊ̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他们累了,就地坐在路边。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要乱跑,请大家就地等我。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有房子,我们就地过夜。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路用的石头是就地取材的。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听见响声,就地蹲下了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了,司机就地修了起来。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题要就地解决,不用送到别处。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雪太大,大家就地住下了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的菜叶,工人们就地埋了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公园里就地铺开了一块布。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "就在当地不去别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极力", "is_correct": false, "explanation": "搭配：“极力”表示竭力，不能修饰“坐”，与“累了坐下歇息”的语境不符。"}, {"text": "连夜", "is_correct": false, "explanation": "语义：“连夜”指整夜，与“累了坐在路边”的即时情境矛盾。"}, {"text": "就地", "is_correct": true, "explanation": "就地：就在当地，不挪动，与“累了坐在路边”的语境相符。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久，与“累了歇一歇”的暂时性矛盾。"}], "explanations": {"极力": "搭配：“极力”表示竭力，不能修饰“坐”，与“累了坐下歇息”的语境不符。", "连夜": "语义：“连夜”指整夜，与“累了坐在路边”的即时情境矛盾。", "就地": "就地：就在当地，不挪动，与“累了坐在路边”的语境相符。", "永远": "语义：“永远”表示长久，与“累了歇一歇”的暂时性矛盾。"}, "sentence_index": 0, "correct_answer": "就地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车坏了，我们就地把车送到修理厂。", "explanation": "这里应该用〈就近〉。就地表示不挪地方，送车去修理厂要离开原地；就近指离得近，与语境相符。"}, {"text": "收到消息，他就地坐飞机去了北京。", "explanation": "这里应该用〈当即〉。就地表示不换地方，“坐飞机去北京”需要换地方；当即表示立刻，符合语境。"}, {"text": "听到警报，他就地起身离开了房间。", "explanation": "这里应该用〈即刻〉。就地表示不换地方，“离开房间”需要换地方；即刻表示马上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远远", "is_correct": false, "explanation": "搭配：“远远”修饰距离或差距，不能修饰“解决”。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”不能修饰“解决”，与“不用送到别处”的语境不符。"}, {"text": "就地", "is_correct": true, "explanation": "就地：就在当地处理，与“不用送到别处”相符。"}, {"text": "一味", "is_correct": false, "explanation": "搭配：“一味”表示只管、一直，不能修饰“解决”，与语境不符。"}], "explanations": {"远远": "搭配：“远远”修饰距离或差距，不能修饰“解决”。", "乱": "搭配：“乱”不能修饰“解决”，与“不用送到别处”的语境不符。", "就地": "就地：就在当地处理，与“不用送到别处”相符。", "一味": "搭配：“一味”表示只管、一直，不能修饰“解决”，与语境不符。"}, "sentence_index": 6, "correct_answer": "就地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到敲门声，她就地跑了出去。", "explanation": "这里应该用〈随即〉。就地表示不离开原地，“跑了出去”需要离开；随即表示紧接着。"}, {"text": "发现车祸，他就地跑去救人。", "explanation": "这里应该用〈立即〉。就地表示不挪地方，“跑去救人”需要移动；立即表示马上。"}, {"text": "比赛结束，她就地离开了球场。", "explanation": "这里应该用〈就此〉。就地表示不换地方，“离开球场”需要换地方；就此表示于是、从此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走累了，在就地歇了一会儿。", "corrected_sentence": "我们走累了，就地歇了一会儿。", "error_description": "错误：“就地”前多加了“在”。“就地”是副词，直接修饰动词“歇”，前面不能加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们玩累了，就地的睡着了。", "corrected_sentence": "孩子们玩累了，就地睡着了。", "error_description": "错误：副词“就地”后面多加了“的”。“就地”是副词，应直接修饰动词“睡着”，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
