INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内情;内部的情况。", "primary_collocate": null, "pronunciation": "jiù lǐ", "ipa": "tɕjoʊ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他刚来公司，不知就里，就说了很多话。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没把就里告诉客人，客人还以为出了大事。", "target_word": "就里", "complexity_tier": "T3", "furigana": "jiù lǐ", "sentence_source": "generated"}, {"text": "这件事的就里，只有经理一个人清楚。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者到处打听，想弄清这件事的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外人不了解就里，难免会误会他们。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张一直瞒着我，我至今不知道其中的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着摇摇头，没有说出其中的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先别问，等我告诉你这里面的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知就里的人，看到他哭都很吃惊。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情的就里都告诉了警察。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "就里|名词|内情，内部的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“就里”指内情，与“不知内情就说了很多话”的意思一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“不知……就说话”的情况无关，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是需要了解的情况，“不知味道，就说了很多话”不合逻辑。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”多用于衣物、物品，“不知尺寸”接“就说很多话”搭配不当。"}], "explanations": {"就里": "正确：“就里”指内情，与“不知内情就说了很多话”的意思一致。", "颜色": "语义：颜色与“不知……就说话”的情况无关，句子说不通。", "味道": "语义：味道不是需要了解的情况，“不知味道，就说了很多话”不合逻辑。", "尺寸": "搭配：“尺寸”多用于衣物、物品，“不知尺寸”接“就说很多话”搭配不当。"}, "sentence_index": 0, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告列出了所有就里。", "explanation": "这里应该用〈细节〉。就里指事情背后没有说出的内情，不指报告中列出的具体细节。"}, {"text": "这种饮料的就里有很多糖。", "explanation": "这里应该用〈成分〉。就里指内情，不能用来说饮料里含有什么。"}, {"text": "他们制定了一个详细的就里。", "explanation": "这里应该用〈计划〉。就里是没有说出的内情，不指可以制定的计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“其中的就里”指没有说出的内情，与句意一致。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装是事物的外在部分，不是可以说出的内情。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料与“没有说出”的情况无关，句子说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是测量得出的数值，“说出其中的体温”搭配不当。"}], "explanations": {"就里": "正确：“其中的就里”指没有说出的内情，与句意一致。", "包装": "语义：包装是事物的外在部分，不是可以说出的内情。", "颜料": "语义：颜料与“没有说出”的情况无关，句子说不通。", "体温": "搭配：“体温”是测量得出的数值，“说出其中的体温”搭配不当。"}, "sentence_index": 6, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的就里很精彩。", "explanation": "这里应该用〈内容〉。就里指没有说出的内情，不用来评价书的精彩程度。"}, {"text": "他说话的就里很温和。", "explanation": "这里应该用〈语气〉。就里是内情，不用来描述说话的语气。"}, {"text": "这座城市的就里很悠久。", "explanation": "这里应该用〈历史〉。就里指内情，不指城市历史的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
