INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿着东西，或者领着人，一起走到别的地方。", "primary_collocate": null, "pronunciation": "dài qù", "ipa": "taɪ̯˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "明天我会把这本书带去学校。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把孩子带去了医院。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一些水果带去朋友家。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把弟弟带去公园玩。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学生带去了图书馆。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把雨伞带去办公室。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸要把我带去海边。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己做的蛋糕带去了公司。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们别忘了把礼物带去他家。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把小狗带去了医院看病。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带去了", "label": "体标"}, {"form": "带去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿着东西或领着人一起去别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“把这本书带去学校”表示拿着书前往别的地方，与句意相符。"}, {"text": "吃去", "is_correct": false, "explanation": "语义：书不能吃，“吃去学校”与“这本书”的动作不符。"}, {"text": "扔去", "is_correct": false, "explanation": "语义：“扔”是抛掷或丢弃，不是“拿着东西一起去”的反向动作；“把这本书扔去学校”语境不合。"}, {"text": "唱去", "is_correct": false, "explanation": "语义：“唱”是发声表演，不能把书“唱去”学校，与句意不符。"}], "explanations": {"带去": "正确答案。“把这本书带去学校”表示拿着书前往别的地方，与句意相符。", "吃去": "语义：书不能吃，“吃去学校”与“这本书”的动作不符。", "扔去": "语义：“扔”是抛掷或丢弃，不是“拿着东西一起去”的反向动作；“把这本书扔去学校”语境不合。", "唱去": "语义：“唱”是发声表演，不能把书“唱去”学校，与句意不符。"}, "sentence_index": 0, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你下午把作业带去我家。", "explanation": "这里应该用〈带来〉。“我家”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}, {"text": "同事给我带去了一份文件。", "explanation": "这里应该用〈送来〉。“给我”表示朝说话人方向，应说“送来”，“带去”指离开说话人去别处。"}, {"text": "你把这本书带去我办公室吧。", "explanation": "这里应该用〈带来〉。“我办公室”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“把我带去海边”表示领着人前往别的地方，与句意相符。"}, {"text": "拿去", "is_correct": false, "explanation": "语义：“拿”只用于东西，不能把人“拿去”海边。"}, {"text": "哭去", "is_correct": false, "explanation": "语义：“哭”是不及物动词，不能以“把”字引出的人作宾语，“周末爸爸要把我哭去海边”不成立。"}, {"text": "笑去", "is_correct": false, "explanation": "语义：“笑”是不及物动词，不能把人“笑去”海边，与句意不符。"}], "explanations": {"带去": "正确答案。“把我带去海边”表示领着人前往别的地方，与句意相符。", "拿去": "语义：“拿”只用于东西，不能把人“拿去”海边。", "哭去": "语义：“哭”是不及物动词，不能以“把”字引出的人作宾语，“周末爸爸要把我哭去海边”不成立。", "笑去": "语义：“笑”是不及物动词，不能把人“笑去”海边，与句意不符。"}, "sentence_index": 6, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸出差回来，给我带去了一份礼物。", "explanation": "这里应该用〈带回〉。“给我”表示朝说话人方向，应说“带回”，“带去”指离开说话人去别处。"}, {"text": "妈妈在老家给我带去了一箱苹果。", "explanation": "这里应该用〈寄来〉。“给我”表示朝说话人方向，应说“寄来”，“带去”指离开说话人去别处。"}, {"text": "朋友从北京给我带去了一封信。", "explanation": "这里应该用〈捎来〉。“给我”表示朝说话人方向，应说“捎来”，“带去”指离开说话人去别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天把这本书带去图书馆了。", "corrected_sentence": "我明天把这本书带去图书馆。", "error_description": "时态错误：“明天”指将来，句末不能加“了”表示已完成。应说“我明天把这本书带去图书馆”，不能说“带去图书馆了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈带去地钥匙找到了。", "corrected_sentence": "妈妈带去的钥匙找到了。", "error_description": "结构助词错误：“带去”修饰名词“钥匙”，应用“的”，说“带去的钥匙”；“地”用于修饰动词、形容词，不能说“带去地钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
