INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带或领着到某处去。", "primary_collocate": null, "pronunciation": "dài qù", "ipa": "taɪ̯˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "他给病人带去了一些水果。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我从家乡带去的茶叶。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国时，我带去了很多药。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把女儿带去北京上学。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给山里的孩子带去了新书。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这封信带去给王老师。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷带去的饺子还热着。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要带去的东西都准备好了吗？", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把相机带去了海边。", "target_word": "带去", "complexity_tier": "T3", "furigana": "dài qù", "sentence_source": "generated"}, {"text": "哥哥常把朋友带去家里吃饭。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带去了", "label": "体标"}, {"form": "带去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "携带或领着到某处去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“给病人带去一些水果”表示携带物品前往病人所在的地方，与句意相符。"}, {"text": "偷去", "is_correct": false, "explanation": "语义：“偷”是暗中拿走别人的东西，与“给病人”的赠送意思相反。"}, {"text": "拿走", "is_correct": false, "explanation": "语义：“拿走”是从病人处取走，与“给”的方向相反。"}, {"text": "唱去", "is_correct": false, "explanation": "语义：“唱”是发声表演，不能把水果“唱去”病人处，与句意不符。"}], "explanations": {"带去": "正确答案。“给病人带去一些水果”表示携带物品前往病人所在的地方，与句意相符。", "偷去": "语义：“偷”是暗中拿走别人的东西，与“给病人”的赠送意思相反。", "拿走": "语义：“拿走”是从病人处取走，与“给”的方向相反。", "唱去": "语义：“唱”是发声表演，不能把水果“唱去”病人处，与句意不符。"}, "sentence_index": 0, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你晚上把钥匙带去我宿舍。", "explanation": "这里应该用〈带来〉。“我宿舍”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}, {"text": "同学给我带去一个口信。", "explanation": "这里应该用〈捎来〉。“给我”表示朝说话人方向，应说“捎来”，“带去”指离开说话人去别处。"}, {"text": "请你把书带去我办公室。", "explanation": "这里应该用〈带来〉。“我办公室”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“爷爷带去的饺子”指爷爷带着去别处的饺子，句中“还热着”与此相符。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”的饺子是冷的，与“还热着”矛盾。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”的饺子不会还是热的，与句中的“热着”矛盾。"}, {"text": "哭去", "is_correct": false, "explanation": "语义：“哭”不能带着饺子去别处，“爷爷哭去的饺子还热着”不成立。"}], "explanations": {"带去": "正确答案。“爷爷带去的饺子”指爷爷带着去别处的饺子，句中“还热着”与此相符。", "冻": "语义：“冻”的饺子是冷的，与“还热着”矛盾。", "冷冻": "语义：“冷冻”的饺子不会还是热的，与句中的“热着”矛盾。", "哭去": "语义：“哭”不能带着饺子去别处，“爷爷哭去的饺子还热着”不成立。"}, "sentence_index": 6, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐从南方给我带去了一盒茶叶。", "explanation": "这里应该用〈带回〉。“给我”表示朝说话人方向，应说“带回”，“带去”指离开说话人去别处。"}, {"text": "同事给我带去了一份文件。", "explanation": "这里应该用〈送来〉。“给我”表示朝说话人方向，应说“送来”，“带去”指离开说话人去别处。"}, {"text": "这次实验带去了意想不到的结果。", "explanation": "这里应该用〈带来〉。“带来结果”“带来变化”是固定搭配；“带去”用于把具体的人或物送往别处，不能与“结果”这样的抽象事物搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨天给朋友带去过一束花。", "corrected_sentence": "她昨天给朋友带去了一束花。", "error_description": "体标错误：说明具体的过去时间（昨天）时，应用“了”表示完成，不用“过”。应说“带去了一束花”，不能说“带去过一束花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐带去地礼物很贵。", "corrected_sentence": "姐姐带去的礼物很贵。", "error_description": "结构助词错误：名词“礼物”前的修饰语应用“的”，不用“地”。应说“带去的礼物”，不能说“带去地礼物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
