INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89616, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到影响而有所体会;心里的体验。", "primary_collocate": null, "pronunciation": "gǎn shòu", "ipa": "kan˨˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "在北京住了一年，我感受到了这里的热情。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进森林，你会感受到空气的清新。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想亲自去农村感受一下那里的生活。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在雪地里感受着冬天的快乐。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在海边，我深深感受到大海的力量。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在这里以后，我才感受过真正的安静。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，大家都感受到了他的热情。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你坐上去就能感受到这辆车有多快。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚到新学校，她就感受到了大家的友好。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有自己去试一试，才能感受到它的好。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "感受了", "label": "体标"}, {"form": "感受过", "label": "体标"}, {"form": "感受着", "label": "体标"}, {"form": "感受到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "动词：受到影响后在心里体会到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da28245a-fd37-4611-8224-e182b1da6850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感受", "is_correct": true, "explanation": "正确：“感受到”表示体会到，与“热情”搭配，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与句中体会到热情的意思相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”表示不注意，与“体会到了热情”矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是具体的东西，不能用于“热情”。"}], "explanations": {"感受": "正确：“感受到”表示体会到，与“热情”搭配，符合语境。", "拒绝": "语义：“拒绝”表示不接受，与句中体会到热情的意思相反。", "忽略": "语义：“忽略”表示不注意，与“体会到了热情”矛盾。", "修理": "搭配：“修理”的对象是具体的东西，不能用于“热情”。"}, "sentence_index": 0, "correct_answer": "感受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在雪地里感受了一只小鸟。", "explanation": "这里应该用〈看见〉。感受指体会到感觉或氛围，看到具体的鸟要用“看见”。"}, {"text": "他感受到了那棵树。", "explanation": "这里应该用〈注意〉。感受指体会到感觉或氛围，看到具体的树要用“注意到”。"}, {"text": "孩子们在雪地里有一只快乐的感受。", "explanation": "这里应该用〈种〉。感受作名词时用“种”，“只”用于动物，不能用于感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感受", "is_correct": true, "explanation": "正确：“感受到了他的热情”指体会到热情，符合语境。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是具体的东西，热情不能被咬。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”的对象是具体的东西，热情不能被摸到。"}, {"text": "撞", "is_correct": false, "explanation": "语义：“撞”表示身体碰撞，与“他的热情”的体会毫无关系。"}], "explanations": {"感受": "正确：“感受到了他的热情”指体会到热情，符合语境。", "咬": "搭配：“咬”的对象是具体的东西，热情不能被咬。", "摸": "搭配：“摸”的对象是具体的东西，热情不能被摸到。", "撞": "语义：“撞”表示身体碰撞，与“他的热情”的体会毫无关系。"}, "sentence_index": 6, "correct_answer": "感受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感受了好成绩。", "explanation": "这里应该用〈取得〉。感受的对象是感觉或体会，不能是成绩，取得成绩要用“取得”。"}, {"text": "他感受了老师的命令。", "explanation": "这里应该用〈服从〉。感受指体会到感觉或影响，对命令要说“服从”，不能用“感受”。"}, {"text": "他感受到了一块蛋糕。", "explanation": "这里应该用〈吃到〉。感受用于抽象的感觉，不能接具体的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在新城市里感受了到温暖。", "corrected_sentence": "我在新城市里感受到了温暖。", "error_description": "结果补语“到”与“了”的顺序错误：应说“感受到了”，“了”放在“到”之后，不能说“感受了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走进花园，你会感受到到春天的气息。", "corrected_sentence": "走进花园，你会感受到春天的气息。", "error_description": "结果补语重复：“感受到”中的“到”只用一次，应说“感受到春天的气息”，不能说“感受到到春天的气息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd26e1c6-24d2-4172-b7ed-2d394db774fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧与悲剧相对，都是戏剧的类型，构成反义关系。"}, {"text": "电影", "is_correct": false, "explanation": "电影是另一种作品形式，不与悲剧构成反义。"}, {"text": "小说", "is_correct": false, "explanation": "小说是文学体裁，不是戏剧类型，与悲剧不成反义。"}, {"text": "诗歌", "is_correct": false, "explanation": "诗歌是另一种文学体裁，不是悲剧的反义词。"}], "correct_answer": "喜剧", "explanations": {"喜剧": "喜剧与悲剧相对，都是戏剧的类型，构成反义关系。", "电影": "电影是另一种作品形式，不与悲剧构成反义。", "小说": "小说是文学体裁，不是戏剧类型，与悲剧不成反义。", "诗歌": "诗歌是另一种文学体裁，不是悲剧的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧与悲剧相对，都是戏剧的类型，构成反义关系。"}, {"text": "绘画", "is_correct": false, "explanation": "绘画是视觉艺术，不是戏剧类型，与悲剧不成反义。"}, {"text": "歌曲", "is_correct": false, "explanation": "歌曲是音乐作品，不与悲剧构成反义。"}, {"text": "散文", "is_correct": false, "explanation": "散文是文学体裁，不是戏剧类型，与悲剧不成反义。"}], "correct_answer": "喜剧", "explanations": {"喜剧": "喜剧与悲剧相对，都是戏剧的类型，构成反义关系。", "绘画": "绘画是视觉艺术，不是戏剧类型，与悲剧不成反义。", "歌曲": "歌曲是音乐作品，不与悲剧构成反义。", "散文": "散文是文学体裁，不是戏剧类型，与悲剧不成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以主人公的不幸结局引起悲痛的戏剧；泛指不幸的事件。", "primary_collocate": null, "pronunciation": "bēi jù", "ipa": "pei˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "《哈姆雷特》是莎士比亚写的悲剧。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这出悲剧的主人公最后死了。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "希腊悲剧里的英雄常常没有好结局。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悲剧的结局让台下的观众都沉默了。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧院今晚演一出有名的悲剧。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，悲剧和喜剧的结局不一样。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战争带来的悲剧本来可以避免，可惜没有人注意。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为一次小错误，他的一生成了悲剧。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给这个国家带来了很多悲剧。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢看古典悲剧，不喜欢看现代戏剧。", "target_word": "悲剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一出悲剧", "label": "量词"}, {"form": "一部悲剧", "label": "量词"}, {"form": "悲剧性", "label": "复合"}, {"form": "悲劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "结局不幸的戏剧，也泛指不幸的事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20c5325b-005c-476c-b1df-5f348cdc042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悲剧", "is_correct": true, "explanation": "悲剧是戏剧的一种，《哈姆雷特》就是莎士比亚写的悲剧，句意相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：莎士比亚写的是剧作，不是菜谱。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“写”的对象是文字作品，不说“写电脑”。"}, {"text": "药方", "is_correct": false, "explanation": "语义：《哈姆雷特》是戏剧，不是医生开的药方。"}], "explanations": {"悲剧": "悲剧是戏剧的一种，《哈姆雷特》就是莎士比亚写的悲剧，句意相符。", "菜谱": "语义：莎士比亚写的是剧作，不是菜谱。", "电脑": "搭配：“写”的对象是文字作品，不说“写电脑”。", "药方": "语义：《哈姆雷特》是戏剧，不是医生开的药方。"}, "sentence_index": 0, "correct_answer": "悲剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场演出是一出快乐的悲剧，观众都很高兴。", "explanation": "这里应该用〈喜剧〉。悲剧以不幸结局引起悲痛，“快乐”的戏应称喜剧，“快乐的悲剧”自相矛盾。"}, {"text": "这出悲剧的主人公最后结婚了，大家都很开心。", "explanation": "这里应该用〈喜剧〉。悲剧的结局是不幸的，主人公结婚是喜事，应用喜剧。"}, {"text": "这出悲剧让全场观众笑个不停。", "explanation": "这里应该用〈戏〉。悲剧以不幸结局引起悲痛，不会让观众笑个不停。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲剧", "is_correct": true, "explanation": "悲剧指不幸的事情，与“可以避免”“可惜没人注意”相符。"}, {"text": "演出", "is_correct": false, "explanation": "语义：演出是预先安排的活动，不是需要避免的不幸事件。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“避免”多接不幸的事件，不说避免“婚礼”，句意不通。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是娱乐活动，不是需要避免的不幸，与“没人注意”也不搭。"}], "explanations": {"悲剧": "悲剧指不幸的事情，与“可以避免”“可惜没人注意”相符。", "演出": "语义：演出是预先安排的活动，不是需要避免的不幸事件。", "婚礼": "搭配：“避免”多接不幸的事件，不说避免“婚礼”，句意不通。", "晚会": "语义：晚会是娱乐活动，不是需要避免的不幸，与“没人注意”也不搭。"}, "sentence_index": 6, "correct_answer": "悲剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这出悲剧的结局很圆满，大家都笑了。", "explanation": "这里应该用〈闹剧〉。悲剧的结局不幸，“圆满”而让人发笑的是闹剧，不能用“悲剧”。"}, {"text": "他随口开了一个悲剧，大家都笑了。", "explanation": "这里应该用〈玩笑〉。“开”搭配“玩笑”，不能说“开悲剧”。"}, {"text": "这个悲剧让观众大笑不止，演完后大家都很开心。", "explanation": "这里应该用〈节目〉。悲剧令人悲痛，不会让观众大笑不止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚这个剧院要演一首悲剧，票很难买。", "corrected_sentence": "今晚这个剧院要演一出悲剧，票很难买。", "error_description": "量词错误：演出的戏剧应用“出”或“部”计量，“首”用于诗词歌曲，应说“一出悲剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的人生是一场悲剧性，大家都很同情他。", "corrected_sentence": "他的人生是一场悲剧，大家都很同情他。", "error_description": "词形错误：“悲剧性”是性质词，不能放在“一场”之后作名词，应说“一场悲剧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
