INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻挡是把路拦住，不让人或东西过去。", "primary_collocate": null, "pronunciation": "zǔ dǎng", "ipa": "tsu˨˩˦ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "一辆大车阻挡了前面的路。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察在路口阻挡行人过去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大树倒在路上，阻挡了汽车。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手阻挡前面的人。", "target_word": "阻挡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大门前的石头阻挡着汽车进去。", "target_word": "阻挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安站在门口阻挡陌生人进去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪阻挡了回家的路。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几只羊阻挡了车子过去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸开手臂，阻挡球飞过来。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把大石头放在路中间阻挡车辆。", "target_word": "阻挡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻挡了", "label": "体标"}, {"form": "阻挡着", "label": "体标"}, {"form": "阻挡过", "label": "体标"}], "register": "中性", "sense_fingerprint": "阻挡：拦住道路，不让人或物通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "阻挡：拦住道路，使车辆不能通过，与“一辆大车”和“前面的路”的情境相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”的对象须是人，不能说帮助前面的路。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”需要有人作为对象，路不能被欢迎。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“前面的路”作宾语。"}], "explanations": {"阻挡": "阻挡：拦住道路，使车辆不能通过，与“一辆大车”和“前面的路”的情境相符。", "帮助": "语义：“帮助”的对象须是人，不能说帮助前面的路。", "欢迎": "语义：“欢迎”需要有人作为对象，路不能被欢迎。", "散步": "配价：“散步”是不及物动词，不能带“前面的路”作宾语。"}, "sentence_index": 0, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他阻挡了一场电影。", "explanation": "这里应该用〈看〉。阻挡指挡住去路，电影不能被阻挡，应说“看一场电影”。"}, {"text": "我们要阻挡事故的发生。", "explanation": "这里应该用〈防止〉。阻挡针对有形的通路，事故的发生要用防止。"}, {"text": "他阻挡了一支歌。", "explanation": "这里应该用〈唱〉。阻挡指挡住去路，歌不能被阻挡，应说“唱一支歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "阻挡：挡住去路，与“大雪”和“回家的路”的情境相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”的主语须是有感情的人，大雪不能怀念回家的路。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”的对象须是人或动物，不能照顾一条路。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”多用于庄稼或成果，不能说收获“回家的路”。"}], "explanations": {"阻挡": "阻挡：挡住去路，与“大雪”和“回家的路”的情境相符。", "怀念": "语义：“怀念”的主语须是有感情的人，大雪不能怀念回家的路。", "照顾": "语义：“照顾”的对象须是人或动物，不能照顾一条路。", "收获": "搭配：“收获”多用于庄稼或成果，不能说收获“回家的路”。"}, "sentence_index": 6, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他阻挡了一盘菜。", "explanation": "这里应该用〈做〉。阻挡指挡住去路，菜不能被阻挡，应说“做一盘菜”。"}, {"text": "老师要阻挡学生的错误。", "explanation": "这里应该用〈纠正〉。阻挡指挡住有形的去路，改正学生的错误要用纠正。"}, {"text": "他阻挡了一张照片。", "explanation": "这里应该用〈拍〉。阻挡指挡住去路，照片不能被阻挡，应说“拍一张照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堵墙阻挡了住风沙。", "corrected_sentence": "这堵墙阻挡住了风沙。", "error_description": "错误：“阻挡了住”。结果补语“住”要紧跟动词，应为“阻挡住了”，表示墙把风沙挡住了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没有阻挡了他的去路。", "corrected_sentence": "我们没有阻挡他的去路。", "error_description": "体标错误：“没有”表示否定，与“了”不能同用，应说“没有阻挡他的去路”，不能说“没有阻挡了他的去路”。错误在“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
