INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89626, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使前进的人或事物无法通过或发展。", "primary_collocate": null, "pronunciation": "zǔ dǎng", "ipa": "tsu˨˩˦ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "困难不能阻挡我们前进。", "target_word": "阻挡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有什么能阻挡他实现梦想。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨阻挡了球迷去体育场的路。", "target_word": "阻挡", "complexity_tier": "T3", "furigana": "dà yǔ zǔ dǎng le qiú mí qù tǐ yù chǎng de lù 。", "sentence_source": "generated"}, {"text": "父母不想阻挡孩子去外地工作。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也阻挡不了科学的发展。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语言不同没有阻挡他们成为好朋友。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的决心很大，别人阻挡不住她。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学画画，没人能阻挡他。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要让小事阻挡你学习。", "target_word": "阻挡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过去的失败曾经阻挡着他，现在他不怕了。", "target_word": "阻挡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻挡了", "label": "体标"}, {"form": "阻挡着", "label": "体标"}, {"form": "阻挡过", "label": "体标"}], "register": "中性", "sense_fingerprint": "阻挡：使前进或发展受阻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "正确：“阻挡”表示使前进受阻，与“困难不能……我们前进”相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“困难不能帮助我们前进”与“困难”的语义相矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”后接人或事物，不能接“前进”作宾语，搭配不当。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“困难不能鼓励我们前进”与“困难”的常见语义相悖。"}], "explanations": {"阻挡": "正确：“阻挡”表示使前进受阻，与“困难不能……我们前进”相符。", "帮助": "语义：“困难不能帮助我们前进”与“困难”的语义相矛盾。", "欢迎": "搭配：“欢迎”后接人或事物，不能接“前进”作宾语，搭配不当。", "鼓励": "语义：“困难不能鼓励我们前进”与“困难”的常见语义相悖。"}, "sentence_index": 0, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我阻挡了这顿晚饭。", "explanation": "这里应该用〈吃〉。阻挡的对象是阻碍前进的人或事物，晚饭不能被阻挡，应说“吃完这顿晚饭”。"}, {"text": "这个消息阻挡了我的高兴。", "explanation": "这里应该用〈分享〉。阻挡只用于阻碍前进的人或事物，感情不能被阻挡；高兴应说“分享我的高兴”。"}, {"text": "他阻挡了我的话，我很生气。", "explanation": "这里应该用〈打断〉。打断指中途插话，阻挡只用于阻碍前进的人或事物，不说阻挡话语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "正确：“阻挡不住她”表示别人拦不住她，与“她的决心很大”相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸不住她”不成立，与“她的决心很大”的语义不符。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶不住她”只是身体上的扶持，与“决心很大”的语义不符。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”的对象是物品，不能收藏“她”，与“决心很大”的语境无关。"}], "explanations": {"阻挡": "正确：“阻挡不住她”表示别人拦不住她，与“她的决心很大”相符。", "夸": "语义：“夸不住她”不成立，与“她的决心很大”的语义不符。", "扶": "语义：“扶不住她”只是身体上的扶持，与“决心很大”的语义不符。", "收藏": "语义：“收藏”的对象是物品，不能收藏“她”，与“决心很大”的语境无关。"}, "sentence_index": 6, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他努力阻挡心中的愤怒，没有发火。", "explanation": "这里应该用〈抑制〉。抑制指压住情绪，阻挡一般指阻碍前进，不用于情绪。"}, {"text": "他努力阻挡住了一个笑话。", "explanation": "这里应该用〈讲〉。阻挡的是阻碍前进的人或事物，笑话不能被阻挡，应说“讲一个笑话”。"}, {"text": "他终于阻挡了过去的失败。", "explanation": "这里应该用〈克服〉。失败要克服，不能阻挡，阻挡不用于失败。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "困难阻挡了的我们前进。", "corrected_sentence": "困难阻挡了我们前进。", "error_description": "错误：“阻挡了”之后不能直接接“的”，“了的我们”结构不成立。应删去多余的“的”，为“困难阻挡了我们前进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有人能阻挡的住她的脚步。", "corrected_sentence": "没有人能阻挡得住她的脚步。", "error_description": "补语标记错误：可能补语应用“得”，不能用“的”。应说“阻挡得住她的脚步”，错误在“的”，正确形式为“得住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
