INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89629, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对不好的事或服务，去告诉管事的人。", "primary_collocate": null, "pronunciation": "tóu sù", "ipa": "tʰou̯˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "菜里有头发，我去找经理投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员态度很差，客人投诉了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要投诉这个服务员。", "target_word": "投诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客人对服务不满意，向老板投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等了一个小时，他生气地投诉了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他叫来经理，要投诉刚才的服务。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜太咸了，我要向经理投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要是不满意，可以向前台投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她投诉过那家酒店的清洁问题。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间太吵的事向前台投诉了。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投诉了", "label": "体标"}, {"form": "投诉过", "label": "体标"}, {"form": "投诉电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "投诉：对不好的服务告诉管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：对不好的服务去告诉管事的人，与“菜里有头发”的情境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”针对做得好的事，菜里有头发时不能去找经理表扬。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：“鼓掌”表示赞赏，与菜里有头发的情境相反。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”是不及物动词，不能表示去找经理提意见的动作。"}], "explanations": {"投诉": "投诉：对不好的服务去告诉管事的人，与“菜里有头发”的情境相符。", "表扬": "语义：“表扬”针对做得好的事，菜里有头发时不能去找经理表扬。", "鼓掌": "语义：“鼓掌”表示赞赏，与菜里有头发的情境相反。", "洗澡": "配价：“洗澡”是不及物动词，不能表示去找经理提意见的动作。"}, "sentence_index": 0, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向经理投诉这场晚会的节目太精彩。", "explanation": "这里应该用〈称赞〉。投诉针对不好的事，节目精彩是好事，应说“称赞”。"}, {"text": "我向银行投诉了贷款。", "explanation": "这里应该用〈申请〉。投诉指表达不满，办理贷款要用申请。"}, {"text": "我向老板投诉加薪。", "explanation": "这里应该用〈请求〉。投诉指表达不满，提出加薪的要求要用请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：向管事的人说明不满，与“菜太咸了，我要向经理投诉”的语境相符。"}, {"text": "订票", "is_correct": false, "explanation": "语义：“订票”与菜太咸的反映无关，句中没有订票的情境。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与向经理反映菜太咸的情境不符。"}, {"text": "投票", "is_correct": false, "explanation": "搭配：“投票”的对象是候选人或提案，不能用于向经理反映菜的问题。"}], "explanations": {"投诉": "投诉：向管事的人说明不满，与“菜太咸了，我要向经理投诉”的语境相符。", "订票": "语义：“订票”与菜太咸的反映无关，句中没有订票的情境。", "游泳": "语义：“游泳”与向经理反映菜太咸的情境不符。", "投票": "搭配：“投票”的对象是候选人或提案，不能用于向经理反映菜的问题。"}, "sentence_index": 6, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把全部精力投诉到工作中。", "explanation": "这里应该用〈投入〉。投诉指向有关部门表达不满，把精力放到某件事上要用投入。"}, {"text": "小明向池塘里投诉了一块石头。", "explanation": "这里应该用〈投掷〉。投诉指表达意见，把东西扔出去要用投掷。"}, {"text": "球员在比赛中投诉了三个球。", "explanation": "这里应该用〈投进〉。投诉指表达不满，把球投进篮筐要用投进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没投诉了，服务员很快道歉了。", "corrected_sentence": "我没投诉，服务员很快道歉了。", "error_description": "错误：“没投诉了”。“没”否定已发生或未发生的动作时不与“了”同用，应为“没投诉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想经理投诉。", "corrected_sentence": "我想向经理投诉。", "error_description": "错误：“我想经理投诉”。投诉的对象前要加介词“向”，应为“我想向经理投诉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
