INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关部门申诉意见或不满。", "primary_collocate": null, "pronunciation": "tóu sù", "ipa": "tʰou̯˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "他向消费者协会投诉了这家店。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以打电话投诉。", "target_word": "投诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买到坏东西，可以向市场管理部门投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居天天很吵，我已经向物业投诉了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他投诉过这家公司三次。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人向有关部门投诉这家工厂的噪音。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅客向航空公司投诉行李丢了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人投诉这家饭店太脏。", "target_word": "投诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她写信向教育局投诉这所学校。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长们到市政府投诉老师乱收费。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "投诉了", "label": "体标"}, {"form": "投诉过", "label": "体标"}, {"form": "投诉电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "投诉：向有关部门申诉意见或不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：向有关部门反映不满，与“消费者协会”和不满的情境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理场所的动作，不能向协会去打扫一家店。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：“批发”用于成批卖出的货物，不能说批发一家店。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能用来说对现成的店。"}], "explanations": {"投诉": "投诉：向有关部门反映不满，与“消费者协会”和不满的情境相符。", "打扫": "语义：“打扫”是清理场所的动作，不能向协会去打扫一家店。", "批发": "搭配：“批发”用于成批卖出的货物，不能说批发一家店。", "发明": "语义：“发明”指创造新事物，不能用来说对现成的店。"}, "sentence_index": 0, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向教育局投诉了一位好老师。", "explanation": "这里应该用〈表扬〉。投诉表示对不好的事申诉不满，称赞好老师要用表扬。"}, {"text": "他向银行投诉了贷款。", "explanation": "这里应该用〈申请〉。投诉指表达不满，办理贷款要用申请。"}, {"text": "我向老师投诉，作业已经全部做完了。", "explanation": "这里应该用〈报告〉。投诉指对不满的事表达意见，中性地说明作业完成的情况要用报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：向有关部门反映不满，与“航空公司”和“行李丢了”的情境相符。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”的宾语须是人或权利，不能用于“行李丢了”这件事。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”的对象是文字或文件，不能删除“行李丢了”。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能说收割行李。"}], "explanations": {"投诉": "投诉：向有关部门反映不满，与“航空公司”和“行李丢了”的情境相符。", "尊重": "语义：“尊重”的宾语须是人或权利，不能用于“行李丢了”这件事。", "删除": "语义：“删除”的对象是文字或文件，不能删除“行李丢了”。", "收割": "搭配：“收割”的对象是庄稼，不能说收割行李。"}, "sentence_index": 6, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把全部精力投诉到学习中。", "explanation": "这里应该用〈投入〉。投诉指向有关部门表达不满，把精力放到某件事上要用投入。"}, {"text": "小明向池塘里投诉了一块石头。", "explanation": "这里应该用〈投掷〉。投诉指表达意见，把东西扔出去要用投掷。"}, {"text": "球员在比赛中投诉了三个球。", "explanation": "这里应该用〈投进〉。投诉指表达不满，把球投进篮筐要用投进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想向物业投诉了楼下的噪音。", "corrected_sentence": "我想向物业投诉楼下的噪音。", "error_description": "错误：“投诉了”。“想”表示打算，动作尚未发生，不能加“了”，应为“我想向物业投诉楼下的噪音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以向平台投诉了这家网店。", "corrected_sentence": "我们可以向平台投诉这家网店。", "error_description": "错误：“投诉了”。“可以”表示可能或许可，动作尚未完成，不能在动词后加“了”，应为“我们可以向平台投诉这家网店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
