INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去把很多东西买回来。", "primary_collocate": null, "pronunciation": "cǎi gòu", "ipa": "tsʰai˨˩˦ kou˥˩", "syllable_count": 2, "sentences": [{"text": "过年前，妈妈去超市采购年货。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一起去市场采购蔬菜和水果。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开车去城里采购了很多东西。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出门采购了好多要用的东西。", "target_word": "采购", "complexity_tier": "T3", "furigana": "cǎi gòu", "sentence_source": "generated"}, {"text": "旅行前，我们采购了很多吃的。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶一早出门，去采购今天要做饭的菜。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有客人来，我得去采购一些东西。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个星期天都采购一周要吃的东西。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的商店很远，我们先采购好食物再上山。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了开学，家长带孩子去采购书包和本子。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采购了", "label": "体标"}, {"form": "采购过", "label": "体标"}, {"form": "採購", "label": "繁体"}], "register": "中性", "sense_fingerprint": "出门一次买回很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20c5325b-005c-476c-b1df-5f348cdc042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与买年货无关。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是器物，不说修年货。"}, {"text": "采购", "is_correct": true, "explanation": "正确：采购指出门一次买回很多东西，与“过年前去超市买年货”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，不能用来表示购买年货。"}], "explanations": {"唱": "语义：“唱”指发出歌声，与买年货无关。", "修": "搭配：“修”的对象是器物，不说修年货。", "采购": "正确：采购指出门一次买回很多东西，与“过年前去超市买年货”相符。", "写": "语义：“写”指书写文字，不能用来表示购买年货。"}, "sentence_index": 0, "correct_answer": "采购"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书架上采购了很久的字典。", "explanation": "这里应该用〈找〉。采购是去买东西，在书架上寻找东西要用找。"}, {"text": "她从冰箱里采购了一瓶水。", "explanation": "这里应该用〈拿〉。采购是花钱买东西，从冰箱里取出东西要用拿。"}, {"text": "她向邻居采购了一把伞，邻居说不用给钱。", "explanation": "这里应该用〈借〉。采购是花钱买东西，不用给钱就应是借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演", "is_correct": false, "explanation": "搭配：“演”要求表演或扮演，不能说演东西去买。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，与去买东西无关。"}, {"text": "采购", "is_correct": true, "explanation": "正确：采购指出门买回很多东西，与“明天有客人来，要去买一些东西”相符。"}, {"text": "弹", "is_correct": false, "explanation": "语义：“弹”指拨动或弹出，与购物无关。"}], "explanations": {"演": "搭配：“演”要求表演或扮演，不能说演东西去买。", "讲": "语义：“讲”指说话，与去买东西无关。", "采购": "正确：采购指出门买回很多东西，与“明天有客人来，要去买一些东西”相符。", "弹": "语义：“弹”指拨动或弹出，与购物无关。"}, "sentence_index": 6, "correct_answer": "采购"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去银行采购了一笔钱。", "explanation": "这里应该用〈取〉。采购是买东西，从银行拿出钱要用取。"}, {"text": "他去邮局采购了一个包裹。", "explanation": "这里应该用〈寄〉。采购是买，寄包裹是把东西送出去，要用寄。"}, {"text": "我们把屋里的垃圾采购出去了。", "explanation": "这里应该用〈清理〉。采购是买东西，把垃圾清理出去要用清理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们去超市采购了一只零食。", "corrected_sentence": "周末我们去超市采购了一包零食。", "error_description": "量词错误：“只”用于动物或单个物件，零食应用量词“包”。应说“采购了一包零食”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天去商场采购过一些衣服。", "corrected_sentence": "我们明天去商场采购一些衣服。", "error_description": "体标错误：“明天”是将来的事，不能用经历体“过”，应去掉“过”，说“采购一些衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
